/* 令和6年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r06.committeeSessions.push(...[{"id":"r06-20240227-7","meetingId":"r06-cm02","date":"2024年2月27日","dateIso":"2024-02-27","committee":"厚生委員会","time":"午前１０時００分～午後 ３時１３分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を100件抜き出しています。","topics":[{"id":"topic-01","title":"令和６年陳情第１５号、八潮南特別養護老人ホームの改築にあわせて入浴設備のあるシルバーセンターの整備を求める陳情","agenda":"令和６年陳情第１５号、八潮南特別養護老人ホームの改築にあわせて入浴設備のあるシルバーセンターの整備を求める陳情","exchanges":[{"speaker":"おぎの委員","kind":"質問","question":"幾つかお伺いしたいと思いますが、まずは今、こちら八潮地域センターの状況についてお聞きします。","respondent":"川原高齢者地域支援課長","answer":"細かい利用稼働率等については、申し訳ありません、所管が異なるところで、詳しいところは把握していないところではあるのですけれども、八潮地域センターに敬老室というお部屋が３部屋ございまして、日中に関しては高齢者に限定して、優先して利用していただいているところです。","id":"exchange-001"},{"speaker":"おぎの委員","kind":"質問","question":"そのバスは、一応目の前にバス停があるということです。増設計画の進行状況と、実際、配管をしなければいけないといったお話、今ありましたけれども、実際ハード面でこれを整備するのは難しいのでしょうか。","respondent":"東野福祉計画課長","answer":"進行状況ですが、現在、実施計画を今年度進めておりまして、今年度末で終了というような予定となっています。来年度後期ぐらい、準備が出来次第ということになりますけれども、建物の工事の説明会と工事に入っていくというような予定となっております。","id":"exchange-002"},{"speaker":"おぎの委員","kind":"質問","question":"荷重がかかるということで、２階の設備のようですが、１階は今もピッコロが入っていると思うのですが、そちらは今後も変わりないのでしょうか。","respondent":"東野福祉計画課長","answer":"改修した後に、重症心身障害者通所事業所ピッコロが入るというような予定になっておりまして、どうしても、施設の入所される方の状況を考えたときに、１階が望ましいというようなところがありますので、それを変えるという予定は今のところございません。","id":"exchange-003"},{"speaker":"ひがし委員","kind":"意見","question":"それはなぜかというと、今までの陳情を見させていただいたのですが、様々、八潮の地区に入浴施設またシルバーセンターをというような文言の陳情が幾つか出されていて、今回はこの改築に伴ってというところで、当てて出されたのかなというふうに思うのですけれど、ここの今の施設だと２階部分で荷重の問題だったり、配管の問題上難しいというのは、冒頭で聞いて分かったのですが。","respondent":"東野福祉計画課長","answer":"その段階でも私のほうから、現状の施設の中で造っていくことについては、はっきりとしたことはその段階では申し上げていませんけれども、八潮地域全体の中で、何かしら区として考えていくことができるか、改めて検討させてくださいということでのお話をしています。","id":"exchange-004"},{"speaker":"ひがし委員","kind":"質問・要望","question":"区民の方々、その八潮にお住まいの方々の声というのをしっかり聞いて、どこかで八潮の方々が利用できるような施設の整備というのは、改めて求めします。","respondent":"東野福祉計画課長","answer":"昨年の第２回定例会でも、議会を通しまして要望いただきました。昨年１１月２２日に、八潮みらい懇談会のほうにお邪魔いたしまして、こちらの八潮南特別養護老人ホームの施設計画について、改めて説明をさせていただきました。","id":"exchange-005"},{"speaker":"ひがし委員","kind":"質問・要望","question":"懇談会だったりとか、その計画の説明会の段階で、その地域に住まわれている方々の要望というのも、引き続きしっかりと聞いていただければなというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"鈴木委員","kind":"質問・要望","question":"その入浴設備に対しては、区としては今後どういうふうに整備をしていこうとしているのか、それとも、設備については考えてもいないということなのか、区の入浴設備の、これだけニーズがあるということを分かっていながら、どう考えているのかというところを伺いたいと思います。","respondent":"川原高齢者地域支援課長、東野福祉計画課長","answer":"シルバーセンターは、新たに設置というところではなく、より多くの、例えば高齢者の見守りということで若い世代の方も一緒に使っていただいたりですとか、ゆうゆうプラザであるとか、多世代交流というところに。八潮南特別養護老人ホーム増設の際のシルバーセンターの検討ですが、今、高齢者地域支援課長のほうからもお話がありましたとおり、シルバーセンターの目的として、高齢者の生きがいづくりや市民活動の場としての。","id":"exchange-007"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そういうところで、ゆうゆうプラザとしてでも、そのシルバーセンターの機能を備えた上に、さらに多世代交流というのが加わるということなので、全然その八潮のこの陳情の皆さんも、シルバーセンターだけ造ってくださいというのではなくて、ゆうゆうプラザという形でもいいので、入浴施設のある、そういう形を造ってくださいというのが要望だと思うのです。","respondent":"川原高齢者地域支援課長","answer":"区として、もちろん福祉の増進であるとか高齢者の皆様の生きがいの支援というところでは積極的に施策を推進していく必要はあるのですけれども、介護予防ですとか認知症予防であったり、そういった事業の充実というのも八潮地区でも図らせていただいているところですので。","id":"exchange-008"},{"speaker":"鈴木委員","kind":"質問","question":"あそこで今、１万５,０００人ぐらいですか、人口があるわけではないですか。やはり、一気につくられたまちというふうなところでの特有なものがあると思うのですが、そういう点ではやはり、行政としてあのまちをつくってきたわけですから、この内陸部とできる限り差のないような形での条件をつくっていくというのはすごく重要なことだと思うのです。","respondent":"東野福祉計画課長、川原高齢者地域支援課長","answer":"八潮地区につきましては、区としましては、昨年１１月に、八潮五丁目地区のまちづくりガイドラインというものを策定いたしまして、区が八潮地区をどう考えていくか、住民の皆さんと一緒に。ただ、東品川ゆうゆうプラザだけに特化して人数が多い理由がございまして、他のシルバーセンターもしくはゆうゆうプラザに入浴施設があるところは、男女別で週２回の利用という形で現状はしているのですけれども。","id":"exchange-009"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そういうところで、ゆうゆうというのは多世代交流なので、子どもたちも来られる、そういう施設なので、八潮とかには特にこれだけ高齢化率が高くなったところで、若い人たちも八潮に、住み心地いいという、八潮に若い人たちに来てもらうというふうなところからも、ゆうゆうプラザはぜひ、八潮の所に造っていただきたいなというふうに思うのですけれど、ぜひそういう方針を持っていただきたいなと思うのですが。","respondent":"東野福祉計画課長","answer":"八潮南特別養護老人ホームの移設施設分ですが、そちらにつきましては、先ほどお話しさせていただきましたとおり、かなり手を入れないと、改修、例えば、荷重を考えたときの床厚ですとかそういったところ、それから配管設備、そういったところの回しですとか、それから例えば。","id":"exchange-010"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ゆうゆうプラザを八潮にも設置していきたいという、区のほうのお考えがあれば、多分、これ、もともと新たに造る場所があるわけではないですか。例えば地域センターだったりとかこみゅにてぃぷらざだったりとか、そういう施設の中で、改築に合わせてゆうゆうプラザも検討できる可能性がある場所というのはあるのか、その点も伺いたいと思います。","respondent":"東野福祉計画課長","answer":"八潮地区全体の中で、今後の区有施設を使ってという部分ですが、まだまだ区有施設、使える部分たくさんありますので、改めて老朽化してきた段階でそういったものは検討されてくるものと思われます。","id":"exchange-011"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それは強く要望しておきたいと思います。大体、シルバーセンターなどはマッサージ器なども置いてあって、自由に使えるという状況になっているではないですか。そういう、グループをつくらなければ使えないというだけではなくて、マッサージ器を置くであったりとか、そういうコミュニティーの場をつくるというのは、今の段階でも可能なのではないかなと思うのですけれど、そこら辺のところはいかがでしょうか。","respondent":"川原高齢者地域支援課長","answer":"品川区視覚障害者福祉協会のマッサージは八潮地域センターで実施をしていただいているようなところです。マッサージチェアの要望というところについては、今後も研究してまいりたいと、所管の地域センター等も含めて話をしていきたいというふうに考えてあります。","id":"exchange-012"},{"speaker":"鈴木委員","kind":"質問・要望","question":"これで終わりにします。マッサージ器とかも、本当に集える場所にもなると思うのです。それで、やはり八潮だけが行政によって格差がつけられているというのは問題だと思いますので、格差解消というところからもぜひ、ゆうゆうプラザというところは、本当にこれだけ強い要望ということなので、どうしたらできるかというふうなところでご検討いただきたいと、要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"ちょっと確認を兼ねてなのですけれども、以前からこういった八潮の入浴施設の設備とか建設への要望があったということなのですが、そういったものを踏まえた上で、こういった、八潮南特別養護老人ホームのこういう改築、増築、増設に合わせて入浴設備等を盛り込まなかったというところで、今回などは例えば、３８９名の方、全員が八潮にお住まいの方ではないかもしれないですが、陳情されているということで。","respondent":"東野福祉計画課長、川原高齢者地域支援課長","answer":"以前から陳情をいただいていたという事実はあります。区としましては、繰り返しになりますが、入浴施設のあるシルバーセンターを造るのに優先して、高齢者施設を増築するというような考えで進めてきた計画ということになります。どうしても八潮地区に関してはそのお風呂というところがメインの施設を建てるというところまではちょっと検討ができていない経緯があります。","id":"exchange-014"},{"speaker":"やなぎさわ委員","kind":"質問","question":"昭和５８年にできた八潮の団地、マンションにおいては入浴がもともとできる状態になっているのでということで、ただ、やはり、今おっしゃられたように、健康増進だとか、もしくは、入浴施設はそれこそ集いの場みたいな感じになっていて、私なんかも子どもの頃から経験ありますけれど、別に、近くの銭湯などは、家にお風呂あるないに関わらず結構いろいろな方が来られていて、私もその一人で。","respondent":"川原高齢者地域支援課長","answer":"繰り返しの答弁にはなってしまいますけれども、後期高齢者の人口の増加に伴いまして、介護予防の充実、あと認知症予防というところでも新たな事業の展開も来年度予定していますので、ここをしっかり八潮地区においても、あえて八潮を選んで新たな事業を開始する認知症予防事業も。","id":"exchange-015"},{"speaker":"やなぎさわ委員","kind":"質問","question":"つまり、今回のような入浴施設とか設置の予定はないけれども、それ以外のことで、高齢者の方に満足してもらえるというか、健康増進だったり、生きがいを持って生活できるような環境を整えていく自信があるということでよろしいですか。","respondent":"川原高齢者地域支援課長","answer":"しっかりと、気持ちだけではなくて皆様にそう思っていただけるような形で検討はしてまいりたいというふうに考えてあります。","id":"exchange-016"},{"speaker":"やなぎさわ委員","kind":"質問","question":"分かりました。これも改めてになってしまうかもしれないですけれども、ほかの、今回のこの八潮南特別養護老人ホーム以外で、別の場所で仮に使える土地というか場所があって、そこで改めて、入浴施設のあるシルバーセンターなり何なりを造ろうということは今のところは考えていないということでよろしいですか。","respondent":"東野福祉計画課長","answer":"福祉部所管としては、今のところ考えていないです。","id":"exchange-017"},{"speaker":"やなぎさわ委員","kind":"確認","question":"ちょっとうがった見方かもしれないですけれども、介護予防に力を入れて入浴施設は考えていないというのは、例えばコスト面でかかり過ぎるとか、先ほどもありましたが、入浴施設を造るのにはかなり初期投資がかかるということで、そういったことではないのですか。そこを確認させてください。別に費用面のことではなくて、区の方針として、そういった結論に至っているということでよろしいですか。","respondent":"東野福祉計画課長","answer":"先ほど、高齢者地域支援課長のほうが話しましたとおり、八潮地区全体の入浴という部分を考えたときに、自分の家での入浴が基本となっているという部分を踏まえまして、今のところ、八潮地区に浴場施設のあるシルバーセンターを造る計画はないです。","id":"exchange-018"},{"speaker":"こしば副委員長","kind":"意見","question":"結論を出すで、不採択でお願いいたします。八潮以外の地域ですと、ある一定の面積の中で町会がありますけれども、八潮ですと大体６９号棟ある中で３０ぐらいの自治会があると思います。そういう中で、自治会の中での交流するスペースを十分に確保できるかどうかということも、当然これから検討していくべき課題ではないかなということも踏まえて、今回のこの陳情には願意には添い難いと判断いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"こんの委員","kind":"意見","question":"本日結論を出すでお願いいたします。この陳情は、特別養護老人ホームの改築に合わせてというところですので、先ほどの質疑からいくと、構造上なかなかこの改築に向けては難しいというご答弁で、そこは理解できるところです。その結果、シルバーセンターというところは声がなかったということ。そうしたことも総合的に考えますと、この陳情には添い難いと結論したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"ひがし委員","kind":"質問・要望","question":"今回結論を出すでお願いいたします。しかし、八潮の高齢化率も高くなっていて、八潮にお住まいの方々の希望を計画の段階で広く拾い、安全かつ安心して利用できるような施設の整備を含めて、八潮の高齢の方々が集える場というのを増やしていただけるよう改めて求めします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"鈴木委員","kind":"質問・要望","question":"これだけ高齢化率が、全区的な２０％に対して３７.１％という突出した高齢化率にもかかわらず、大きく八潮だけが高齢者の施設がないというところでの格差は、行政として解消することが必要だと思います。これからもぜひ、ゆうゆうプラザという形でもいいので、入浴設備のある施設をぜひ造っていただきたいということで、強く要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"筒井委員","kind":"質問・要望","question":"本日結論を出すので、不採択でお願いします。なので、その八潮の住民といっても様々なご意見、ご要望があるという中、これは丁寧に検討していかなくてはいけないなと考えております。一方、地域間格差というのも残念ながら現在進んでしまっていますので、そうしたもろもろの総合的な事情を考慮した上で、その入浴設備が本当にできるのかどうかはしっかり検討していっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"おぎの委員","kind":"質問・要望","question":"本日決めるでお願いします。残念ですが不採択とします。ほかの施設へのバスのアクセスはいいとのことですが、八潮の中に造ってほしいというニーズは、長年の陳情が出ているので、そういった声はずっとあるのだなということは感じております。今回は難しくても、ぜひ、計画の段階から地域の声をよく聞いて、ゆうゆうプラザなどをこの先、整備することを検討していってほしいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"本日結論を出すで、結論としては不採択にしますけれども、理由としてはやはり、八潮南の特別養護老人ホームに今から造るということが難しいというところと、あとはやはり、八潮みらい懇談会で要望がなかったというところ、ちょっと気になっていて、その辺は私も改めて深掘りしなくてはいけないところだと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"}]},{"id":"topic-02","title":"（仮称）戸越四丁目障害者グループホームの事業者公募","agenda":"（仮称）戸越四丁目障害者グループホームの事業者公募","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"それで、前回と同じような形で、なかなかその応募がないということも考えられるのではないかと思うのですけれど、そこのところは小山七丁目のときと、こういうところが違って応募が増えるという可能性があるよというふうなところがあるのかどうか、ちょっとその点、１点伺いたいと思います。","respondent":"川崎障害者施策推進課長","answer":"戸越四丁目障害者グループホームの整備に係る説明会を１月に行わせていただきまして、委員おっしゃるとおり、地元の住民の方からもグループホーム建設について否定的な意見はございませんでした。","id":"exchange-026"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それからあと、運営費の補助というのもあるのではないかなと思うのですけれど、それも、その体制強化の補助金みたいなものもあったのですが、そういうものというのは、でもそれも何か令和５年というふうなことで書いてあったので、令和６年これからどうなるのかなという、運営そのものもすごく大変ということを伺っているので、運営に対しての補助というのはどこからも出なくて。","respondent":"川崎障害者施策推進課長","answer":"委員おっしゃる、８分の７について、令和６年度以降継続かというところについてはこちらとしても確認をします。今回、戸越四丁目につきましては定員１０人の予定で、２ユニットを予定しております。ショートは考えておりません。建築費用につきましては、今後になります。","id":"exchange-027"},{"speaker":"鈴木委員","kind":"質問","question":"そうすると、かなりその人員の配置というのもしっかりと取っていかなくてはいけないと思うのですけれど、そうすると余計に、加算とかというのもいろいろあるとは思うのですが、体制的には経営的にはなかなか厳しいというのは、ほかのグループホームの方からも伺っているのですけれど、そういうところで、区としても。","respondent":"川崎障害者施策推進課長","answer":"実務経験として、障害福祉サービスに係る実務経験が、支給対象月の前月末までに常勤換算で３年以上ある者となっております。助成額としては月額１０万円です。１グループホームにつき２名を上限として、この助成は行います。","id":"exchange-028"},{"speaker":"鈴木委員","kind":"質問・要望","question":"実際にこの補助金を受けているグループホームというのは、品川区では何件くらいあるのか伺いたいと思います。本当に、グループホーム、これからもっともっと造っていくという方針だと思うのですけれど、かなり厳しいというのが実態だと思いますので、そこはぜひ充実をさせていただきたいと思います。何件くらいがこの有資格者配置助成というのを受けているのか、そのことだけ教えてください。","respondent":"川崎障害者施策推進課長","answer":"有資格者配置助成につきましては、こちら障害者支援課で管理している件数になります。申し訳ございません、本日はこちらでは分かりかねます。","id":"exchange-029"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それは本当に問題だなと思っていまして、資格のところをしっかりと規定していただきたいなと、私はずっと思っているのですけれど、品川区が、看護師や精神保健福祉士や心理士などにそういう支援するというのはすごく大事なことだなというふうに思っています。ぜひ、これがどんどん活用されるような、そういう配置の方向を目指して、実際に助成もしていただきたいということでお願いをしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"おぎの委員","kind":"質問","question":"私のほうからは１点だけお聞きします。私もこちら住民説明会のほう出させていただきまして、資料が、想定人数１０名程度ということですが、この１０名の内訳は特に、軽度とか重症度としてはどういった方を想定しているというのは、現段階ではあるのでしょうか。","respondent":"川崎障害者施策推進課長","answer":"現在、区としては、中重度の方の受入れを想定しております。","id":"exchange-031"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ちょっと障害者の方々からご意見を伺っていまして、出石つばさの家の施設、私たちも先日、開所式に出させていただいて、その後見せていただいて、私たちとしてはすごくいい施設だなというので回りながら見せていただいたところなのですけれど、障害者の方々が実際に見学したときに、様々、構造上、本当にちょっと細かなところなのですが、もっとここがこうなったらもっといいのにというところが。","respondent":"川崎障害者施策推進課長","answer":"民間事業者のほうでも、こういった方々の声をお伺いするようなことは今後、住民説明会を通してお声を伺うような機会もあるかとは思いますし、私どもも障害福祉計画の策定において、団体のほうからもいろいろな意見、相談なども聞いておりますので、そういったものを加味しながら。","id":"exchange-032"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ぜひ、設計の段階から、出来上がってからではもう遅いので、出来上がる前の設計の段階から当事者の意見を聞いていただきたいということで、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"}]},{"id":"topic-03","title":"西五反田シルバーセンターの改築","agenda":"西五反田シルバーセンターの改築","exchanges":[{"speaker":"鈴木委員","kind":"確認","question":"これは、シルバーセンターの改築ということですけれど、シルバーセンターのままでゆうゆうプラザにはならないということなのでしょうか。ちょっとその確認。","respondent":"川原高齢者地域支援課長","answer":"シルバーセンターはゆうゆうプラザとしても運営するのかですが、その辺りの機能、あと運営の中身も含めましてこれから検討するところですが、現在のところはここの資料に記載のとおり。","id":"exchange-034"},{"speaker":"鈴木委員","kind":"意見","question":"このシルバーセンター、今のところはまだ、介護予防の総合事業ですよね。デイサービスではなくて運動の総合支援のところでのそういう介護予防というふうなところは、今まではやってないけれども、今度新しく改築した後には介護予防が入るということなのですね。","respondent":"川原高齢者地域支援課長","answer":"現在のところは、おっしゃっていただいた、恐らく総合事業とか地域ミニデイのことだと思いますけれども、そこの実施はしておりません。今後、介護予防事業を機能の検討という中で出ていた形のものを取り込むかというのはこれから検討していくところです。","id":"exchange-035"}]},{"id":"topic-04","title":"専決処分の報告について（報告第１号）","agenda":"専決処分の報告について（報告第１号）","exchanges":[{"speaker":"鈴木委員","kind":"意見","question":"それなので、改めてこの自転車の乗り方の安全運転の指導というか教育というのは、私たちもそうなのですけれど、どこかで学んで徹底することが必要ではないかなというふうな思いがしているのですが、そういった意味では品川区としては、こういう今回の報告とかも含めて、どういうふうにその職員に対しての自転車の安全運転の徹底というのはされているのか、その点をお聞かせいただけたらと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-036"},{"speaker":"こんの委員","kind":"質問","question":"すみません、先ほど私が聞き間違えていたらご指摘ください。先ほどのご説明の中に、報告書に記載のとおりですというお言葉があったと思うのですけれども、この報告書というのは私たちが見えるものなのでしょうか。その点だけ教えてください。","respondent":"菅野高齢者福祉課長","answer":"失礼いたしました。私の表現が悪かったので、議案の報告第１号の部分の記載のところということで申し上げたつもりでしたので、申し訳ございません。","id":"exchange-037"},{"speaker":"筒井委員","kind":"意見","question":"事故から１月１２日ということで、４か月ぐらいたって決定されたということで、これは警察なども最初から入って、双方もいろいろ交渉されたかと思うのですけれども、警察が入っていたのかということと、ちょっと簡単に交渉の状況というのをお知らせいただけると幸いです。","respondent":"菅野高齢者福祉課長","answer":"その後、相手方もけがをした、当方もこちらもけがをしたのですけれども、そういったところもございましたので、損害賠償の部分について保険会社等も確認しながら交渉を進めさせていただいて、やっと和解と損害賠償額が決定したというところで。","id":"exchange-038"},{"speaker":"筒井委員","kind":"質問","question":"民事でこういうように示談になったので、刑事事件には特にはならなかったということでよろしいですか。","respondent":"菅野高齢者福祉課長","answer":"委員おっしゃるとおり、民事で解決したと捉えております。","id":"exchange-039"}]},{"id":"topic-05","title":"品川区第三期データヘルス計画・品川区第四期国保基本健診等実施計画","agenda":"品川区第三期データヘルス計画・品川区第四期国保基本健診等実施計画","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"１７ページのところに評価方法というのがありまして、３ページのデータヘルス計画の「実施体制」のメンバーで、品川区データヘルス計画評価委員会を設置して、関係機関と連携して、ＰＤＣＡサイクルに沿った事業展開ができる体制を構築するということで書かれているのですけれど、この品川区のデータヘルス計画評価委員会というのは、これから設置するということなのでしょうか。","respondent":"池田国保医療年金課長","answer":"それで今後の部分ですけれども、データヘルスのこちらの策定委員会については、実際にはこれで終了という形になってまいりますが、今後の部分で検討するということで、令和６年度から毎年開催するような形になりまして、実際には。","id":"exchange-040"},{"speaker":"鈴木委員","kind":"質問・要望","question":"７６ページにある、これまではこの計画をつくってきた策定委員会が、そのままこの計画評価委員会ということで機能していくということで、この評価委員会は１年間に１回開かれて、この計画がどこまで進んでいるか、そして、課題が何か、そして。","respondent":"池田国保医療年金課長、若生健康課長","answer":"こちらのほうは、第三期のほうに向けては、こちらを課題として捉え、国保保健指導の実施体制の工夫というようなことも含めているのと、それから。一方で、がんの対策につきましては、健康課のほうでがん対策推進計画のほうで、そのがん検診ですとか予防の取組での。資料のほうにありました、７６ページのメンバーで今後の検討会を実施するのかですけれども、定数区分についてはほぼ同じ、この予定ですが、実際に。","id":"exchange-041"},{"speaker":"鈴木委員","kind":"質問","question":"がん対策はがん対策で、改めて出ているということで、ここの中には入りませんよということなのですけれど、７ページのところにも、健診受診率向上対策というところが第一に出てくるので、私はそこのところで、がん検診とか若者健診とか、そういうところを向上させていくというのも、それはそれですごく大事なのではないかなと思っていまして、そして若者健診というのはここに入ってくるのですか。","respondent":"池田国保医療年金課長、若生健康課長","answer":"若い方の受診率の向上対策ですけれど、８ページに健診受診率向上対策というところがありますが、国保の場合、特定健診というところで、若い方で４０歳からになるのですけれども、実際この方につきましては、９ページのところに。そういったところも、今後も進めていきたいと考えております。","id":"exchange-042"},{"speaker":"鈴木委員","kind":"質問・要望","question":"３８ページぐらいのところから、いろいろ行ってきたもののそれぞれの評価がついているのですけれど、Ａ評価というのは少なくてＣ評価が多いのですが、この評価というのはどう捉えたらいいのか、どこでどういうふうにしてこの評価というのがつくのか、それでＣ評価というのをどう捉えるのか、ちょっとその点もお伺いしたいと思います。","respondent":"池田国保医療年金課長","answer":"そういったものが、４４ページのほうを見ていただくと、こちらが全部まとめたところですが、Ａが目標を達成したけれども、Ｃの部分には、目標の達成は難しいけれどもある程度の効果があったなというようなことで、こういった評価をさせていただいてあります。","id":"exchange-043"},{"speaker":"ひがし委員","kind":"質問・要望","question":"教育のところなのでちょっと課が違うところもあるかもしれないのですけれども、品川区の健康に関わることですので、ぜひ今回参加されている皆さんも共に考えていただきながら、品川区の健康の部分についての対策というところ取っていただければなというふうに思いますので、この点は要望だけで大丈夫です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"おぎの委員","kind":"質問","question":"私から２点だけお伺いします。６ページのところで、一番下の医療費です。","respondent":"池田国保医療年金課長","answer":"現在のところ、重複服薬についての通知はさせていただいているところですが、その部分については、今度は多剤投薬についても広げて実施できないかということで、現在のところ細かな部分については検討させていただいているところで、こちらを実施するに当たりましては、医師会。","id":"exchange-045"},{"speaker":"おぎの委員","kind":"質問・要望","question":"高齢者におきましては、特に副作用がふらつきや目まいなど出やすくなりますので、そのふらつきの転倒がまたそのまま、骨が折れて寝たきりになってしまうという方向に行くという報告等も聞きますので、これはやはり、多剤に関しては処方する側の協力がないとどうしても減らせませんので、今回この委員会のほうも、医師会、薬剤師会、歯科医師会の先生方。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"こんの委員","kind":"質問・要望","question":"この取組の中の、健診受診率向上対策で具体的に教えていただきたいのですが、「出張！国保基本健診」の実施といったところで、出張という、過去には集団研修みたいなものをされていたというのが、この資料の中にも出てくるわけですが、具体的にどういうふうにこれを実施されていこうとお考えなのか、具体的に教えていただきたいと思います。","respondent":"池田国保医療年金課長、若生健康課長","answer":"４ページの「出張！国保基本健診」ですけれども、委員がお話をされたように、以前は集団健診という名目でさせていただいたところを、同じような形で区の施設を使っての基本健診を実施するというような形を考えているところです。国保とのというところでは、この健診を受けた方に対してどういった連携かというところは今のところないのですけれども、このデータヘルス計画についても、あるいはその国保の健診についても。","id":"exchange-047"},{"speaker":"こんの委員","kind":"質問・要望","question":"インセンティブですけれども、キャッシュレス決済サービスでどういうふうにインセンティブにしていくのかというところをもう少し詳しく教えていただけますでしょうか。","respondent":"池田国保医療年金課長、若生健康課長","answer":"ということで、今回改めて、集団健診を実施するようなことを考えているところです。もう一つ、私もちょっと言葉が足りなくて申し訳なかったのですが、キャッシュレス決済サービスでです。二十歳からの健康診査の啓発についてですが、委員ご案内のＳＮＳについては現状、そういった活用はできていないところで、そういったものも含めまして、あとは区のイベントといったところでの周知ですとか。","id":"exchange-048"},{"speaker":"こんの委員","kind":"質問・要望","question":"もう一つ、新たな質問で恐縮なのですが、医療費の適正化の取組ですけれども、これ、服用している薬を被保険者に通知していくということですが、あなたはこれだけ薬をもらっていますよ、飲んでいますよという通知なのだろうと想像するのですが、いわゆるそれをもらって、人によっては、分かっているのだけれどもお医者さんで出されてしまう、これはいいですと、自分で判別できないというか。","respondent":"池田国保医療年金課長","answer":"国保基本健診の出張のものですけれど、令和５年度については２か所を予定していますが、今後、この健診の実施具合によっては、また、拡大するかどうかということを判断させていただければというふうに考えているところです。","id":"exchange-049"},{"speaker":"こんの委員","kind":"質問・要望","question":"状況を見て、拡大をしていったほうがいい場合はそのようにしていただきたいというふうに思いますし、まずはやってみるということが大事だと思いますので、よろしくお願いします。それから、薬のほうですけれども、薬剤師会とも連携を取ってくださっているということですので、よりこれが、通知が効果的に発揮できるような形を期待したいなというふうに思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"やなぎさわ委員","kind":"確認","question":"確認なのですけれども、この健診の受診券というのは郵送で送られてくると思うのですが、それはどのタイミングというのは決まっていらっしゃるのでしょうか。","respondent":"池田国保医療年金課長","answer":"その基本健診の受診券につきましては、毎年４月の中旬にはお送りしているところでございまして、受診券が届いたら翌年の１月までが受診の期間ですということでご案内をさせていただいているところです。","id":"exchange-051"},{"speaker":"やなぎさわ委員","kind":"質問","question":"昨日の国保などの滞納者の通知などもそうなのですけれど、お話変わるのですが、何かちょっと手に取ったときに開けやすいような感じの、花柄とか分からないですけれど思わず開けてしまいたくなるようなほうがやはり、恐らくそれこそ無料で受診できるということを知らない区民の方も結構いらっしゃるのではないかなというふうに思っていて、まず、封筒を開けてもらうというところで、開けたときにそこでもう。","respondent":"池田国保医療年金課長","answer":"なおかつ受診券在中と書いてあります。中を開けますと、基本健診については８,０００円分の健診が無料にというようなことで、お得ですよというようなことも含めさせていただいてありますので、今後さらによいものがあれば記載していければと思います。","id":"exchange-052"},{"speaker":"やなぎさわ委員","kind":"質問","question":"質問で、ちょっと具体的にお伺いしたいのが、肥満者の方の対策といいますか、そういったことの取組で、資料を見て具体的なところのイメージがつかなかったのですけれど、改めてどういったことを取組されていらっしゃいますか、お伺いできればと思います。","respondent":"池田国保医療年金課長","answer":"肥満の方につきましては、国保基本健診の結果を機に、保健指導についての特定健診の通知を出させていただいておりまして、それで受診の勧奨をさせていただいているところです。","id":"exchange-053"},{"speaker":"鈴木委員","kind":"質問","question":"そういうところからすると、がんでの死亡もすごく、品川区は突出してというわけではないのですけれど東京都や国よりも多い状況になっているので、これは本当に早期発見、早期治療でかなり抑えることができるのではないかなというふうに思うと、がん対策というのは別な計画の中で示されているということなのですが、こういう医療費を押し上げるということにもなりますし、本人にとっても早期発見で済めば。","respondent":"若生健康課長","answer":"そういうところも含めまして、国保の対策とともにがん検診のほうの受診、予防に努めていただくように、健康課としても取り組んでまいりたいと考えています。","id":"exchange-054"},{"speaker":"鈴木委員","kind":"意見","question":"このがん検診を受けた結果の、要検査というのもかなりの割合で高いというのがデータでも出ていると思うのです。そういった意味では本当に、早期に健診をする中で早期発見というのがポイントかなと思いますので、その人の人生にとっても本当に大事なことだと思いますので、ぜひ、この健診をどうしたら引き上げられるかというところでは、ぜひ様々な工夫の検討をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-055"},{"speaker":"筒井委員","kind":"質問","question":"昨日もいろいろ議論がありましたけれども、やはりその国保料を下げるためにも、健康、予防というのは非常に重要でございまして、この計画というのは本当に大事なことかなと考えております。そこで、７６ページの策定委員会というのがあるのですけれども、これはそのまま評価委員会になるということでまず、よろしいのでしょうか。","respondent":"池田国保医療年金課長","answer":"こちらは実施計画策定の委員会でございまして、実際に、今度、検討委員会の検討する場につきましては、若干名称も変わるのと、それから委員構成も若干変わる可能性はありますけれど、ほぼ、医師会とか薬剤師会といったメンバーについては、役割といいますか。","id":"exchange-056"},{"speaker":"筒井委員","kind":"質問","question":"というのも、健診受診をするような勧奨とか、また、そのインセンティブを与えるという点について、こうした医師会とか職員の皆様とか専門の方は、それはそれで当然、委員会にいらっしゃってもちろんいいのですけれども、そうした健診とかインセンティブとかのためのアイデアとか、その広報の強化のためにも、第三者とか外部の声をもうちょっと入れていったほうがいいのかなと考えておりまして。","respondent":"池田国保医療年金課長","answer":"ご意見としては承らせていただきます。","id":"exchange-057"},{"speaker":"筒井委員","kind":"質問・要望","question":"例えば、スポーツ系のイベントとかで啓発活動とか、また、そのスポーツイベントに参加するのに、１つの条件というか、今度、しながわシティランとかありますけれども、そこに参加するにはきちんと健診を受けていただかないといけないとか、そうした何か条件づけとか、啓発広報のためにもそうしたイベントなどで積極的にやっていったほうがいいのではないかと思うのですが、その点いかがお考えでしょうか。","respondent":"池田国保医療年金課長","answer":"今の、スポーツのイベントというようなことですけれども、そういったこともまた、頭のほうに入れさせていただければと考えています。","id":"exchange-058"},{"speaker":"筒井委員","kind":"提案","question":"３８ページとかで、セミナーの開催は難しいとか、いろいろ、セミナーはあまり評価がよろしくないのかなと思うのですけれども、セミナーは、会場に行かないと受けられないような形だと、なかなかその都合によっては直接現場に、セミナー会場に行けない方もいらっしゃるので、やはり、私はほかのところでも何回か提案させていただいたのですが、そのオンラインとか、あと。","respondent":"池田国保医療年金課長","answer":"もう一つが、先ほどちょっとお話をさせていただきましたけれども、これまでの国保の加入者の方しかセミナーのほうに入れなかった、受診できなかったところですが、そういった対象なども広げて、多くの方にセミナーを受診していただければということも考えているところです。","id":"exchange-059"},{"speaker":"筒井委員","kind":"質問","question":"ぜひよろしくお願いします。最後に、最近、厚生労働省がアルコールによる健康リスクについての、飲酒に関するガイドラインを公表したのですけれども、もう本当に出たばかりだと思うのですが、この計画にはそうしたら、アルコール、飲酒についての記載というのは特段しないのでしょうか。それともちょっとは記載、反映していこうかというお考えはあるのでしょうか。","respondent":"若生健康課長","answer":"アーカイブに関しての対策ですけれども、現在、健康プラン２１という、健康課のほうで所管している健康増進計画ございまして、そこの中で、来年度改定の作業を行っていく段階になりますので、そこの検討委員会の中で検討してまいりたいと考えております。","id":"exchange-060"}]},{"id":"topic-06","title":"国保財政健全化計画","agenda":"国保財政健全化計画","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"これはすごく難しくて、今の説明で毎回よく分からないのですけれども、結局赤字になった分を法定外繰入れで賄っているということですよね。それが、令和４年度のときは１３億２,４０６万２,０００円が、赤字部分を法定外繰入れで賄いましたということなのでしょうか。","respondent":"池田国保医療年金課長","answer":"ただ、実際にこの法定外繰入金の部分について、計画どおりいっていないかというところではありますけれども、これまで保険料の改定の際に何度か説明させていただいたところですが、コロナウイルスの影響による医療費の増加、それと物価の高騰等によりまして、激変緩和率。","id":"exchange-061"},{"speaker":"鈴木委員","kind":"質問・要望","question":"赤字というものと、コロナで余計に医療費がかかって、その分を法定外繰入れで入れたということの関係性というものは、それはコロナで余分にかかったというものは赤字とは言わないですか。赤字は赤字でまた別なもので、結局令和４年度の赤字というものは、決算補填等を目的とした繰入金というところの９億５,５１１万円余、これが赤字という意味なのですか。なかなかこれ理解することが難しいのです。","respondent":"池田国保医療年金課長","answer":"こちらの部分で、赤字と今出している金額につきましては、決算補填等目的によって繰り入れた金額ということでございまして、令和４年度につきましては、保険料の負担緩和を図るためということで、９億５,０００万円ほど繰入れをしたです。","id":"exchange-062"},{"speaker":"鈴木委員","kind":"質問","question":"そしてそれを計画的になくして、これ９４％から１％ずつ増やして保険料で賄うようにして、そして１００％、６年間でなくすというような計画を令和８年まで引き延ばすと、そのようなことの計画ということで考えていいですか。","respondent":"池田国保医療年金課長","answer":"あくまでもこちらのほうは、平成３０年に国保の改革がございまして、平成２９年度に立てた計画で、その際に、その当時赤字額が幾らあったかというところで、その赤字額を６年間で解消するというところを立てなければいけないという見込みで立てたものなのですけれども。","id":"exchange-063"},{"speaker":"こんの委員","kind":"質問","question":"すみません。今の質問に関連するのですが、私も理解ができているところとできていないところの、赤字解消という、この意味は、そうすると平成３０年以前から赤字があった。それを解消していくための計画をこの６年で品川区が立てたけれども、今そこになかなかいっていないから次のものを立てなければいけない、このような理解でいいですか。そこをよろしいでしょうか。そのような理解でいいですか。","respondent":"池田国保医療年金課長","answer":"令和５年度が、この赤字解消計画の見直しの年に当たるということになっているところでございまして、駄目だったからするわけではなくて、その周期で計画を見直すものです。","id":"exchange-064"},{"speaker":"こんの委員","kind":"確認","question":"今のご説明分かりました。そうすると、６年でなかなか難しいということなのですが、そもそものこの赤字というものは、平成３０年以前に積み上げられてきた赤字という、そのような理解でいいのですか。それを解消するために６年の計画を立て、さらに次の計画を立てるという、そのような理解でいいですか。そこを確認させてください。","respondent":"池田国保医療年金課長","answer":"平成２８年度の赤字の額が幾らあったかと、そこのところでの額になりますので、もともとその年に幾ら赤字があったですので、こちらの様式のところで約１３億２,０００万円というものが、平成２８年度に発生した赤字の額ということです。","id":"exchange-065"},{"speaker":"こんの委員","kind":"質問","question":"分かりました。そうすると、先ほどの赤字の原因というものがご説明あったかと思うのですけれども、現時点での、この平成４年の、ここに書かれている実施状況の原因としては、コロナの医療費だったり、物価高騰だったりということですが、この平成２８年度までの赤字の原因というものはどのように捉えられていたのでしょうか。その辺を教えてください。","respondent":"池田国保医療年金課長","answer":"平成２８年度のこの部分については、なぜこうなったかというところではなくて、区の運営の中でこの額が赤字だったというようなことしか、今のところ私どもが分からない状態です。","id":"exchange-066"},{"speaker":"こんの委員","kind":"質問","question":"その当時市区町村でやっていた、この運営の中で、残念ながら赤字が出ていたといったところは、何となく赤字が出てしまったのは、先ほどのデータヘルスではないですけれども、いろいろな計画を立てるのだけれどもなかなか健診がうまくいかないとか、そういったことの要因で医療費が上がってしまってとか、そのような要因が考えられるのですが、そうしたことの返済をしていくための計画で。","respondent":"池田国保医療年金課長","answer":"令和５年度に今後の赤字解消計画というものを立てる予定になっております。","id":"exchange-067"},{"speaker":"筒井委員","kind":"質問","question":"この国保財政健全化計画は、また見直しということなのですけれども、現状の国保財政健全化計画は、区のホームページなど、そうしたところに掲載はされているのでしょうか。区のホームページを検索してみてもちょっと載っていないので、何かそうした書面状のものがあるのかどうかお聞きしたいと思います。","respondent":"池田国保医療年金課長","answer":"この赤字計画につきましては、東京都の国民健康保険のページに、東京都内の計画を全て紹介しているところでございまして、特に区のところでは載せていないかもしれません。","id":"exchange-068"},{"speaker":"筒井委員","kind":"質問","question":"分かりました。では、東京都のページ、東京都国民健康保険の運営方針など、そうしたところから、東京都関連のページから引っ張っていけば閲覧できるという状況でしょうか。","respondent":"池田国保医療年金課長","answer":"こちらのほうに細かく載ってございまして、各区の解消予定年度など、そういったものもホームページのほうに掲載されてあります。品川区のほうはそのページの一番下のほうに載ってありますので、よろしくお願いいたします。","id":"exchange-069"},{"speaker":"鈴木委員","kind":"質問","question":"それで、毎年法定外繰入れの削減をしていくというところでの目標というものが、目標というか、出しているのが、４,９０８万４,０００円というようなことなのですけれども、これは結局この部分を保険料算定のほうに入れるということで、赤字を減らすために保険料算定に入れていくという、そのような計画ということで考えていいのでしょうか。","respondent":"池田国保医療年金課長","answer":"それと、毎年４,９０８万円という数字になっていますけれども、こちらのほうは、激変緩和措置につきまして、毎年１％ずつなくなっていって６年で１００％にするということで、およそ１％ということで、１％が赤字解消になるだろうということで。","id":"exchange-070"},{"speaker":"鈴木委員","kind":"質問","question":"それでも計画どおりにはいかなかったので、さらにこれからも計画を立てて、その分を保険料で賄うように保険料の賦課総額として上げていくという、そのような考え方でいくということで、そうすると、この健全化計画というものは、令和５年度が終わった後の赤字の状況で、さらにその計画を立て、この赤字解消、赤字ゼロになるまで計画を立て続けるという、そのような考え方でいくのでしょうか。","respondent":"池田国保医療年金課長","answer":"計画につきましては、最終目標はこの赤字がゼロになるところが目標ではありますけれども、実際のところ保険料につきましては、平成３０年度に激変緩和率９４％からスタートして、令和６年度までの１００パーセントにいくというところ。","id":"exchange-071"},{"speaker":"鈴木委員","kind":"質問","question":"収納率などの関係もあると思うのですけれども、収納率は何％というようなことで計算をして、それでもなおかつ赤字にならない計画を立てるようにという、そのようなことで組んでいくということなのですか。収納率の目標というような。収納率との関係というものも出てくる、赤字になるかどうかということはあるのではないかという気がするのですけれども、その点はどうなっているのでしょうか。","respondent":"池田国保医療年金課長","answer":"これはどうしてかといいますと、保険の収納率が９９％だと、１％、２％少なくなりますと、未収金補填金というような形で、またその分の保険料を取らなければいけないということで、１００％にするということで保険料の緩和を考えた形で、算定しています。","id":"exchange-072"},{"speaker":"鈴木委員","kind":"質問","question":"そうすると、１００％で計算するとなると、最終的には１００％というものはなかなか難しいということになると、最終的には１００％で計算した結果、赤字というものは必ず出てしまうのかなという気がするのですけれども、それでも、もう１００％で計算すると赤字で、ゼロに、１００％で計算しても赤字がゼロになるというようなことで、どうやったら組めるのですか。","respondent":"池田国保医療年金課長","answer":"今の委員からのご質問については、以前からいろいろとご質問があるかというところと思いますけれども、私どももあくまでも計画し、目標に向かって事業を進めするです。ご理解いただければと思います。","id":"exchange-073"},{"speaker":"こんの委員","kind":"確認","question":"もう１回よろしいでしょうか。すみません。そうすると、またちょっと理解の確認をしたい、自分の理解を確認したいのですが、毎年５,０００万円を返済していくというか、解消していくということなので、先ほどの収納率という話も出ましたけれども、あくまでも毎年５,０００万円を計画的に返す。","respondent":"池田国保医療年金課長","answer":"きちんと赤字解消のほうに向かって、保険料の収納率の向上のような形で、健全な財政にしていかなければいけないと考えているところです。","id":"exchange-074"},{"speaker":"こんの委員","kind":"質問","question":"これまた同じ額でいくということはないにしても、法定外繰入金でそのような解消もするし、赤字解消もするし、保険料の補填もしていくという、この額はともかくとしても、この法定外繰入金を使いながら財政を維持していく、ごめんなさい、繰り返しての質問になりますが、そのようなことでいいですか。","respondent":"池田国保医療年金課長","answer":"令和８年度まで、激変緩和措置解消で１００％ということを区長会のほうで決定されておりますので、目標としましては、やはり赤字解消ということにつきましては、令和８年度を目標にはしたいとは、私個人としては考えているところです。","id":"exchange-075"},{"speaker":"こんの委員","kind":"意見","question":"一応目標値としては令和８年度ということですが、そのときにどこまで解消ができているのか、また、保険料の激減緩和をするための補填として使う部分も出てくると思うので、なかなか、痛しかゆしというようなところもあると思うのですけれども、ここをうまく使うしかないのだろうなとは思いますが、その額についてはその時々の額でという形になると思いますけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-076"},{"speaker":"筒井委員","kind":"質問・要望","question":"赤字削減なのですけれども、今ご答弁あったように、区長会として、特別区は激変緩和措置の部分を減らしていって赤字解消するという、大体どの区も同じなのでしょうか。ちょっと今、先ほどお示しいただいたほかの区の状況を見ているのですけれども、大体が激変緩和措置の解消で赤字を解消していくという方向でよろしいのかという確認をさせていただきたいのですが、それでよろしいでしょうか。","respondent":"池田国保医療年金課長","answer":"実際に、令和５年度についてはこれから各区出す予定になっておりますので、この間の令和８年度までに１００％にするという、保険料の激変緩和についてなくして１００％にするということが区長会で決まりましたので、それ以降の各区の動きについてはまだ把握していないところです。","id":"exchange-077"},{"speaker":"筒井委員","kind":"質問","question":"各区いろいろ違っていて興味深いなと思っているのですけれども、ただ足立区の場合は赤字、法定外繰入金が４６億９,０００万円ぐらいありまして、毎年度返済額もばらばらなのですが、一応その解消の目標年次が令和１５年度ということは書かれてあるのですけれども、品川区としては、その解消の目標年次というものは、これから８年、どうせそこは返し切れていない可能性はあるのですが。","respondent":"池田国保医療年金課長","answer":"そのぐらいになるだろうということで、都のほうには出しています。その後、令和３０年以降に解消するという区も確かにあります。そちらはまた後ほど、東京都のホームページのところに各市町村の解消予定年度というものがありますので、ご覧いただければと思います。","id":"exchange-078"},{"speaker":"筒井委員","kind":"質問","question":"これ、期限というものは特に、各区いつでも自由な期間を設定していいという、解消できればという計算式を立てられているのでおおよそあれなのですけれども、何か、大体何年度までに解消しなければいけないというような、そうした何か、特別区全体の目標など、そのようなものはないのでしょうか。それとも各区自由に決めるということでよろしいのでしょうか。","respondent":"池田国保医療年金課長","answer":"赤字解消につきましては、何年度までにやらなければというものはないのですけれども、東京都のほうの計画の中でも、２３区で何区以上を目標とするというような形で、法定外の解消を目標にです。は法定外です。","id":"exchange-079"}]},{"id":"topic-07","title":"品川感染症予防計画の策定","agenda":"品川感染症予防計画の策定","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"この感染症予防計画が、どのような体制でどのような方が入られて、検討されてつくられたものなのかということを教えていただきたいということと、多分もちろん医師会とか、薬剤師会とか、そのようなところとも連携しながらつくられていると思うのですけれども、そういうところに対しての、この計画の、何というのですか、周知など、そのようなものはどのように考えられているのか、まず伺いたいと思います。","respondent":"坂野保健予防課長","answer":"この計画自体は２２ページほどありますが、これは区のほうで作成しているのですけれども、国のほうでかなり詳細な作成の手引というものが出ております。それにのっとってつくっています。","id":"exchange-080"},{"speaker":"鈴木委員","kind":"質問・要望","question":"少し具体的に伺いたいことが、２ページのところの事前対応型の体制の構築ということで書かれているのですけれども、サーベイランスの体制の強化だったり、それから平時からの事前対応型の体制を構築するということで、そのように書かれているのですが、これ具体的にどうするのかということをちょっと伺いたいと思います。","respondent":"坂野保健予防課長、舩木生活衛生課長","answer":"事前対応型ということとは一体何ぞやということだと思うのですが、例えばＰＰＥ、防護服など、あのようなものをあらかじめ用意しておくとか、もう十分訓練をしておくとか。１月の委員会でコロナ検証報告書についての内容を報告いたしましたけれども、その際にも触れましたが、まさにその事前対応型という意味では、来年度から、区の中でも健康推進部の中に地域医療連携課という組織を新設し、そして様々。","id":"exchange-081"},{"speaker":"鈴木委員","kind":"確認","question":"前にご報告いただいたのですけれども、今回これを出てきた段階で改めて見させていただいて、本当に感染状況に応じた健康危機管理体制というようなところでとか、かなり基盤整備の検討とか、そのようなところでもすごい詳しく、こちらの前にご報告いただいたほうがすごく詳しく載っていたので、このような体制も含めて進めていくということは改めて確認させていただいたところなのですが、このＩＨＥＡＴは。","respondent":"坂野保健予防課長","answer":"そこから派遣してもらう形になりますので、あらかじめそちらのほうは調整をかけておくということが１つです。この４０人、８０人、１２５人に比べて４人は随分少ないのではないかということがあると思うのです。","id":"exchange-082"},{"speaker":"鈴木委員","kind":"質問","question":"もともとドクターも、人材の定数よりも、今、多分２名だけのドクターの配置というような状況になっていると思うのですけれども、そのようなドクターにしても、それから保健師にしても、少し少ない人員になっていると思うのですが、そのような点ではどのような体制の強化がされたのか、それから今回の定員削減の中で、たしか保健予防課の人数もかなり削減されているのではないかと思うのですけれども。","respondent":"阿部品川区保健所長、坂野保健予防課長","answer":"ごめんなさい。私から先にＩＨＥＡＴについての補足の説明をいたします。保健所の体制の強化の話、先ほど生活衛生課長のほうからもあったのですが、まさにそこを今度、新年度から地域医療連携という新しい課をつくって、地域とのコラボレーションを強化していこうということが重要なところなのかなと思います。","id":"exchange-083"},{"speaker":"鈴木委員","kind":"質問・要望","question":"この保健所の体制というところでは、人員体制としてはコロナを通して強化されたというようなところがどれぐらいあるかということは、強化されているのかどうなのか、その人員体制のところで教えていただけたらと思います。","respondent":"坂野保健予防課長","answer":"人員体制はコロナでどれぐらい増えたのかということでしょうか。結局感染のフェーズによって人数もすごく違うので、どの部分で比較するかですけれども、それなりに体制は強化されたとは思っております。何年何月で見るかで全然違うものですから。","id":"exchange-084"},{"speaker":"鈴木委員","kind":"意見","question":"コロナ前、コロナを通して、コロナ禍の経験を通してどう強化されたのかというようなところが知りたいなと思ったのですけれども、なかなかはっきりしないということであれば結構です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-085"},{"speaker":"筒井委員","kind":"確認","question":"今回の品川区感染症予防計画なのですけれども、国の基本方針および都道府県予防計画に即して作成するとなっておりまして、その即してつくらなくてはいけないという影響というか、どの辺が影響されているのか、特に具体的には、「都は地域の計画と整合性をはかった計画策定を目指しており、区案の段階から整合性の確認・修正を行っている」ということなのですが、どの程度修正が行われたのか、現時点で分かる。","respondent":"坂野保健予防課長","answer":"かなり細かく、これとこれは入れるようにというものが最初からあって、それで入れて、それに対して東京都が、ではこのようにしてくださいというような感じのやり取りを電子的にやっているという状況です。","id":"exchange-086"},{"speaker":"筒井委員","kind":"質問","question":"区が考えたものと、何か都と大きく違ったことなどはあまり、そのようなことはなかったのですか。それとも、何かここはちょっと大きく変えなければいけないところがあったなというところがありましたでしょうか。","respondent":"坂野保健予防課長","answer":"先ほども申しましたように、結構詳細な手引があって、これに則ってつくりなさいというものが最初からあったので、そこですごく違うというようにはあまりならないと。","id":"exchange-087"},{"speaker":"筒井委員","kind":"質問","question":"分かりました。１月の厚生委員会でお示しがあった、新型コロナウイルス感染症対応の検証と健康危機管理体制の基盤整備検討報告書を踏まえたものとするということなのですけれども、その報告書については特に何か、都との整合性など、そのようなものはあまり関係なかったというか、特段修正というようなことはなかったのですか。","respondent":"坂野保健予防課長","answer":"報告書自体やっていない区もいっぱいありますので、あのようにレビューをつくっていない区もあります。だから、レビューをつくったのは品川区の独自の取り組みです。そこで何か直すなど、そのような話にはなかなかならないです。","id":"exchange-088"},{"speaker":"こんの委員","kind":"確認","question":"１点確認をします。そうしたことのために、このような体制をということで計画をされているのだろうと理解しているのですが、それでよろしいかどうかといったところです。この、いわゆる橋渡しをする方、これはどのような方が橋渡しをしていくのか、その橋渡しをする方の権限というものはどこまであるのか、その辺を教えてください。","respondent":"舩木生活衛生課長","answer":"私からは、こういったパンデミックに備えた全庁的な支援体制というところですけれども、これはまさにこれから、報告書の提言の内容を踏まえまして、つくり上げていくものだというように認識しておりますが、例えば保健所でなければできないこと、それから物を買うですとか。","id":"exchange-089"},{"speaker":"こんの委員","kind":"質問","question":"そのときに、本当にこのような、今回のようなコロナが起きたときに、迅速に速やかにその体制を整えていくためには、やはり保健所、保健予防課との、医師会との連携でスムーズな体制を取るといったときに、これを何でしょう、橋渡しをする、医師会、先生たちがこう体制を取ってほしいという調整をするものと、いやいや、品川区としてはこのような体制をお願いしたいのだという。","respondent":"秋山保健整備担当部長","answer":"ですから、新しい課の管理職を含めて、そこが、業務、仕事として平時から医師会との連絡体制を構築し、そこには統括保健所も来ますので、そこの専門的な知識を含めて、医師会と区との対応を、そこが終始やるという体制を来年度からつくるというところで対応します。","id":"exchange-090"}]},{"id":"topic-08","title":"その他","agenda":"その他","exchanges":[{"speaker":"鈴木委員","kind":"質問","question":"その質問に対して、福祉部長が、紹介会社の手数料は平均で８９万円もかかっていて、紹介料補助を行っていくというような答弁をされたのではないかと思っているのですが、そこのところで、紹介会社を通さなければ人材確保できないような実態を区としてどのように把握されて、その紹介料補助というものはどのようなものなのか、その考え方と内容についても伺いたいということでお願いしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-091"},{"speaker":"鈴木委員","kind":"質問・要望","question":"お話を伺ったところでは、もうほぼこの紹介会社を通さないと確保できないというところだらけという感じで、障害者のほうもそうですし、高齢者のほうもそうですし、大体年収の３割というように伺って、そうすると３００万円の年収になると１００万円の紹介料を払わないと、しかもその紹介料を払ったからといって、ずっと勤め続けるということではなくて、例えばもう１週間で辞めてしまうなどという人もいたり。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-092"},{"speaker":"やなぎさわ委員","kind":"確認","question":"すみません。確認になるのですけれども、介護職員の人材紹介というものは、資格的には、いわゆる看護師や生活相談員などの有資格者が、そういったものの対象範囲というものはどこまでになりますでしょうか。","respondent":"菅野高齢者福祉課長","answer":"役割というか、介護士の資格を持った介護職員というように、今のところ考えているところです。","id":"exchange-093"},{"speaker":"やなぎさわ委員","kind":"質問","question":"介護士、介護福祉士。介護福祉士以外の、特に何も資格を持っていない方やヘルパー、機能訓練士などというものは対象にならないということですか。","respondent":"菅野高齢者福祉課長","answer":"この辺りの細かい制度設計は、今後また詰めていくところではあるのですが、今のところ考えているのは、以前から特別養護老人ホームや老人保健施設に勤める看護職員を確保するための、そういった紹介料に対する補助をするというスキームがございましたので。","id":"exchange-094"},{"speaker":"やなぎさわ委員","kind":"質問","question":"たしか以前にも似たようなものがあって、それが多分あまりというか、ほぼ使われない、それほど利用実績が、多分３年、４年ぐらい、もっとかな、５年ぐらいあるのかな、間にあまり使われていなくて、それで要は幅を広げたというような解釈でよろしいですか。","respondent":"菅野高齢者福祉課長","answer":"ただ、施設に看護職員をやはり集めることが、数年前からかなり厳しいというお声は聴いていたので、今までは看護職員の紹介料を支払ったときの補助をしてきたと。今回、介護職員についても同じようなスキームでやってみようというところで、予算計上させてもらいました。","id":"exchange-095"},{"speaker":"やなぎさわ委員","kind":"質問","question":"特に有資格者が人員配置上必要な場合は、本当にもうすぐにでも人員確保しないといけなくて、やはり有資格者ほど集めるのが大変なので、結局そこのところにピンポイントで、紹介してくれるところということでそのような業者を使ってしまうという現状があるので、役に立っている部分は当然あるのですけれども、大きい話になってしまいますが、それこそ区がそれをやるぐらいな。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-096"},{"speaker":"おぎの委員","kind":"質問","question":"今やなぎさわ委員が言っていた、人材を品川区で確保するということは、私も全く同じことを考えておりまして、実は今回予特のときにお聞きしようかなと思っていたのですが、やはりこの紹介会社、中間の紹介会社に入る平均８９万円、または１００万円、これが勤める介護職のご本人、または事業所のほうに回していただいたら、介護職の方も給料が上がりますし。","respondent":"菅野高齢者福祉課長","answer":"介護職においても２１社、それが認定されているというようには、夏の資料では記載しておりますので、一定程度区内のそういった、今ほかの委員からも、そういったファクスが事業者にはいっぱい来るというお話もありましたが。","id":"exchange-097"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"福祉専門学校の件で１つ付け加えさせていただきたい。お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-098"},{"speaker":"鈴木委員","kind":"質問","question":"先ほど１０人分というようなことだったのですけれども、これは看護師のほうは１２０万円で、特別養護老人ホームや老人保健施設のところでの看護師の確保というところでということでしたが、この１人当たり５０万円の介護福祉士というものも、そこの、何というのですか、これが使える場所というものは、老人保健施設と特別養護老人ホームに限るのか、それとも一般の。","respondent":"菅野高齢者福祉課長","answer":"今まで看護職員については、特別養護老人ホームや老人保健施設というところで限定されておりましたので、まずは介護職員についても、そこの同じようなスキームで、施設での職員不足が特に顕著だというようにも聞いておりますので、まずはそこにフォーカスというか。","id":"exchange-099"},{"speaker":"鈴木委員","kind":"質問・要望","question":"指定管理者を辞退されるところの杜松ホームのところでも、やはりこの確保がすごく大変で、１人１００万円ぐらいで、５人雇おうと思うと５００万円かかってしまうというような、そのようなところをお聞きしたのですけれども、これそのものが本当に制度のゆがみなので、これをどんどん拡大すれば済むというものではないので、今お二人から出たように制度のゆがみを正していくというところで、ぜひ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-100"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/132976?Template=document&Id=3686#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":72273,"voices":273}},{"id":"r06-20240227-8","meetingId":"r06-cm02","date":"2024年2月27日","dateIso":"2024-02-27","committee":"建設委員会","time":"午前１０時００分～午後 ２時０７分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を56件抜き出しています。","topics":[{"id":"topic-01","title":"品川区自転車活用推進計画策定に向けた検討状況","agenda":"品川区自転車活用推進計画策定に向けた検討状況","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"なので、やはりそうしたことは本当にしっかりやっていただかないと、結局利用を促進していっても、そうした事故につながってしまうということになりますので、私がけがしたときは、多分あれは国道だったと思うので、区道ではないのですが、ぜひそうした整備はしっかりやっていっていただきたいと思います。混乱しないようにということですけれども、していただきたいと思うのですが、いかがでしょうか。","respondent":"工藤交通安全担当課長","answer":"要は車と自転車を分けて安全を確保しましょうということの趣旨です。なので、車道には車、自転車道のほうには自転車に走っていただくということで指導がなされていると理解をしております。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問","question":"歩道にそういう整備があるときは、そこを通ったほうがいいということなのですね。分かりました。道路交通法上は違反にはならないと考えていいのですか。車道を通った場合のこと。","respondent":"工藤交通安全担当課長","answer":"法律上も、自転車道が整備されているところについては、歩道を自転車で通っても違反にはならないです。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうしたら、ほかのところで、１３－１の意見のところでシェアサイクルのことが書かれているのですけれども、平準化と電池切れに対応していくということで、実際に今の状況がどうなっているのかというのをお聞きしたいのですが、区役所にもポートがあって、自転車を持ってこられる業者の方がいるので、今もやられているのではないかと思うのですが、その頻度というか、現状を伺いたいのと。","respondent":"櫻木土木管理課長、工藤交通安全担当課長","answer":"シェアサイクルにつきましては、事業者がおおむね１日１回、頻度の多いところだと２回程度、ぐるぐると区内を巡回して、必要に応じて台数の調整と、充電器の交換という形で行っているところです。住民の方々には、住宅前の駐輪場の状況を見ながら、撤去、もしくはそういった状況を勘案しながら撤去する・しないというのを判断していくということでご説明させていただいているところなのですけれども、現状を申しますと。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"大森駅前住宅については、どういう検討をされているのかというのを聞いたので、もう少しお話しできるところがあれば、伺いたいと思います。住民の皆さんからはやはり撤去してほしいという要望が、この間ずっと、１０年やっているということでお話を聞いていますので、ぜひそれが反映されるように区としても力を尽くしていただきたいと思いますけれども、改めて伺いたいと思います。","respondent":"工藤交通安全担当課長、櫻木土木管理課長","answer":"こちらの現在の検討状況ですけれども、住民の皆様からは、大森の地下機械式駐輪場の利用率もなかなか上がっていないのではないかというような。ただ、同じポート内に複数台ありますので、電池が切れればほかの自転車を使っていただくということで、全て電池切れという状況はあまりないのかなと考えています。","id":"exchange-004"},{"speaker":"のだて委員","kind":"質問・要望","question":"シェアサイクルのところは、こういった声も出ていますので、今後対応されるということですので、利用しやすいようにぜひお願いしたいと思います。大森駅前住宅のほうは、今、水神公園の地下駐車場に大型も入れられるようにということで考えていらっしゃるということで、そうしたこともぜひ進めていただいて、駅前住宅の駐輪場をぜひ撤去できるようにしていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"西本委員","kind":"質問・要望","question":"幾つか確認したいと思います。ありがたいなと思います。ここから、ご説明いただいたのですけれども、確認も含めて質問したいと思います。それが１つ目。利用状況によって考えますということは言っていたと思いますけれども、その現状を踏まえて、しっかり維持していくためのご理解をぜひしていただきたいなと思いますので、私はすぐというのは難しいのではないかなと思いますが、いかがでしょうか。","respondent":"鈴木都市計画課長、高梨公園課長、工藤交通安全担当課長","answer":"対応につきましては、このパブリックコメントの回答のところにも書いてありますが、しばらくの間、しっかりと周囲の看板であったり。周りの状況等も勘案して、状況を見ながら判断していきたいと思いますので、今行っていることを住民の方々にも説明しながら。","id":"exchange-006"},{"speaker":"西本委員","kind":"質問","question":"いろいろありがとうあります。最後に、立派なこの自転車活用推進計画、こういう推進計画をとるべきだというのは前々から私も指摘していた部分があるので、ありがたいなと思うのですけれども、この活用方法ですね。それぞれのところでは、これを基にして啓発活動であったり広報であったりといろいろやられると思うのですけれども、より活用できる方法は何か考えられていますでしょうか。","respondent":"鈴木都市計画課長","answer":"推進計画ということで、施策的なところはしっかり計画の中で位置づけておりますし、警察、道路管理者含めて連携した取組を行っていくというところで、この計画の冊子自体、区のホームページ等で公表という形になりますが、できるだけ分かりやすく。","id":"exchange-007"},{"speaker":"田中委員","kind":"質問・要望","question":"今回、推進計画策定に向けまして、協議会の方々がパブリックコメントを求めて、それに対するコメントがあって、それに対してしっかり回答も整えていただき、その中でもまたこの計画に盛り込むべきものは盛り込んでいただいているという流れがあると。確認です。","respondent":"鈴木都市計画課長","answer":"今回は５回目の協議会のご報告で、１回目から５回目まで全て、その都度、当委員会にご報告させていただきまして、１回目・２回目のあたりは品川区の現状を整理していた状況の中でも、当委員会の中で、例えば自転車の大型化。","id":"exchange-008"},{"speaker":"田中委員","kind":"質問・要望","question":"区長も含め、区民の方へ直接ご意見を求めるということは、必要なことでありますし、それに対して異を唱えるものではありませんが、一方で、二元代表制の中での我々代弁者として発言をしていることも同様にしっかりご対応いただけたらというのが、当然やっていただいているとは思いますが、改めてお話をさせていただきました。その上で、個別の話で、先ほど桜新道の話がありました。","respondent":"森道路課長","answer":"ネットワーク計画に基づきまして、整備すべき路線に対して来年度から優先順位をつけて順次やっていくという形になりますけれども、区道から都道へ、都道から区道へというところも、その整備の中でしっかりと都道管理者と話をしながら。","id":"exchange-009"},{"speaker":"田中委員","kind":"質問・要望","question":"それと、先ほど電動キックボードのお話も出ていたように、時代の変化とともに新しい機種がどんどん増えてくると思いますが、同じ自転車であっても、電動もそうかもしれませんが、さらにその上を行く、スピードがもっと速く出る、あれは何ていう自転車と呼んでいいのか分からないのですが、少しタイヤが太めの、相当スピードが出る。","respondent":"鈴木都市計画課長","answer":"ただいま委員からご紹介いただいた電動バイク、ペダル付き原動機付自転車というところのくくり、法的には特定小型原動機付自転車、自転車に含まれるということで、最近そうした移動手段も見られるということで、計画の中ではしっかりご紹介させていただいているところですが。","id":"exchange-010"},{"speaker":"田中委員","kind":"質問・要望","question":"ぜひそれは早急な対応、その都度の適切なご対応をお願いしたいと思います。特に交通関係なので、警視庁、各警察署との連携も必要になってくると思いますが、せっかくいいものをつくっていただいたものを、さらにその有効性を高めていく上では、近隣区や警視庁との連携も、実効性をより高めていくためには、やっていただいたほうがいいと私は思っているのですけれども、その辺の今のお考えはいかがでしょうか。","respondent":"鈴木都市計画課長","answer":"計画をこうしてつくって、商店街とも連携しながら、取組の中で、場合によっては当然ながら近隣区、自治体、それから商店街の方のお話も伺いながら、様々な検討・取組を進めていきたいと考えているとともに、今回、策定に当たっては、区内の警察の方全て委員に入っていただいて。","id":"exchange-011"},{"speaker":"田中委員","kind":"質問・要望","question":"最後の警察の方のお話、大変心強く受け止めております。併せて近隣区との連携も、これを計画するに当たって、近隣の区の計画も参考にされているということでありましたが、逆に近隣区に対しても、品川区民が目黒区に行ってということもあるかもしれませんので、そういったことも含め、実効性を高める視点からも、近隣区との連携もぜひ進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"若林委員","kind":"質問","question":"この幅員の広い道路というと、国道とか都道が中心になるのかなと思うのですけれども、交差点の事故が多かったり、ほかの箇所での事故が多かったり、そこら辺の傾向性はどういう形か、ご存じであれば教えてください。","respondent":"鈴木都市計画課長","answer":"ここに示している状況のとおり、やはり自転車と自動車の事故というのが広幅員の道路でですが、やはり広幅員の道路になりますと、車のほうも一定速度を出しているというところと、併せて自転車のほうも、見通しがいい関係で、スピードが出ているというところがあって。","id":"exchange-013"},{"speaker":"若林委員","kind":"質問","question":"そうすると、道路交通法の、自転車は車道を走るのが原則というのが、ある意味で広く徹底されて、この二、三年ぐらいですか、ここのほかのページにも、パブリックコメントにもありましたけれども、自動車が、自転車通行帯とか自転車道とかという青い帯がありますよね、あと矢羽根もあると。ああいう周知がされてから。","respondent":"鈴木都市計画課長","answer":"ご指摘の道路への違法な駐停車ですが、計画の中では、まず道路管理者として注意喚起を促す看板の設置、それから法的な違法の取締りについてはやはり交通管理者というところで、各施策ごとに実施主体というところで、警察署であったり、区の計画ですから。","id":"exchange-014"},{"speaker":"若林委員","kind":"意見","question":"駐車禁止のところは比較的あるのかなと思うのですけれども、停車禁止はそんなにないですよね、あの幅員の広いところで。だから、とまってもいいのですよね。自転車が車道を走ることも、これは推奨されている。どうやったって取り締まれないですよね。これは区議会議員に言うことではないのかもしれないけれども、何とかしてほしいということがつい最近もありましたので、これはどういうふうに言うかですよね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"まつざわ副委員長","kind":"質問","question":"しかし、先ほど西本委員からもありましたが、やはり子育て世代の、事故率が多いのか分からないのですけれども、子育て世代の危険運転というのですか、確かに子どもを乗せっぱなしも危険ですし、お母さん・お父さんも逆走しますし、信号も無視してしまいますし、子どもを乗っけても飛び出してしまうという、ずいぶん危険なところを私も車を運転しながら感じることが多くて。","respondent":"鈴木都市計画課長","answer":"ルール・マナーの啓発については、全世代を通じてしっかりと区としても周知啓発に努めていきたいですが、今いただいた子育て世代のお話ですが、６５ページに「通園の安全対策の実施」ということで、モデル的に子育て送迎ルートの整備というのを、今後計画をつくった上で。","id":"exchange-016"},{"speaker":"まつざわ副委員長","kind":"質問","question":"ぜひ幼稚園のお迎えや保育園のお迎え、そういった送迎の父親・母親のお話を聞きながら、そういうのができると、とてもありがたいです。青パト。本当に。できるのだったら、それはすごく効果的で、例えば区の方に声をかけてもらう、商店街とかで物を買うときに、そういう方は本当に非常に多いので、それこそすごくいい周知になるのではないかなと思って、お聞きします。","respondent":"鈴木都市計画課長","answer":"実際に降りてそうした取組を行っているか、できるかどうかというところは、地域活動課の生活安全担当の所管になろうかと思いますので、そこはいただいたご意見をそちらにもお伝えして、検討といいますか、確認をさせていただければと思います。","id":"exchange-017"},{"speaker":"田中委員","kind":"質問・要望","question":"すみません、先ほど質疑の中で、我々の意見はどういうふうに反映されるかといったときの、そのときは述べなかったのですが、自分の意識の中の一つは、ちょうど今出た６５ページの子育て送迎ルートに関して私も発言しましたが、保護者の方が子どもを乗せたときに、送迎ルートをつくると、そこは自分たちが安全に通行できるものだと思い込んでしまうことが、ルートを外れた先でも同様の感覚を持って通行すると。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"}]},{"id":"topic-02","title":"セーフティネット住宅家賃低廉化補助制度の開始","agenda":"セーフティネット住宅家賃低廉化補助制度の開始","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"家賃低廉化補助制度を開始するということなのですが、肝腎な専用住宅の戸数というのは、登録はされたのかどうかというのと、登録住宅の今の件数を伺いたいと思います。","respondent":"竹田住宅課長","answer":"セーフティネット制度の実績ですが、区内のセーフティネット住宅は、１月４日現在ですが、登録住宅が１,０２９戸、専用住宅がゼロ戸となっております。今回の家賃低廉化補助の開始を契機として、専用住宅の増加に努めていきたいと考えております。","id":"exchange-019"},{"speaker":"のだて委員","kind":"質問・要望","question":"今回を契機として増やしていきたいということなので、それは増やしていっていただきたいと思います。専用住宅がゼロ戸ということは、この制度は使えない状況ということですので、今、区としては増やしていく方策をどのように考えていらっしゃるのか、伺いたいと思います。","respondent":"竹田住宅課長","answer":"専用住宅を増やしていく方策ですが、まずは、オーナーの意思決定に重要な関係性を持っていらっしゃるのが、建物を管理する不動産事業者ですので、不動産団体等を通じまして、不動産事業者の方々にご協力いただきながら、大家にもメリットをご理解いただいて。","id":"exchange-020"},{"speaker":"のだて委員","kind":"質問・要望","question":"この制度を開始するということですから、使えるように、使いやすいようにしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"西本委員","kind":"質問","question":"このセーフティネット住宅というのはどういうものですかというのが一つあります。教えてください。これ、家賃は決まっているのですか。どのぐらいの家賃のところ、例えばもともとの家賃が１０万円なのか、２０万円なのか、そういう規定があるのかどうか。それと、そもそもこれをやるきっかけは何なのですかということなのです。品川区ですか。それとも国ですか。東京都ですかということをまず教えてください。","respondent":"竹田住宅課長","answer":"実施のきっかけですが、先ほども申し上げたとおり、登録住宅のほうは着実に増えているのですけれども、なかなか専用住宅のほうは進まないということで、今回開始するものです。","id":"exchange-022"},{"speaker":"西本委員","kind":"質問","question":"もう少し具体的に数字で示していただくと分かりやすいなと思うのですけれども、１戸当たり４万円なわけではないですか。そこはある程度、先ほどのいろいろな要件があって、それで計算しているのだろうと思うのですけれども、実際、幾らのところを借りれば、この４万円は適用できるのですかということなのです。品川区でいうと、大体８万円とか１０万円以下とかというところが多いと思うのです。","respondent":"竹田住宅課長","answer":"公営住宅並み家賃の求め方ですが、こちらも公営住宅法の家賃の算出方法を参考に家賃算定基礎額が決まっておりまして、それに立地係数、規模係数等を掛けることによって、公営住宅並み家賃を割り出して、実際の家賃からそれを差し引いたものが補助額となりますので。","id":"exchange-023"},{"speaker":"西本委員","kind":"質問","question":"これが、では１０万円だったらどうなのですかとか。だって、どのぐらいの家賃のところ、例えば大家たちが、専用住宅になりました、ここの物件だったら通常１０万円なのですけれども、こういう制度があるから４万円引いて６万円でいいですよということでいいのですか。そういうふうにはっきり分かれば、大体区民の人も分かると思うのですけれども、そういうことの理解でよろしいですか。","respondent":"竹田住宅課長","answer":"非常に簡単に申し上げると、限度額が４万円ですので、７万円の家賃であっても１０万円の家賃であっても、最高４万円の限度額となりますので、１０万円であれば４万円引いた６万円、７万円であれば４万円引いた３万円が限度額となりますので、まずはそう理解していただいて、ただ。","id":"exchange-024"},{"speaker":"西本委員","kind":"質問","question":"少しずつ分かってまいりました。そういう説明でよろしいのかどうかと思うのです。要は、若い人たち、結婚したけれども、なかなか２人のを合わせてもこんなにないよとかというケースがあった場合には、この月額所得ということを考えれば、そういう方も入れられないのかな、含められないのかなと思うのですが、いかがでしょうか。","respondent":"竹田住宅課長","answer":"家賃低廉化事業を開始するに当たって、ニーズの多いところ、高齢者、障害者等、対象世帯も多いような、ニーズの高いようなところをまずは対象として始めていき、今後、対象者については、居住支援協議会のご意見も聞きながら、拡大していきたいと考えております。","id":"exchange-025"},{"speaker":"西本委員","kind":"質問・要望","question":"ただ、やはり苦しいという人も中にはいらっしゃると思うので、そこは、これはセーフティネットですから、救済という中で、いっときだけでもそういうのがあると助かるのではないかなと思いますので、ぜひ今後、高齢者からスタートするにしても、いろいろな世代、特に若い人たち、本当に若い人たちも視野に入れていただきたいと思いますので、それに関してのご意見もいただきたいと思います。","respondent":"竹田住宅課長","answer":"委員ご指摘のとおり、住宅の確保にお困りの方、様々な方がいらっしゃると思いますので、状況等を十分把握しながら、そういった方々が一人でも減るように、総合的に支援していきたいと考えております。","id":"exchange-026"}]},{"id":"topic-03","title":"踏切道手前部の視覚障害者誘導用ブロックの整備","agenda":"踏切道手前部の視覚障害者誘導用ブロックの整備","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"先ほどご説明もありましたけれども、今回は１４か所ということで、あと残りの１２か所も引き続き進めているということですので、ぜひよろしくお願いいたします。それと、踏切道内のところも設置していく方向だということだったのですが、今回は踏切手前のところだと。道内はどうなっているのかというところを伺いたいと思います。","respondent":"森道路課長","answer":"ただ、鉄道各線でも、それぞれいろいろな鉄道会社の中で、どういうふうに、いつから、どこから進めていくかというところを検討中だということですので、まだ設置時期は明確になっておりませんが、こういった動きがありますので。","id":"exchange-027"},{"speaker":"のだて委員","kind":"質問・要望","question":"各鉄道事業者、前向きに検討しているということで、それはよかったと思うのですが、今回設置する１４か所も、東急は手続未定ということなのか、そこを確認させていただきたいと思います。","respondent":"森道路課長","answer":"東急はこれに対してまずは設置を進めていきたいとしております。一応、国のほうでは令和７年度までにという形で指定がありますので、来年度、再来年度中には東急のほうで何かしら動かれるのだろうと期待しています。","id":"exchange-028"},{"speaker":"若林委員","kind":"質問","question":"いよいよ実施に至るわけですが、まずは東急電鉄というところで、しっかりと年度内、まずは着手、竣工というのですか、完成していただくということで、これはいずれにしても工事はしっかり着実に、安全・安心に進めていただくということと、いわゆる団体、また、いわゆる視覚に障害のある方への周知というのは、いつも周知、周知と言うのですけれども、周知の考え方。そこら辺、２点ほど。","respondent":"森道路課長","answer":"役所の近くに苗木原という踏切があります。しながわ中央公園のすぐ先にある踏切ですけれども、実際に現地に行っていただいて、ここに点字ブロックを設置する予定ですと。","id":"exchange-029"},{"speaker":"田中委員","kind":"質問・要望","question":"区内２６か所全てに早急に設置されることを願うのですが、これは個人的な感覚なので、事実と違ったら謝るのですけれども、やはり民鉄というか、東急・京急の対応は多分早いと思うのですが、ＪＲはなかなか対応が、いろいろな場面で想定されるのですけれども、例えばホームドアの設置も、基本は鉄道事業者がやるのですが、それを促す視点で行政が補助を出して、例えば東急の大井町駅も多分補助が出て。","respondent":"森道路課長","answer":"ただ、昨年度から区のほうでは東急とお話をさせていただいて、何度か話をする中で、まずは荏原中延２号からしっかりと取組を進めたいというお話があります。","id":"exchange-030"},{"speaker":"田中委員","kind":"質問・要望","question":"形状的に踏切の中でも、特にＪＲの踏切は、例えば西品川の権現台の裏の、狭い、車も通れないような踏切が、中央体育館とファミーユの間ではなくて、もう１個、大崎駅寄りに小さな、ファミーユの裏を抜けたところなどのような、ああいう形態的に平坦ではない踏切が、あと原踏切も勾配があったり、私が見ていて危険性が高いのはＪＲが多いのかなと感じられますので、全ての踏切が同等ではあるのですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"若林委員","kind":"確認","question":"質疑の中であえて確認したほうがいいなと思ったのは、これは、要するに奈良県で令和４年に、踏切内にいらっしゃった視覚に障害のある方が事故に遭われたというところに当然起因されて、だから、あえて言うと、踏切内を安全に歩行するということだけではなくて、もっと大事なのは、踏切内に今いるのかいないのかというのをご本人がしっかりと自覚をする。今、私はここから踏切内に入ったのだなと。","respondent":"森道路課長","answer":"区といたしましては、管理区域である外、手前部についてしっかりと注意喚起の点字ブロックをつけるということもありますし、中につきましては、今までいろいろな形態で、国のほうもいろいろな点字ブロックを考えられていたみたいなのですけれども。","id":"exchange-032"},{"speaker":"のだて委員","kind":"質問","question":"今回の踏切の数２６というのが、品川区道の交差する踏切の数ということで、ほかの都道・国道の踏切の数というのはあるのかどうか、伺います。","respondent":"森道路課長","answer":"品川区道と申しましたけれども、都道・国道でまたいでいるところは、今、踏切はございません。住吉踏切がありましたが、あそこは補助２６号線の開通によって、基本的には上に行けるようになったですので、対策としては、品川区内の踏切２６か所とご認識いただければと思います。","id":"exchange-033"}]},{"id":"topic-04","title":"公園児童遊園等維持修繕工事における未精算金の対応状況","agenda":"公園児童遊園等維持修繕工事における未精算金の対応状況","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回いろいろ再発防止策を行っていくということでご説明いただきました。そして、現在、１月から既に実施されているところが幾つかあると思うのですが、実施をしての状況というのですか、効果などを伺えたらと思います。","respondent":"高梨公園課長","answer":"各種取組の中で、１月から実施してきた今現在の状況といったところですが、こういった大きな問題を起こした後です、職員のほうも非常に慎重になってございまして、１件１件確認をしながら、情報共有を図りながら、現在進めている、こういった状況です。","id":"exchange-034"},{"speaker":"のだて委員","kind":"質問・要望","question":"今回対策も示されましたので、それをしっかりと実施していって、再発防止に努めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"西本委員","kind":"確認","question":"お支払いが終わりましたということなのですが、令和４年度５社、令和５年度６社、計５,０００万円余。それと、デジタルというか、ＤＸも含めて、どうやったらこういうミスを少なくできるのかということは、今の話だと、いろいろとデジタルのところでの改善はされているのだろうと思うのですけれども、そこをまずしていただいて、確認ということが必要なのかなと思うのですが、その辺はいかがでしょうか。","respondent":"高梨公園課長","answer":"公園課の中では、週１回、公園維持担当の係長によるチェックを行い、チェックを行った段階で、公園課長の私のほうに報告を上げて、私もそのときにチェックするというような形で進めておりますが。","id":"exchange-036"},{"speaker":"西本委員","kind":"質問","question":"片手間でやるようなものではなくて、経理は経理で専門的な知識であったりとか慣れとか、非常に必要なところだと思うので、私はこれを二度と繰り返さないということであるならば、やはり専門家を１人、別にそこだけでなくていいと思うのです、ほかのところも同じようなことが起きる可能性があるので、なので、人事は考えたほうがいいのではないかなと思いますが、いかがでしょうか。","respondent":"高梨公園課長","answer":"今回の問題につきましては、公園維持担当の中で日常的に発注する工事案件の台帳管理といったものは、担当係長の本分でもあると考えていますので、そこをしっかりとチェック体制を整えながらやっていくというものは、改めて付け加えられた事務というよりは。","id":"exchange-037"},{"speaker":"西本委員","kind":"質問・要望","question":"仕事の範疇だということは分からないではありませんが、その担当になっている方に専門的な知識がどれだけあるか私は分かりません、でも、職員なので、そうそう専門的な知識のある方が担当になっているとは限らないのではないかなという思いがあるので、できればとにかくチェックをしてもらうという、これは例えばＳＥ関係とかもたけている人が１人いてもいいぐらいではないのかなと私は思いますので、今後。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"}]},{"id":"topic-05","title":"東品川海上公園におけるＰａｒｋ－ＰＦＩ制度の導入","agenda":"東品川海上公園におけるＰａｒｋ－ＰＦＩ制度の導入","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今いろいろな意見が地域団体等から出されているということで、若干ご説明がありましたけれども、地域からどういった声が出ているのかというところを伺いたいと思います。それと、７月の説明のときには、公募を今年度の９月に行うというスケジュールだったのですが、今、スケジュールが延びてきているというところの理由も伺いたいと思います。","respondent":"高梨公園課長","answer":"スケジュールについてですが、７月の際は本年度内に事業者決定まで行えればということでスケジュールをお示しさせていただいたところですが、本日ご説明させていただいたとおり、地域の方々のご同意を得ない中での手続を進めるというものは。","id":"exchange-039"},{"speaker":"のだて委員","kind":"質問・要望","question":"いろいろ住民の方からも声が出されているということですので、ぜひそうした住民の声に寄り添っていただいて、寄り添ったということでこの期間が延びているということでもあると思いますので、住民の声をよく聞いていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"西本委員","kind":"質問・要望","question":"なので、そこの方々と一緒につくり上げていくということでの公募の条件をぜひ入れていただきたいなと思っているのです。それと、自由度です。Ｐａｒｋ－ＰＦＩをするときの自由度はどのぐらいを想定されているのかということと、それから、この予定でいうと、来年度に事業者が決定されて、令和７年度が設計・施工になるということは、令和７年度の予算に入るという認識でよろしいでしょうか。","respondent":"高梨公園課長","answer":"令和７年度に開業予定ということで、こちらについては前回ご提示させていただいたスケジュールと変えずに、令和７年度中開業ということを現在のところの予定としてお示しさせていただいてありますが、ここで行う設計・施工関係は。","id":"exchange-041"},{"speaker":"西本委員","kind":"質問・要望","question":"これは新しい取組なので、ぜひ成功してほしいなと思うのですけれども、この周辺は、やはり旧東海道というか、宿場関係、結構活発な団体がたくさんおられるのです。なので、そことぜひ一緒に考えていただきたいなと。そういう心配を、逆に、一緒につくってくださいという、そういう位置づけで展開していただきたいなと。いい事例を出していただきたいなと。これは私たちの視察のときもそうでしたよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"田中委員","kind":"質問・要望","question":"地域の方々の同意を得てというところなのですが、今も少し出ていましたが、地域というのは、一般的には町会だとか商店街だとかということが地域的には考えられる、特にここでいうと、いろいろなまちづくりの、特に運河まつりを運営する主体もありますし、旧道での宿場まつり等、しっかりやっていただいているところもありますし、もしお話ししていいのであればですが。","respondent":"高梨公園課長","answer":"最初に、施設を設置する位置についてですが、原則的なところで申しますと、先ほど答弁させていただいたとおり、区のほうでここに建てなさいというようにピンポイントで示すようなことはしないように考えてありますが、東品川海上公園は東京都下水道局のポンプ施設が。","id":"exchange-043"},{"speaker":"田中委員","kind":"意見","question":"西本委員もお話しされていましたが、我々、福山市に視察に行きまして、そこの先行事例を学んでまいりまして、大きな成功要因としては、まずは行政との連携ということですね、協業ということの必要性も感じましたし、その上で、地元をどれだけ理解し、しっかり対応してくださる業者を選んでいただけるかというところにかかりますので、ぜひそういった視点を通じて、すばらしいものになるように期待をして。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-044"}]},{"id":"topic-06","title":"しながわ区民公園リニューアルイベント","agenda":"しながわ区民公園リニューアルイベント","exchanges":[{"speaker":"西本委員","kind":"質問・要望","question":"これ、順延はできないのかしらと思っているのですけれども、というのは、やはりこれ、楽しい催しの内容になっているので、子どもたち、親御さんたちも含めて楽しめるし、公園が親しみやすいというか、こういうふうに変わったのだねとより実感していただけるいいきっかけではないかなと思うのですけれども、時期をずらしてもいいから。","respondent":"高梨公園課長","answer":"ぜひ当日、晴れることを願っているところですが、どうしても公園の中ということで、準備の関係もございまして、現在のところ、全ての同じようなイベントを別日で行うというのは準備の関係で難しいという状況ですが、ご提案を受けまして、例えば、今まさしく考案中ですけれども。","id":"exchange-045"},{"speaker":"西本委員","kind":"質問・要望","question":"期間をずらしてもいいから、やってほしいなと要望しておきたいと思います。それと、しながわ区民公園、水族館もそうなのですけれども、意外と他地域から来ている方が本当に多いのです。なので、やはりここは広く伝えてほしいなと思います。どこから来ましたということで調べたときがあって、大分外から来られていますので、ぜひそういう配慮もしていただきたいなと思いますが、いかがでしょうか。","respondent":"高梨公園課長","answer":"現在でもＳＮＳ等含めて電子媒体を使っての広い広報を考えてありますが、今ご提案のありました公園に来ていただいた方が目にできるような掲示であるとか、水族館にも区外の方が多くいらしていますので、水族館含め、そういったところの掲示による広報等。","id":"exchange-046"},{"speaker":"田中委員","kind":"質問・要望","question":"あるいは、こちらにも関係者がいらっしゃいますが、サッカーの大会を開催してもらうとか、そういう公園を利用する方も共に楽しめるようなイベントにできるともっといいのかなと思うのと、逆に、行政的な視点かもしれませんが、２か所のマンホールトイレというのは、意味合いは分かりますが、開催に当たってのイベントとして、こういうのをつくったという紹介はいいと思いますが。","respondent":"高梨公園課長","answer":"利用者の団体等と、日付も迫ってまいりましたので、どこまでできるかということもありますし、また別日でも、例えばしながわ区民公園のグラウンドのオープン記念の大会と冠をつけていただくとか、いろいろな連携の仕方があろうと思いますので。","id":"exchange-047"},{"speaker":"田中委員","kind":"質問・要望","question":"１点、確認でありますが、事務事業概要のところには、名称で少年野球場とか少年サッカー場という、少年ということの明記がありましたが、こちらの資料を見ると、こども野球場とかこどもサッカー場となっておりますが、女の子も、サッカーにしても野球にしても、既に積極的に利用していただいていますので、そういうことも踏まえて、今後、区の施設は名称として、少年野球場とかではなく、こども野球場。","respondent":"高梨公園課長","answer":"申し訳ございません、事務事業概要のほうが恐らく混同されるような表記になっていたと思いますが、今、条例施行規則等で規定している施設の名称としましては、こども野球場、こどもサッカー場となっていますので、これからはこの名前で統一していければなと思います。","id":"exchange-048"},{"speaker":"渡辺委員","kind":"質問","question":"それは、例えば児童遊園に来られた方も、全体を知ることはなかなかないと思うので、それぞれのよさ、何ていうのですか、たすきがけの論理ではないですが、サッカーをやっている子が水族館や児童遊園で楽しむ、児童遊園に来た親子が、こういうところで将来野球選手になってほしいなとか、何かそういう仕掛けというかストーリーのあるイベントを検討されてもいいかなと思いますが、いかがでしょうか。","respondent":"高梨公園課長","answer":"このたび１０年かかって新たに生まれ変わった区民公園ということで、新しくスタートすることになってありますので、今、委員からご提案がありましたようなイベントについても、どんどんその時代に合ったいいイベントを、様々な団体や。","id":"exchange-049"},{"speaker":"のだて委員","kind":"質問","question":"以前の説明のときにも工期の変更とかがあって、その具体化がされたのかなと思ったのですけれども、前回の説明のところからの変更点というのはどこになるのか、それともこれ全体がそうなのかというところを伺いたいと思います。","respondent":"北原河川下水道課長","answer":"今回につきましては、契約変更を受注者とも協議した上で正式に行うということで、工事の工期が決まったという形になりまして、委員がおっしゃったように、より具体的になったという形になります。","id":"exchange-050"},{"speaker":"のだて委員","kind":"意見","question":"より具体的になったということで、そうすると、前回の説明のところからあまり変更がないはずなのかなというところなのですが、前回の資料を見ると、前回は凍結工法でやるということになっていたのですが、今回はその凍結工法は変更するということですよね。なので、前回の説明からも結構変わっているのかなと思ったのですが、そこのところをもう少しご説明いただければと思います。","respondent":"北原河川下水道課長","answer":"凍結工法に関する変更というのが、前々回ですか、変更していたと思うのですけれども、それは取水No.４という、中流部の貯留管から第二戸越幹線に接続するというやり方の部分だったかなというところでして、今回は、シールドが到達する西品川公園のところの施工方法で。","id":"exchange-051"}]},{"id":"topic-07","title":"目黒川安全航行啓発活動の実施","agenda":"目黒川安全航行啓発活動の実施","exchanges":[{"speaker":"西本委員","kind":"質問","question":"今回８回目ということですが、これはどういう効果が得られていますか。大分落ち着いてきているのかなという感覚はあるのですけれども、周知がされていて、大分マナーが守られてきていることなのか、ただ、２日間ですよね、２日間以外になるとまたマナーが荒れてしまうなという状況なのか、それとも、大分周知されていて、目黒川の使い方というか、うまく使われているのかどうか、その状況を教えてください。","respondent":"北原河川下水道課長","answer":"この委員会に属している皆さんからも、やはりこういった取組が浸透してきているというところで言っていただいておりまして、ただ一方で、やはり桜の時期の舟運というのも人気が高まっているところもありまして、船が非常に増えてきているということもありまして、また。","id":"exchange-052"},{"speaker":"西本委員","kind":"質問・要望","question":"やはりコロナ禍が終わったということもあって、多分ここは人気だと思うのです。毎回毎回やって、それでしつこくしつこく言っていかなければいけないことだと思うのですけれども、安全配慮という形で、これからも頑張っていただきたいなと考えています。決して事故がありましたとか、そういう報告をいただくことがないようによろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"田中委員","kind":"質問・要望","question":"それと、少し細かい話ではありますが、正式名称としては五反田船着場という名称がふさわしいのかもしれませんが、せっかくああやってリバーステーションというようなすばらしい名前もつけて、より親しんでもらうということもありますので、表記の問題でありますが、どちらを売りに出そうとされているのか分かりませんが、より広く発信をするという意味でも。","respondent":"北原河川下水道課長","answer":"五反田船着場とリバーステーションの名称につきましては、確かにご指摘の部分がありますので、表記をきちんと、どういう場合、どうやって使うのだというのを決めて、より船着場が浸透していくように努めてまいりたいと考えています。","id":"exchange-054"}]},{"id":"topic-08","title":"その他","agenda":"その他","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"インターネットでの申込み件数を増やしたということで、電話とネットではできる品目数がどれだけ違うのかというのを伺いたいのと、やはり夜というのは恐らく仕事をしている方がよく利用されるのかなと思うのですけれども、そうした方への影響というのですか、区の考えているところと、今後そうした方にどう対応していくのかというところを伺いたいと思います。","respondent":"品川品川区清掃事務所長","answer":"夜の対応ですが、これは我々の見込みとしてというところもあるのですけれども、日中、高齢者の方等がいろいろ申し込んだりするような時間帯については、電話のほうを充実させていただいて、夜間については、若い方というか。","id":"exchange-055"},{"speaker":"西本委員","kind":"質問","question":"それは日中聞けばいいということではあると思いますので、別に夜間やる必要はないのかなという思いはありますが、ただ、昨日も申し上げましたけれども、やはりインターネット、分かりやすいように、できれば絵とか何かあるといいなと思うのですが、判断がつかないものを、インターネットで判断がつきやすいものにしていただくと、さらに利便性が高まるかなと考えていますので、いかがでしょうか。","respondent":"品川品川区清掃事務所長","answer":"夜間ですので、多少人数が少ない時間帯であるということはありますが、おおむね２４０万円、年間で削減できると見込んでおります。それから、インターネットのほうは、努力して、使いやすいようにやっていきたいと、このように考えております。","id":"exchange-056"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/250442?Template=document&Id=4402#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":55694,"voices":170}},{"id":"r06-20240227-9","meetingId":"r06-cm02","date":"2024年2月27日","dateIso":"2024-02-27","committee":"文教委員会","time":"午前１０時００分～午後 ０時２７分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を66件抜き出しています。","topics":[{"id":"topic-01","title":"令和５年度品川区教育委員会事務事業の点検および評価の報告書","agenda":"令和５年度品川区教育委員会事務事業の点検および評価の報告書","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"それと、学識経験者の方の評価の２１ページからになっています特別支援ですけれども、研修の充実なども今後の課題とありましたが、現在、支援員は、資格はどのような感じの方が入っているのか、要件はあるのかということと、それと、これから全校にということなのですけれども、これ以外に、支援員の方、今までは数の関係なのですけれども、支援員がいる方のところは、学習支援員ですとか。","respondent":"柏木学務課長、唐澤特別支援教育担当課長","answer":"私からは、学校給食に関わる部分の質問にお答えいたしますが、総合評価「Ｃ」のところですけれども、大きな理由としては、まず、今年度、学校給食無償化を実施いたしましたが、その実施方法等について、まだ検討する、１年やってみて。介助員につきましては、個々の子どもの実態に応じてつけるものですから、発達障害教育支援員をつけている学校においても、介助員を配置している学校はあります。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"特別支援のほうは、資格はないということなので、やはりそういう意味では、本当に研修の充実はすごく大事だなと思って、私、支援員ではないのですけれども、コーディネーターに配置された教員の方が、新任の方だったので、いきなりコーディネーターというか、発達支援員の専門家になれと言われて、結構大変な思いをしてという事例もあったので、特別支援教育は、本当に専門性が大切にされると思いますので。","respondent":"柏木学務課長、唐澤特別支援教育担当課長","answer":"それともう１つが、アレルギー等でお弁当の対応の方への給食相当額の支給方法について、今ご意見をいただいていますので、来年度に向けて、そこについては、今、学校を含めて検討しているところになります。ただ、次年度、まず発達障害教育支援員を、全校、小学校前期課程に配置しますので、その成果も振り返りながら、教育委員会として検討していきたいと考えております。","id":"exchange-002"},{"speaker":"ゆきた委員","kind":"質問","question":"プレス発表でも、４月から順次配置予定ということで、支援員の確保でＮＰＯ法人に委託しているところだと思われますが、今後の方向の計画性というようなところがあれば、お聞きできればと思います。","respondent":"唐澤特別支援教育担当課長","answer":"ＮＰＯ法人ではなく、学研エル・スタッフィングというところに派遣で依頼しております。次年度については、派遣でこれを実施していく形ですので、今後、そうした形で進めていく予定となっております。４月配置に向けて動いていくという形でやっております。","id":"exchange-003"},{"speaker":"ゆきた委員","kind":"質問","question":"４月に全校という認識でよろしいでしょうか。令和４年度から次年度にかけてのニーズに応えての速やかな派遣事業であるだけに、十分に考慮されていることだと思われますが、より一層のモデル校の現場のヒアリングに十分に力を入れて進めていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"}]},{"id":"topic-02","title":"第６回品川区学事制度審議会の実施報告","agenda":"第６回品川区学事制度審議会の実施報告","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"それと、毎回言わせてもらっているのですけれども、学事制度審議会の、今回は特に実施報告ということなのですが、今回、中間報告が出されてパブコメということなのですけれども、その中間報告は、結局、文教委員会に一度も出ていないということで、今回も添付されておりませんが、学事制度審議会を実施しました、パブコメは何件でしたというだけの報告なのですけれども。","respondent":"柏木学務課長","answer":"学事制度審議会の実施報告について、議会に何を求めているのかですけれども、内容的には非公開で実施をしておりますので、いろいろご意見をいただいていますけれども、話せる話、話せない話があるということはありますけれども、学事制度審議会を適切に実施しているということを。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"パブリックコメントをされた中間まとめ答申は、内容も少し拝見したのですけれども、結局、結論的なことは何もおっしゃっていないなと思ったものの、こちらについてはパブコメにかかっているわけで、なぜこの内容については文教委員会に報告してくれないのでしょうか、それは委員長からも求めたのかということも知りたいところではあるのですが、なぜなのかという、なぜこれは報告されないのか。","respondent":"柏木学務課長","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"安藤委員","kind":"意見","question":"「ちょっと議会軽視だろう、それは」という声も上がりましたが、やはり資料を見ておいてねということだと、それを言ってはおしまいよというか、やはりしっかりと資料として提示するということが、私は議会を重視するというか、あるべき姿だと思いますので、厳しく指摘したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"石田（し）委員","kind":"質問","question":"今、安藤委員からの質疑の中で、では、この学事制度審議会を実施して、議会の意見は、どのタイミングで言えて、どのタイミングで反映ができるのかということを教えてください。","respondent":"柏木学務課長","answer":"それについて、方向性などが答申に出てくるという形になります。その後、実際の制度設計をしていくところでは、また文教委員会等に報告しながら、そこでご意見はいただける。反映できるものは反映していきたいと考えています。","id":"exchange-008"},{"speaker":"石田（し）委員","kind":"確認","question":"そうすると、答申が出て、報告があって、そのときにいろいろな質疑の中で議会の意見を聞いて、最終的に制度設計の中に落とし込んでいくというようなスケジュールということ、それをもう一度確認でお願いします。","respondent":"柏木学務課長","answer":"そのように、今、考えてあります。","id":"exchange-009"},{"speaker":"石田（し）委員","kind":"質問","question":"先ほどの答弁は、私はやはり、そこは議会に対して、資料がネットにあるからネットで見てくださいということでは、私は、これは議会軽視と言うしかない。では、逆に言えば、ネットに出している資料をなぜ委員会に出せないのですか。逆の観点からすれば、なぜ出てこないのかというところを、もう一度改めて説明してください。","respondent":"柏木学務課長","answer":"いただいた意見につきましては、次回以降は、きっちりそこら辺は対応していきたいと考えています。","id":"exchange-010"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"我々もそれはできる限りいろいろなところで、別の資料は探したりはしますけれども、基本的に、必要最低限というか、その部分の資料に関しては、それは委員長にもですけれども、ぜひそこは委員長とすり合わせしていただいた中で、できる限り資料提供はしていただきたいと思うので、そこはお願いをして終わりますけれども、よろしくお願いします。","respondent":"つる委員長","answer":"委員会としては、正副でまた改めてでよろしいですか。","id":"exchange-011"},{"speaker":"ゆきた委員","kind":"質問","question":"パブリックコメントで、８名から３１件のパブリックコメントがあったということで報告がありますが、このパブリックコメントを受けての公表は４月の予定とのことで、パブリックコメントを上げていただけた区民への対応を、具体的にどのような返信とか、そういう対応をされているのか具体的にお聞きできればと思います。","respondent":"柏木学務課長","answer":"意見を寄せられた方への対応ですが、こちら、パブリックコメントの回答につきましては、ホームページに掲載するというふうに考えてあります。","id":"exchange-012"},{"speaker":"ゆきた委員","kind":"意見","question":"３１件で単純に８名で割ったとしても、１名で４件の意見を上げてくれているということは、強い思いがあってのことだなというふうには感じています。なおさら個人的なところで回答されていないということですけれども、機械的な回答でないようにというふうに思います。十分考慮されていることだと思われますが、より一層丁寧な対応をしていただくようにお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"高橋（し）委員","kind":"確認","question":"先ほど、議会に云々という話が出たのですけれども、ご答弁の中で、答申が出て、そこで議会に示して意見を聞くという話があったので、ということは、中間答申に対する議会の意見は、そのときには聞かない、パブコメが出たものも聞かないつもりであった。答申が出てからだけ議会の質問の中の議論をしてもらうというのが教育委員会の姿勢ということで確認していいですか。","respondent":"柏木学務課長","answer":"中間答申を出させていただいて、区民の方からパブリックコメントをいただきました。それを踏まえた上で最終的な答申を受けて、その中でまた具体的な制度設計をする上で、議会からもいろいろご意見をいただきたいと考えています。","id":"exchange-014"},{"speaker":"高橋（し）委員","kind":"確認","question":"学事制度審議会で話し合っている内容に関して、議会から何も聞く性質のものではないと今おっしゃいましたけれども、そこは確認していいですか。","respondent":"柏木学務課長","answer":"今回の学事制度審議会につきましては、そこで、途中、途中、ご意見をいただく性質の審議会ではないと考えています。","id":"exchange-015"},{"speaker":"高橋（し）委員","kind":"質問","question":"話し合っている審議会の内容で、次にこうしろとかではないのです。今、こういうことを話し合って中間報告が出た、議会としては、こういう意見が出たということをやる機会が要らないということですか。審議会の中身に中間報告、進める内容にここの議会の中身を反映させろという意味ではないですから、審議会は審議会で話合いをきちんとしていただければいいのですから。","respondent":"柏木学務課長","answer":"文教委員会で審議会の実施報告をさせていただいて、そこでいただいた意見については、審議会のほうに、議員のほうからこういう意見があったということは、必要に応じて伝えしていますけれども、そういう形での議会からの意見は、お伝えをしているということになります。","id":"exchange-016"},{"speaker":"高橋（し）委員","kind":"質問","question":"そういうものが出てこなかったので困ってしまいましたと伝えてくれるのですか。出てこなくて、議会では、どうしてそういう資料を全然出さなかったのだということを審議会に伝えていただくわけですか。おっしゃったように、ご意見が出たということを伝えていただければいいですけれども、そういうことをやるつもりがなくて、ここまで来たという認識でよろしいですか。","respondent":"柏木学務課長","answer":"ただ、その中でも、いただいた意見につきましては、繰り返しになりますけれども、適宜、審議会のほうには報告させていただいて、そこでいただいた意見については、取り込めるものについては、審議の中でお話はされていると考えています。","id":"exchange-017"},{"speaker":"高橋（し）委員","kind":"確認","question":"もうやめますけれども、要するに、結果としてはこういう結果になっているわけですから、教育委員会として、こちらに資料を出さないで、委員の方の意見を聞いてどうするかは審議会の話ですからあれですけれども、そういう機会をいただけなかったという事実だけは残ったので、そこは確認しておいていただけますか。","respondent":"柏木学務課長","answer":"今回は、中間答申等を資料としてお示ししなかったという部分については、いただいた意見におきまして、次回等につきましては、そういうことのないように努めていきたいと思います。","id":"exchange-018"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"でも、やはり８名かという気がしておりまして、子どもたちの教育に関わることなので、本当はもっと関心のある方がたくさんいらっしゃるのではないかというふうに思っていて、今後については、もう少し皆さんがパブリックコメントに気がつきやすいような募集の仕方も考えていただきたいのですけれども、現時点で、どのような工夫をされているか、もしご回答いただけることがあったら伺いたいのですが。","respondent":"柏木学務課長","answer":"１つ目のパブリックコメントをいただいた方への回答ですけれども、前回、第６回の審議会でも、委員のほうから、丁寧な寄り添った回答をしたいという意見をいただいていますので、審議会のほうでは、そういう形で進んでいくものと考えています。","id":"exchange-019"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"３１件、意見が出てきたということは１つ成果かと思いますけれども、８名の方というのは、少し私の評価としては少ないかなというふうに思っておりますので、今後、一層の工夫をしていただきたいと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問","question":"今後の感染症の蔓延を防ぐために、区教委と、あと、子ども未来部保育課としては、どのような対策や啓発を行っていくお考えがあるのかということをお伺いしたいのと、それとあと、２月１４日、１５日に学校閉鎖があるということでしたけれども、３日目からは再開されたというふうなことだと思うのですけれども、学業への影響ですとか、そのフォローみたいなものはどうなったのかということと、あと。","respondent":"柏木学務課長、立木保育課長、丸谷教育総合支援センター長","answer":"インフルエンザの流行を防ぐ対応ですが、まずは学校については、基本的な感染症対策の徹底と考えています。幼稚園・保育園に関しましても、手洗い、うがい、換気、それから消毒、あと、保護者の方への周知、それから保健だより等で感染予防についての啓発等。学級閉鎖中の学習保障についてですけれども、各学級で課題を出すなど工夫をしておりますが、多くの子どもたちが感染症で発熱しているとか。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問","question":"ほかにも学校閉鎖という例があったのか、先ほどの、今回は特に保護者からの相談ですとか報告はなかったということなのですけれども、今後、そういった事例がやはりあるのではないかと思うのですが、相談を受けた際に、どのようなアイデアがあるのかというのはいろいろあると思うのですが、すまいるの活用ですとか、事前に対応策のガイドラインみたいなものは考えておいたほうが。","respondent":"柏木学務課長","answer":"ただ、保護者の対応、どうしても休めないですとかという部分については、何かしら考える必要もあるのかなと思いますが、現状のところは、そういうガイドラインは特にはございません。","id":"exchange-022"},{"speaker":"吉田副委員長","kind":"質問","question":"先日の学校閉鎖のご報告をお電話でいただいたときには、たしか教員の方でも体調不良の方が複数出られたということもお話しいただいたのですが、子どもたちから教員へという感染もあるので、大体同じような感じがするのかもしれないですけれども、教員の方の体調不良については、学級閉鎖になるようなところにそういう方が多いと思っていいのでしょうか。その辺、ご報告いただければと思います。","respondent":"柏木学務課長","answer":"教員が体調不良等でお休みした場合には、担任を持っていない方、または副校長とかが、そのクラスに代わりに入るということが通常のやり方かと考えています。","id":"exchange-023"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"それで、学校に関しても、子どもたちのことを第一に考えていただきたいと思いますが、やはり働いているというか、教員の方の労働環境としての健康維持といいますか、そういうこともぜひ、これからもまた次の感染症の流行とかにも備えるべきと思いますので、その辺について、既に議論になっているのか、もしなっていないのであれば、今後ぜひ考えていただきたいというふうに思うのですけれども。","respondent":"柏木学務課長","answer":"ただ、今後、新たな感染症対策について、区健康推進部が中心になりますけれども、そこが検証等を現在しておりますので、そちらの報告も受けて、今後、検討する必要があるのかと考えています。","id":"exchange-024"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"ですので、所管が別かもしれませんけれども、その中にやはり学校現場でのこともぜひ入れてもらうというのか、入れるように、教育委員会としても働きかけていただきたいと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"せお委員","kind":"質問","question":"小・中学校のほうなのですけれども、こういった学級閉鎖とか学校閉鎖までいかなくていいのですけれども、それも含めて、今、少し多めにお休みしているみたいな、そういった情報を、関連するすまいるとか、児童センターとかもそうだと思うのですけれども、あと、保護者にも、情報提供はどのように行っているのでしょうか。","respondent":"柏木学務課長","answer":"教育委員会から、全体的にこうだという形では保護者等には特には出していませんが、各学校で発症状況等ありますので、学校のほうから適宜、そういう情報提供はされているものと考えています。","id":"exchange-026"},{"speaker":"せお委員","kind":"質問・要望","question":"正直、うちの学校もすごいみたいなのですけれども、情報が来ていないというところもあって、あと、すまいるのほうでも分からないみたいなお話があったりしたので、ぜひ情報提供して換気していただくとか、できることは限られているとは思うのですけれども、そのクラスで少し多めに発熱者が出ていて、ほかの子たちでマスクをさせたいなという親もいらっしゃると思うので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"}]},{"id":"topic-03","title":"令和６年度新入学 学校選択の希望申請理由に関する調査結果","agenda":"令和６年度新入学 学校選択の希望申請理由に関する調査結果","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"重大事態が今年度に入って１０件に上るということで、１つ１つの案件が、その子どもにとってはかなり深刻ということで、しかも、重大事態は氷山の一角ですから、重大事態以前の認知された大小のいじめもたくさんあるということだと思います。品川区で、このいじめ重大事態が相当多いという事実は、やはり正面から認めて、今後の改善に生かすべきだと思うのですけれども、その点、いかがでしょうか、伺います。","respondent":"丸谷教育総合支援センター長","answer":"こうしたいじめの重大事態が１件でも減るように、しかしながら、法に基づいて対応していくことは大切なことですので、そこと合わせて、教育委員会としてしっかりと行っていきたいと考えております。","id":"exchange-028"},{"speaker":"安藤委員","kind":"質問・要望","question":"いじめを防止して解決できる学校をどうつくるのかが求められていると思いますし、今、センター長も、今後の対策などのお話もしていましたけれども、大事になってきていると思います。だから、これは、私としては、逆行なのではないかと思わざるを得ないのですが、こういう規定が子どものいじめ解決につながると考えているとしたら、区教委のお考えを伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"引き続き、学校に対しては、子どもが一人で悩まないようにというような指導を継続していくように働きかけてまいります。","id":"exchange-029"},{"speaker":"安藤委員","kind":"提案","question":"今回の、ともすれば、様々予算が、対策も出されております。それ自体は必要なことだと思いますけれども、それと同時に、根本の学校の環境をしっかりとそうしたものに変えていくということ自体が、言わば予防対策です、すごく大事だと考えていますので、これに関しては、今後、様々、また機会を捉えて提案をしていきたいと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"},{"speaker":"ゆきた委員","kind":"質問","question":"条例の改定のところとは少し外れてしまうのですけれども、１月４日から、区長部局によるいじめ相談窓口を設置するというところで、ここが今回、児童、保護者からしても受け手として大きく変わったところだと思われます。区長部局での対応が、今後、文教委員会にも報告があるのか、縦割りというか、この辺について教えていただければと思います。","respondent":"丸谷教育総合支援センター長","answer":"お互い連携をして進めているものですので、適宜、文教委員会でも報告ができるようにしていきたいと考えております。","id":"exchange-031"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"確認させていただきました。こちらは文教委員会の中でも、寝屋川市の攻めの情報収集ということで、何回も引用して要望してきたところでもあるので、発信先が異なっていても、現場に関わってくるといったところは、報告事項の共有ができればと思いますので、こちらは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"１０件もあるのかと、けしからんではなくて、それだけ深刻な学校の状況があるという中で、どうやって対策をするかという１つの検討材料であって、私は、この数、もちろん大事なのですよ、数を減らすことは大事だし、きちんと数を出すことも大事なのですけれども、私は、そこよりも、なぜそうやって起きているのかということをぜひきちんと考えて、それを解決していくということが大事なので。","respondent":"丸谷教育総合支援センター長","answer":"いじめ重大事態の数に意識をとらわれないでということだと思いますけれども、起こっているいじめの重大事態に対して、どのように対処していく、子どもたちを救っていくかということを丁寧に丁寧に行っていくことが、まずは大事だと思いますので、起こってしまったものに対しては。","id":"exchange-033"},{"speaker":"石田（し）委員","kind":"確認","question":"それは区長部局の窓口もそうだし、ほかの様々な窓口にとっても、あくまで入り口はそこかもしれないけれども、しっかりとグリップをして、教育委員会が学校と連携をして解決に向かっていくということでいいのか、そこだけ確認します。","respondent":"丸谷教育総合支援センター長","answer":"いじめの被害に遭っている児童・生徒に寄り添った形での対応ということで、学校と教育委員会しか対応しないとか、そういうことではなくて、オール品川で解決に向けて動いていきたいというふうに考えております。","id":"exchange-034"},{"speaker":"せお委員","kind":"質問","question":"今回この条例改正が、「区長部局によるいじめ防止等の対策を総合的かつ効果的に推進していくことから」ということで書かれているのですけれども、先ほど、ご答弁でも、いじめ防止対策というのはいろいろなことがあって、それをやっていくというセンター長からもお話があったのですけれども、その中でも、やはりどれも重要なのですけれども、いじめが起こらないような学校現場をつくるということは大切なので。","respondent":"丸谷教育総合支援センター長","answer":"一方で、我々教育委員会、学校を支えていく身としては、いじめが起こらない学校風土づくりを目指して推進していきたいと考えておりますので、もちろん教育委員会も起こっているいじめ対応もしていきますけれども、そこは役割が少し異なってくるかなというふうに考えております。","id":"exchange-035"},{"speaker":"せお委員","kind":"質問・要望","question":"やはり区長部局で環境を変えることへのアドバイスはできないだろうとは思っていないのですけれども、やはりそういった学校環境をつくるというのは教育委員会が、やはりプロもたくさんいらっしゃると思うので、やはりそこは中心になって行っていただきたいと私も思っていますので、ぜひよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"高橋（し）委員","kind":"質問","question":"全件を共有して把握するというふうに総務委員会の資料には出ているので、その点をお尋ねします。それで、いじめ対策協議会は月一にやるということなのですけれども、こことの情報共有の関連についてはいかがでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"いじめ対策協議会の中で、それぞれの事案についての進捗状況でしたり、学校が対応できているもの、または、対応しきれないで困っているもの、そういったものをお互いに意見交換しながら対応を練っていくと、そういったいじめ対策協議会というものも４月からの本格運用に向けて。","id":"exchange-037"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ありがとうございました。情報を共有して、両方のセクションで対処するということは非常に大事だと思います。どちらが中心になってというのは、事案によって違うのだと思うのですけれども、今お話にあったようなフローで、しっかりと共有していっていただきたいと思います。要望で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"高橋（伸）委員","kind":"質問","question":"ご説明ありがとうございました。そこは先生にお預けするしかないのかなと思うのですけれども、今度、４月になると、新学期が始まって、新しい時期になって、先生の、特に校長を含め管理職の方が転出・転入してくるではないですか。","respondent":"丸谷教育総合支援センター長","answer":"いじめを受けているお子さんが、相談できない子もいるのではないかというところですけれども、今、１人１台端末を用いて、日々の健康観察を行うようにしたいというふうに考えて、今、計画を詰めているところです。","id":"exchange-039"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"そういう子どもたちの声の集約といいますか、そういう仕組みは、どういうふうになっているのか、その点についても伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"児童センターの職員の方が相談を受けた場合ですけれども、実際に区内の事例として、児童センターで相談を受けて学校に連絡が来たというようなケースもありますので、そこは学校がしっかりと地域の各施設と日頃の関係を密にしていくということが大切かというふうに考えております。","id":"exchange-041"},{"speaker":"吉田副委員長","kind":"質問","question":"これ、本当に対応が難しいといいますか、いっぱい相談窓口はあったほうがいいのだけれども、いっぱいあるがゆえに、自分の場合はどこに相談しようというふうな迷いにつながってしまうということも実際はあると思いますので、それと、本当に申し上げにくいのですけれども、親御さんからの相談とか、それから、子ども、当事者からも、子どもからいったら、保護者に相談して。","respondent":"丸谷教育総合支援センター長","answer":"そういった意味では、学校の対応力ですとか、そういったところをしっかりと上げていかなければならないというふうにも考えておりますし、保護者の皆様にも、しっかりといじめ対応について、学校の基本的な方針ですとか、そういったところをご理解いただく、そのためには。","id":"exchange-042"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"高橋（し）委員","kind":"確認","question":"すみません、先ほど、確認することを忘れて、ごめんなさい。その中の３つ目に、学校教育法の中の出席停止、あるいは、そのほかの必要な措置を勧告できるということがあるのですけれども、最終的な、例えば出席停止とすると校長先生、あるいは、そのほかの措置も校長先生、つまり、最終的な児童あるいは生徒に対する措置の責任は、学校にあるということでよろしいですか。","respondent":"丸谷教育総合支援センター長","answer":"それぞれの措置の最終的な判断は学校になりますけれども、出席停止につきましては、教育委員会の判断ということにもなりますので、そういったところは学校と教育委員会がしっかりと勧告を受けた後に、真摯に受け止めながら対応していくという形になります。","id":"exchange-044"},{"speaker":"高橋（し）委員","kind":"意見","question":"区長部局での勧告を受けたときに、教育委員会および学校現場が、今お話にあったように、どのようにその措置をどうするかとかというところをしっかり、今お話があったように、きちんと検討して、本当に児童・生徒が救済されるように、そして学校がその後をしっかり運営できるような形で進めていっていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-045"},{"speaker":"安藤委員","kind":"質問","question":"これは品川区だけではないですけれども、教育環境の問題もあります。最後に質問ですけれども、そういう観点は、一度前にも伺ったら否定されましたけれども、そういう自覚を私は持つべきなのではないか、品川区の競争的な、管理的な教育が、こういったいじめの件数の増大につながっているという自覚を、私は持つべきなのではないかと思うのですけれども、最後にご答弁をお願いします。","respondent":"丸谷教育総合支援センター長","answer":"ただ、ご指摘いただいたような、時代に合っていないものは改善していくべきものというふうに捉えておりますので、その辺りは、我々もしっかり時流を捉えて、学校にも働きかけていきたいというふうに考えております。","id":"exchange-046"},{"speaker":"安藤委員","kind":"提案","question":"そういうご答弁ではないかとは思うのですが、そこについては、今後も、子どもの生の声も集めながら、いろいろ改善の提案などもさせていただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-047"}]},{"id":"topic-04","title":"西五反田保育園の改築","agenda":"西五反田保育園の改築","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"２点なのですが、認定こども園化に向けて隣接する敷地を活用するということですけれども、具体的にはどのような内容なのかお伺いしたいのと、それと、西五反田保育園の民営化を視野に入れて検討とありますけれども、これは、当面５園という民営化方針が６園になるということなのでしょうか。なぜ今回、西五反田保育園を民営化検討するのか、その理由を伺います。","respondent":"立木保育課長","answer":"民営化方針との関連ですけれども、今回のこの西五反田保育園の改築に関しましては、民営化ガイドラインの中で進めている改築・民営化の部分とは直接リンクはしてございませんで、あくまでもぷりすくーる西五反田と西五反田保育園との関係性の中で、今回。","id":"exchange-048"},{"speaker":"安藤委員","kind":"質問","question":"シルバーセンターも併設すると思うのですが、それはどうなるのかということと、それと、なぜ西五反田保育園は民営化を視野に検討するのかという理由も伺ったので、よろしくお願いします。","respondent":"立木保育課長","answer":"そちらに関しては、施設更新に合わせて民営化も検討するということで進めてきておりますので、ぷりすくーる西五反田と西五反田保育園の今後については、そういった部分も視野に入れて検討していくです。","id":"exchange-049"},{"speaker":"安藤委員","kind":"意見","question":"更新は必要だと思っていますけれども、本会議でも、民営化して株式会社立になると、人件費率と平均勤続年数で明確な差が出ていまして、区立は人件費率７３.９％で、株式会社立４８.２％ということで、勤続年数、区立１２.９年に対し、株式会社が６.３年と半分ということで、やはり今ある区立園を民営化することはやるべきではないと思いますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-050"}]},{"id":"topic-05","title":"病児保育施設における委託費の返還対応","agenda":"病児保育施設における委託費の返還対応","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"少し残念なことだなと思うのですけれども、廃止検討ということがありますけれども、仮にここが廃止になった場合は、区としては、代わりの、今回、８名定員ということですけれども、病児保育施設の整備というか、それはお考えはあるのでしょうか、ないのでしょうか、伺いたいと思います。","respondent":"立木保育課長","answer":"さらに今回の施設が閉鎖になりますと、２施設になってしまいますので、今現在も鋭意新しく事業をやっていただけるクリニックを探しています。品川、荏原、両医師会にも働きかけをしながら、新たな施設を、できるだけ早く開設をしてまいりたいと考えているところです。","id":"exchange-051"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"それで、ある意味、発覚したということなのですけれども、これ、逆に、クリニックとしては、保育士確保ができていなかったから断ったというふうにとれたのだけれども、８名定員だけれども、例えば２人しかいないから、６人しかとれないよということだったのか、それとも、２人しかいなかったのに８人とっていたのか、８人以上だからとれないというふうにした、その辺は改めて教えていただきたいのと。","respondent":"立木保育課長","answer":"今回、大分前より、クリニックに保育士がいない状態で、委託費を受けながら預かっていなかった期間がある中で、そのまま事業を継続することの是非についても区のほうで検討しなくてはいけない部分がありますので、そこは慎重に判断をさせていただきたいと思っているところです。","id":"exchange-052"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"この病児保育施設の、ある意味、難しさというのか、辞められてしまう、今回この件があったからということも発端なのかもしれないけれども、やはりほかのところも辞めたりされていて、非常に難しいですよね、多分、保育士の確保もそうだし、運営面も含めて。これは要望ですけれども、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"せお委員","kind":"質問","question":"今はもう、今後、２施設になってしまうということで、探していくというご答弁だったのですけれども、これは、いわゆる小児科に限って探していくのか。どういう方向性なのか教えてもらっていいですか。","respondent":"立木保育課長","answer":"ただ、クリニックに限ったことではなく、そのほかの施設でも、施設的な部分ですとか、医療機関との連携がとれれば実施が可能となっておりますので、医師会やクリニックだけでなく、一般の保育運営事業者の方々でも、そういったところができないかどうかということは。","id":"exchange-054"},{"speaker":"せお委員","kind":"意見","question":"例えば、先ほど、始まる前に話していましたけれども、今は未就学児だけなので、小学校一、二年生とかも、対象のところとかも、少しここからずれてしまって申し訳ないですけれども、広げていく、そういうお声はすごく、私も含めてですけれども、すごくいただいているので、そこも含めて考えていく必要があるのかと思っているので、今後、ぜひ検討をお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-055"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"すみません、委員会時間を過ぎているのに質問します。それをしなかったことで、言うなれば、委託費をもらったクリニックに対して、区としてどういう対応といいますか、返還を求めるだけではなくて、どのような対応が考えられて、どういうことをされようとしているのでしょうか。","respondent":"立木保育課長","answer":"区といたしましては、関係機関とも連携をとりまして、こういった事案に対して、どういった対応をとるべきかということを相談し進めているところです。","id":"exchange-056"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"最後、そこだけしっかりやっていただきたいというところで、いかがでしょうか。","respondent":"立木保育課長","answer":"やはり保育士が雇えなかったという事情はありながらも、報告をきちんと区とやり取りしていなかったという部分がありますので、そこの部分に関しては、しっかり関係機関と連携をとりながら対応してまいりたいと思います。","id":"exchange-057"},{"speaker":"石田（し）委員","kind":"質問","question":"今の部分で、５年間、区が把握できていなかったというのは、もちろん不正で申請されていたのが悪いのだけれども、そのチェック体制がとれていないというのは、逆に問題ではないかと思うのだけれども、そういうチェック機能は、どういう形で、要は、お支払いされている、それは保育だけではないかもしれないのだけれども、どういう形でチェックされているのかということを教えてください。","respondent":"立木保育課長","answer":"全く預かっていなかったということではなく、預かっている日もあります。全く実績がないということではないので、そういった中で、区としても見抜けなかった部分がございましたので、チェック体制、チェックの仕方も変えていかなくてはいけないと考えているところです。","id":"exchange-058"},{"speaker":"吉田副委員長","kind":"確認","question":"今のご質問に関連すると思うのですけれども、私も幾つか区の事業、仕様書も確認させていただいていますけれども、こういうときは、仕様書には、例えばこういう場合には区へ報告するとか、その辺のことは明記されていないのでしょうか。その辺を伺いたいと思います。","respondent":"立木保育課長","answer":"特に個別のケースに関しまして、具体に仕様書に記載することはなく、あくまでも契約行為ですので、履行が前提のもとでやってありますので、そこに何か不履行になるような内容があれば、それは協議をするという、そういうような記載はありますが、細かい部分に関しては。","id":"exchange-059"},{"speaker":"吉田副委員長","kind":"質問","question":"もしそうでないのであれば、今後の仕様書の記載の仕方も検討されるべきではないかと思う。もちろんチェックもそうですけれども、チェックの前に、やはり先方の、こういう場合はこういう報告をするようにとか、そういうことが、先に規定がないと、チェックもしにくいかなと思うのですけれども、その点についていかがでしょうか。","respondent":"立木保育課長","answer":"すみません、先ほど説明の中で、履行が難しい場合にはというような言葉をつけたのですけれども、そのような表現にはなっていなくて、仕様書に記載のない事項については、甲乙双方で協議するというような記載になってあります。","id":"exchange-060"},{"speaker":"吉田副委員長","kind":"質問","question":"こういう事例が出てしまったので、それに基づいたお考えを伺いたいと思います。","respondent":"立木保育課長","answer":"契約書に約款も添付して契約しています。そちらは経理課のほうでやってありますので、そちらと連携しながら、こういった事例の対処は考えてまいりたいと思います。","id":"exchange-061"}]},{"id":"topic-06","title":"保育所の空き定員等を活用した未就園児の定期的な預かりモデル事業","agenda":"保育所の空き定員等を活用した未就園児の定期的な預かりモデル事業","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"しかも、今回のように地域の在宅のお子さんの預かりまでするとなると、子どもを預かるということですから、荷物を預かるのとはわけが違うわけで、日々、固定しない子どもを、従来の保育園のクラスにも入ってもらって交流するとかとなると、なかなかいろいろな課題が、今もありましたけれども、保育士のスキルもかなり求められるでしょうし、子ども自身にとって。","respondent":"石井保育支援課長","answer":"その上の配置体制なのですけれども、通常、スキームとしては、余裕活用型の一時預かり事業ということで、保育所で実施する場合については、その保育所の定員の範囲内の人員配置をされているということで要件が満ちているのですけれども、一部。","id":"exchange-062"},{"speaker":"安藤委員","kind":"意見","question":"登録制に近いということで、最初のご説明で、ものすごく需要があるということなのですが、実際の人数は、受け入れる保育園の体制なのでしょうけれども、１名とか、０名とかというところもあるので、これだけ見ると、応募は殺到したのだけれども、実績、受け入れる数は、この数でしたということなのか、それとも、０名というところは、そもそも応募もなかったのかという、需要がものすごくあるという割には。","respondent":"石井保育支援課長","answer":"もともと都事業を実施するときに、０歳から５歳の未就園児で募集をかけてみるというふうなこともあったので、たまたまこの園自体は０歳から２歳の空きがなかったので、それで３歳から５歳で募集してみたらどうだろうと言ったのですけれども、やはり３歳から５歳に関しては。","id":"exchange-063"},{"speaker":"安藤委員","kind":"質問・要望","question":"冒頭申し上げたような、私たちもそういう問題意識もありますので、十分な人員体制ですとか、課題の解決策をやはり整えていくということを、まずはしていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"}]},{"id":"topic-07","title":"議会閉会中継続審査調査事項","agenda":"議会閉会中継続審査調査事項","exchanges":[{"speaker":"安藤委員","kind":"提案","question":"幼児画展覧会作品の件なのですが、戸越四丁目暫定広場とは、区の土地なのでしょうか。どういう場所なのか伺いたいことが１つ。そしてもう１つ、ここで展示をしようと提案した部署はどこなのか伺いたいと思います。","respondent":"石井保育支援課長","answer":"区が暫定広場として占用許可を取得した上で整備しています。こちらを利用しようと提案したのは、我々保育支援課で、どこか使えるところはないかというふうなことで探していたところ、今ちょうど使える掲示板があるということだったので、活用するというようなところです。","id":"exchange-065"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"だから、そういう人たちに意識を向上させるためにも、そういう取組をやると、町にもアートがあふれるし、そういった若い人たちに掲示板の存在を理解もしてもらえるので、いろいろな効果があると思うので、ぜひ今後こういうものをもしやるのであれば、そういったことも検討していただきながら、ほかの部署とも連携して取り組んでいただけると、もっといいものになっていくのかと思うので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/799105?Template=document&Id=5124#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":47583,"voices":189}},{"id":"r06-20240227-5","meetingId":"r06-cm02","date":"2024年2月27日","dateIso":"2024-02-27","committee":"総務委員会","time":"午前１０時００分～午前１１時３６分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を27件抜き出しています。","topics":[{"id":"topic-01","title":"令和５年度行政評価の結果","agenda":"令和５年度行政評価の結果","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"ご説明ありがとうございました。少し説明していただけたらと思う点ですが、つまり、この予算削減額の２３億６,４００万円余の内訳、事業が分かるように説明をしてもらったり、資料をつくっていただけたらというところです。２３億６,４００万円余にはどんな事業があるのか、一覧表というか、見て分かるものというか、それをちょっと提出してもらえると分かりやすいなと思って、１つ伺いたいと思います。","respondent":"吉岡政策推進担当課長","answer":"２点目の施政方針での数字というところで、１％、２０億円というところがございましたけれども、こちらは公約で、１％、２０億円というふうにお話しさせていただいているところですけれども、今回、予算削減額２３億円余というところが、結果として削減額となったところです。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"それと、まとめてもう一個だけ、２ページ目の予算特別委員会への資料の提供ということで、先ほどともかぶりますけれども、分厚いのがどんと来られても、もちろん全部見ようと頑張りますけれども、せめて評価のＡＢＣＤのタイトルや目次、全体像が分かるものを併せて出していただければ、ああ、何ページのどこを見ればいいのかと進めると思うのですけれども、それぞれいかがでしょうか。","respondent":"吉岡政策推進担当課長","answer":"性質別については、人件費のところが各事業に分散されていて、どれだけ削減されたかというところはなかなか難しい部分もありますので、内訳については、どのような出し方が分かりやすいかというのは引き続き検討していきたいというふうに考えてあります。","id":"exchange-002"},{"speaker":"須貝委員","kind":"質問","question":"うがった見方をすれば、数字合わせのように見えます。それはどうなのかということ。電子決裁率、庁内業務における電子決裁の割合、こういうふうにしていますよ、どんどん上げていますというのは、目標としてはいいのでしょうけれども、これが行政評価なのですかとちょっと思うのと、あとキャッシュレス端末の設置もそうですけれども、どんどんキャッシュレス端末を置いていく。こういう目標も掲げている。","respondent":"吉岡政策推進担当課長","answer":"そういった意味で、予算削減額というところは、あくまで結果として出たところでございまして、これは当然目的ということではございません。ただ、事業実施方法の改善ですとか見直し、こういったところで、結果としてこの２３億円が捻出されたです。","id":"exchange-003"},{"speaker":"須貝委員","kind":"提案","question":"それをこうやって評価して、財務情報まで出して、それが一体何なのかというのが、非常に分かりにくいので、私はいつも辛口で言って恐縮ですけれども、一体何を評価して、それがどういうふうに、庁内で事務事業もこれだけ合理化して、それだけすごく人件費も浮いてきました、何もしてきましたというのだったら、それだけを記載すればいい話だし、各職員の方が、いや。","respondent":"吉岡政策推進担当課長","answer":"今回の行政評価、事務事業評価につきましては、庁内での検討というところになりますけれども、一方で政策評価につきましては、区民・有識者による外部委員会を設置いたしまして、防災と環境について評価をいただいたところです。","id":"exchange-004"},{"speaker":"須貝委員","kind":"意見","question":"毎回すみませんけれども、別に区長の方針に逆らうわけではないけれども、自分の会社だと思ったら、こんなことをやるのだったら、やるべきことがたくさんあるのではないかという気がするし、ただ数値化したものを出して、どれだけの意味があるのかなと非常に疑問に思って、よりいい方法に評価方法が変わるとまた違うと思うのですけれども、一応意見だけ言わせてください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"松本委員","kind":"意見","question":"議事録のほうでは、どちらかというと、ある程度事前の会議、事前の検討を踏まえたものがたたき台というか、事務局からまとめたものが出てきて、それを、改めて皆さんでご意見を出していただくという形になっていて、多分事前の検討のほうが実際の中身があるのかなと思っていて、ここの部分が、そこまでの公開は、議事録の形にはされていない、記録の公開はされていなくて。","respondent":"吉岡政策推進担当課長","answer":"一方で、何も数字、事業がないまま、これを評価していただくというところは、区民の方にとって非常に難しい部分がございましたので、そちらを構成する代表的な事業を幾つか取り出して、ご説明させていただいて、インプット、あるいは意見交換をするというところで。","id":"exchange-006"},{"speaker":"松本委員","kind":"意見","question":"政策の話をするところと事務事業の話をするところというのは、一応段階を分けたということでいいのかというのが１点と、多分政策と事務事業の関係でいったら、間に施策が入ると思うのですが、つながっているというか、事務事業が施策につながって、施策が最終的な政策の達成になっているかというところが一連の流れになるかと思います。その辺りの工夫は何かなされたのか、お願いいたします。","respondent":"吉岡政策推進担当課長","answer":"先ほど事務事業と政策が離れているということで、まさにそのとおりでございまして、政策の柱でどのような代表的な施策があるか、そういったご説明をさせていただいて、事務事業の中でも、代表的なものを出すことによって、小さい事務事業ではなくて。","id":"exchange-007"},{"speaker":"石田（秀）委員","kind":"質問","question":"なぜやめたかと聞きたい。あれは５００万円以上、間違っていたら、ごめんなさい。前は５００万円以上だった。そこら辺をどう捉えてこれを今やっていらっしゃるかというのを、１年はいいのだけれども、３年ごとにやるとか、５年ごと、もう一回チェックをするためにやるぐらいの感覚とかというのがないと、何度もこんなことをやる話ではないと思っていて、そこら辺の感覚を教えてほしい。","respondent":"吉岡政策推進担当課長","answer":"引き続き行政評価を行う上で、どういった評価対象、事業にしていくかですとか、評価の在り方というところをしっかり検討するとともに、予算の削減額、予算の編成のところにどう生かしていくかというところを再整理していくことが必要だというふうに考えているところです。","id":"exchange-008"},{"speaker":"石田（秀）委員","kind":"質問","question":"不用額をどうしようなどという話とか、行政側にある程度の幅があっていいと私は思っているのです。それはいろいろな中で、だから、款項目節で目間流用だっていいよとやっているわけではないですか。皆さんもその中で、企画の方々もそういうことを勘案しながらやっていらっしゃると思います。何年に１回やるとか、見直すということは必要、監査の視点から毎年やる。今の話ではちょっと納得できなかった。","respondent":"吉岡政策推進担当課長","answer":"今後事務事業評価、行政評価を行うに当たって、どのように予算編成に活かしていくかというところはしっかりと考えさせていただいて、答えを出していきたいと思います。","id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"意見","question":"今ちょうどこういう時期なので、この前か何か話があって、こういうのがあって、職員の方々からもいろいろなお話を聞いて、９事業か何か新しくやっていく。ぜひそういうことだけお願いしたいと思います。だって企画に切られてしまうということしか思っていない、職員の人、所管の人たちは。応援します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"塚本副委員長","kind":"質問・要望","question":"以前、行政評価はこの委員会でも何回か報告いただいていますけれども、そこで聞いていたかもしれないですけれども、改めてで申し訳ないのですが、評価のＡＢＣＤをつけるときに、どういう会議というか、誰が中心になって最終的に評価をつけるのかというのを確認させていただきたいのです。","respondent":"吉岡政策推進担当課長","answer":"評価を行うに当たっては、区長審議というところで、関係する部長ですとか、企画の職員、こういった者が集合いたしました会議体を行いまして、こういった評価を決定していったです。","id":"exchange-011"},{"speaker":"塚本副委員長","kind":"質問","question":"分かりました。予算審議においてはそういう前提で臨んでまいりたいというふうに私も思います。非常にお忙しいし、大変だとは思うのですけれども、そういった資料はなるべく分かりやすくなるようなものをお願いしたいというのと、あとは時期的に予算特別委員会が来週に迫っていますけれども、いつ頃、なるべく早くお願いしたいのですけれども、いかがでしょうか。","respondent":"吉岡政策推進担当課長","answer":"区議会においてもこういった資料をお渡しするルールというものもありますので、そちらに沿って今週中には皆様にお届けできるよう、ご用意させていただければと考えています。","id":"exchange-012"}]},{"id":"topic-02","title":"「ＳＤＧｓ未来都市および自治体ＳＤＧｓモデル事業」への応募","agenda":"「ＳＤＧｓ未来都市および自治体ＳＤＧｓモデル事業」への応募","exchanges":[{"speaker":"須貝委員","kind":"提案","question":"昨日もこれをじっくり読ませていただいて、ＳＤＧｓ未来都市および自治体ＳＤＧｓモデル事業ということで、提案概要をずっと見ながら考えていたのです。誰一人取り残さない社会をつくるということですけれども、生活に余裕のある人はこういうことも考えられますけれども、今ほとんどの人が希望するのは、どうしたら生活が楽になるかということが主眼だと私は思うのです。様々な項目が書かれております。","respondent":"吉岡政策推進担当課長","answer":"当然自治体が行う事業についても、すべからくＳＤＧｓにつながるというふうに考えているところですけれども、こちらのモデル事業、未来都市というところは、特に官民、あるいは産学官が連携しながら進めている事業を抽出して載せていくところです。","id":"exchange-013"},{"speaker":"須貝委員","kind":"意見","question":"もう一点、嫌な言い方をして恐縮ですけれども、誰一人取り残さない。今多くの方が取り残されている。将来的には大事なことだというのは私も認識しているのですが、ましてこれだけ全世界で戦争だ、能登半島地震があって、もう復興で大変だ、いや、そうではない、誰一人取り残さないこういう社会は大事なのですよと言われても、多くの方がぴんとこないと思うのですが、その辺はどう思われますか。","respondent":"吉岡政策推進担当課長","answer":"ＳＤＧｓに向けた様々な事業がありますので、そういったところで、多くの区民の方の幸せにつながるような事業、官民が連携しながら、持続可能な事業をすべく、引き続き邁進していきたいというような考えです。","id":"exchange-014"},{"speaker":"塚本副委員長","kind":"質問・要望","question":"そういうものをようやく全ての政策において、ＳＤＧｓという考え方で、持続可能な、誰一人取り残さないという考え方で物事を進めていかなければというところで非常に大事な、今の問題を解決するために外せない考え方というか、政策だというふうに思っていますので、その点について一言、区の考えをお伺いしたいと思います。","respondent":"吉岡政策推進担当課長","answer":"区民の皆様が、大きいこと、国がやること、地方公共団体がやること、そういったふうに思っていただかないように、しっかりと普及啓発をしながら、品川区を持続可能な町にすべく、いつまでも住み続けたいと思ってもらえるような形で、こういった計画を提案しながら。","id":"exchange-015"},{"speaker":"石田（秀）委員","kind":"質問","question":"目標だけは掲げておかなければいけないし、いろいろやってくださっているではないですか。これは本末転倒だね。だから、これをやっていただくのはいいので、全部の事業に関わってくることなので、努力してやっていくけれども、ぜひそこら辺の、矛盾しているな、これは本末転倒だろうというようなところは、どこかでちょっと１回整理をして、ＳＤＧｓの観点から見て本末転倒ではないか。それだけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"}]},{"id":"topic-03","title":"令和６年度都区財政調整","agenda":"令和６年度都区財政調整","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"財政調整でも見られるみたいですけれども、先ほどの説明でも、新規算定を見ても、水害はあるけれども、いわゆる首都直下型大震災については、消火器がぽろっと入っているぐらいで、あと公共施設が入っているぐらいで、これだけ防災対策が言われている中で、国や都の補助金が少ないのもどうかと思うのですけれども、質問は１７億円ぐらいの一般財源のうち。","respondent":"遠藤財政課長","answer":"一般財源ということで、財政調整の中で防災がどれぐらい含まれているかというご質問ですか。","id":"exchange-017"},{"speaker":"中塚委員","kind":"意見","question":"最後は自分の意見だけです。防災対策と言われながら、首都直下型大震災に向けて、新年度予算でもいろいろ事業が追加・拡充されていますけれども、国や都の補助金は少ないと思うし、一般財源の中で、２３区の共通の項目となってくると、品川区の町の特徴と２３区の町の特徴は、重なる部分と大分違うところもあるし、最近そんなことを考え始めたということです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そこら辺のところを教えてもらいたいと思うのが１つです。それから、新規算定の部分は、頑張っていただきたいとしか言いようがなくて、ぜひよろしくお願いしますというところだけれども、１つ思うのは、再調整のやり方だけれども、いろいろ項目が、主にどういうのに使ったり、再調整でこういうのはあるのだけれども、基本は、私が懸念しているのは、再調整は金額が大きいではないですか。","respondent":"桑村副区長、遠藤財政課長","answer":"ただ、令和２年度の財政調整の方針で、５５.１％は確認するということは取れているので、少なくとも０.１％は児童相談所の議論の中で上がったというのは、実績としては取れたということであります。調整額の考えです。令和３年度が多かったというところですけれども、恐らく東京都のほうで、コロナ禍というところもありまして、法人住民税がそんなに伸びないだろうと見込んでいたのが、大手のところで増えたです。","id":"exchange-019"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ぜひ頑張っていただきたいと思っていて、私はもう本当に再算定の中で取り込まれてしまうのではないかと思っていますが、今言ったように、０.１％でも、これはやったということであります。ぜひご理解いただきたいのは、品川区の場合は、特に私の地域は、同じ町会の中に児童相談所が２か所あるので、片方はなくなるのかといったら、ほかの区がやらないから、なくならないわけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"松本委員","kind":"質問・要望","question":"その事実確認と、細かい話になるかもしれないですが、たった１年でそこが変わるというのはよくあることなのか、どういう意図で伺っているかというと、補助しますよというのは、どちらかというと、都のアピールに使われてしまうのかなとある意味思ってしまって、アピールに使ったら、あとはこのような算定という形で、ある意味切り離されるような感じになるのか。","respondent":"遠藤財政課長","answer":"帯状疱疹は都のほうでも始めて、区のほうでも結局補助金をやるかやらないかというのは、また別の判断があるかと思うのですけれども、比較的多くの区が標準的にやるというような判断がなされたので、今回新たに算定に加わったと考えていただければと思います。","id":"exchange-021"},{"speaker":"松本委員","kind":"意見","question":"分かりました。では、補助金としては引き続き東京都としても残るということですね。比較的多くの区がやっているということもあって、協議の結果、算定が上がってきたということで理解しました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"}]},{"id":"topic-04","title":"令和６年能登半島地震に対する区の対応","agenda":"令和６年能登半島地震に対する区の対応","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"それと、人的支援のほうですが、向こうに行かれた方がいて、話を聞いたら、報道でもありましたけれども、宿泊所がなくて、避難所対策、それから、各自治体の市役所等をはじめ、宿泊施設がないというので相当困ったという話をお聞きしているのですが、実際支援に行かれた品川区の職員は大丈夫だったのでしょうか。","respondent":"勝亦総務課長","answer":"金沢市です。金沢市のほうからご要望いただいているのですが、委員がおっしゃるように、一定程度復旧はしているのですが、金沢市が石川県北部のほうに支援物資を出してくれという要請を受けたということで、それを２段階支援のような形で実施しているものです。","id":"exchange-023"},{"speaker":"須貝委員","kind":"意見","question":"派遣で行かれた方は大変な思いをして、金沢市まで戻って、片道だけでも３時間、４時間かかって、往復６時間以上かかって、実質向こうで作業が、あんまりお手伝いできなかったという話も聞くので、本当に宿泊施設というのも大切だなと思いました。本当にご苦労されたと思います。終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"},{"speaker":"松本委員","kind":"質問","question":"それで、一般質問であったかもしれないし、総務委員会なので、公営住宅の受入れ、どこまでお伺いできるかはあれなので、無理でしたらおっしゃっていただけたらと思うのですが、考え方が、今回ほかの自治体も見ていて、結構提供できる住宅がこのぐらいあるよというのは、ぼんぼん報道で出ていたかと思うのですけれども、これはあらかじめある程度予備として取っていらっしゃるからこういうことができるか。","respondent":"勝亦総務課長","answer":"住宅の所管をしている部署の確認ということで、区民住宅のほうが２戸空いているものを転用しているという状況と、木造住宅密集地域用の従前居住者用住宅を８戸転用できるものを活用しているというふうに考えてあります。","id":"exchange-025"},{"speaker":"松本委員","kind":"質問","question":"ということは、結局この被災者を受け入れたり、目的ではないけれども、事実上空いているところがあったから、これを転用したというような理解でよろしいのですか。","respondent":"勝亦総務課長","answer":"そのような形で有効活用しているです。","id":"exchange-026"},{"speaker":"石田（秀）委員","kind":"質問","question":"１点だけ教えてください。これは分かる方がいらっしゃって、本当は防災課かな。品川区も支援をしました。今回も支援をしています。そのときの対応、それから今１２年か、それぐらいたった中で今度の震災があって、あんまり変わっていないではないかとか、いろいろな面でそれが生かされているのかみたいな話が出てくるではないですか。","respondent":"勝亦総務課長","answer":"防災のほうからの話といたしまして、被災地支援に関しましては、例えば、物資を送る際に、この間、物資の配備ですとか、トラック協会との関係構築ですとか、そういった部分の中で。","id":"exchange-027"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/131056?Template=document&Id=2292#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":32252,"voices":85}},{"id":"r06-20240228-14","meetingId":"r06-cm02","date":"2024年2月28日","dateIso":"2024-02-28","committee":"行財政改革特別委員会","time":"午前１０時００分～午後 ０時３９分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を62件抜き出しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"松永委員","kind":"質問・要望","question":"私から２点確認をさせていただきたいのですが、６ページの駐車場についてなのですが、今現在の駐車場は、よく満車でなかなか入れないという状況であって、今後新しい庁舎で約１５０台ということなのですが、これは大丈夫なのかということと、もう一つ、エレベーター、地下１階のほうにはないのですが、地下２階のほうに１基だけ黄色くなっておりますが、１基で大丈夫なのかという。","respondent":"大友新庁舎建設担当課長","answer":"そういう駐車場との連携も含め、現在検討しているところではありますけれども、駐車場の一般利用につきましては、隣接した広場１号やＪＲ棟に整備される駐車場、また、Ｂ－２地区の今後の整備なども含めて、今後広く地区として考えてまいりたいと考えています。","id":"exchange-001"},{"speaker":"松永委員","kind":"質問","question":"先ほどの駐車場の件ですが、近隣のＪＲのところをお借りするということなのですが、これは一回上がって、またそこの区役所に向かうという形になるのでしょうか。そのまま地下から移動できるという感じは考えていないということでよろしいでしょうか。","respondent":"大友新庁舎建設担当課長","answer":"今後の調整になるものでございまして、今確保できているところの駐車といたしましては約１５０台、現庁舎が２００台程度であるのが１５０台となるというところで、周辺の駐車場利用も含めて、今後検討してまいりたいというところになります。","id":"exchange-002"},{"speaker":"松永委員","kind":"質問","question":"私、少し気になったのが、一般の来庁者の方の駐車場と職員の駐車場の割合というのを知りたくて、よく私たちも車で来るときもあるのですけれども、そういった時もなかなか入れないというところもあるので、今現在、１５０台のうち、職員の割合と一般の割合というのを考えていらっしゃるのでしょうか。どのくらいなのか教えてください。","respondent":"大友新庁舎建設担当課長","answer":"現庁舎の割合ですけれども、現庁舎では公用車が１１０台程度、一般車が９０台程度という割合になってあります。今後ですけれども、整備するところといたしましては、公用車が１００台程度、一般車が５０台程度の内訳となる想定で考えてあります。","id":"exchange-003"},{"speaker":"あくつ委員","kind":"提案","question":"今の松永委員の説明のところで、１００台が公用車ということで伺ったのですが、公用車というのは何を指すのかというところを教えていただきたい。１００台というのは、どういうものなのか、内訳、もし簡単に分かればというところで。我々、トイレトレーナーなどというのも導入を提案していますので、それなりの高さが確保されているのかどうかというところをお伺いします。","respondent":"大友新庁舎建設担当課長","answer":"高さにつきましては、こちら、３.２ｍの高さまで出入りができるところで考えているところです。屋外にも大型車がとめられる駐車場を確保しておりますので、そこについては天井がないところになりますので、高さの制限がないというところも一部確保はあります。","id":"exchange-004"},{"speaker":"あくつ委員","kind":"質問","question":"現状、公用車は何台なのかというところですが、本庁舎と、今このエリアで今回改築になる部分で、どれぐらい公用車が。今おっしゃられた数があって、１５０台のうち１００台は公用車で、いわゆる外来というか、訪問する方については５０台という、こういうことの理解でいいのでしょうか。","respondent":"大友新庁舎建設担当課長","answer":"公用車の台数につきましては、こちらが今ぴったり最新の状況かというところはあるのですけれども、１１０台あまりの台数と把握しています。残りの台数が一般利用という形になってあります。この公用車の台数につきましては、東京都が管理する、利用する車両等も含まれてあります。","id":"exchange-005"},{"speaker":"あくつ委員","kind":"質問","question":"そうすると、繰り返しになりますが、来庁者の車が４０台分しか。出たり入ったりもあると思うのですが、公用車の部分は、普通の車がとめられなくなったりしていることも、そういうふうに指定されている場合もあるのですけれども、いわゆる来庁者分としては４０台という理解でいいのでしょうか。そういう説明はこれからされるのでしょうか。","respondent":"大友新庁舎建設担当課長","answer":"今整備できる駐車場の台数といたしまして、約１５０台を検討しているところではありますけれども、公用車の台数につきましては、今現在、こちらでとまっている台数を全て新庁舎に持っていくのかどうかというところの台数精査もあるかと思います。","id":"exchange-006"},{"speaker":"あくつ委員","kind":"質問","question":"結論は分かったのですが、もう一回お伺いしたいのですが、現状では一般車両、来庁者の車の台数はどれぐらい確保しているのか、分かれば教えてください。","respondent":"大友新庁舎建設担当課長","answer":"現状は９０台です。","id":"exchange-007"},{"speaker":"あくつ委員","kind":"確認","question":"そうすると、一般来庁者の車が９０台で、これからそれが、増減があるとしても、４０台前後ぐらいになる可能性があるということで、半分以下になる可能性があるということなのですが。その辺り、そういう理解でいいのか、区民がそれで理解していただけるのかどうかというところで、もしかしたらこの議論は前にあったのかもしれないのですけれども、もう一回確認させてください。","respondent":"大友新庁舎建設担当課長","answer":"とめられる台数のところにつきましてですが、一般利用者の確保のところにつきましては、今後設計や運用の中で、また引き続き精査してまいりたいと考えているところです。","id":"exchange-008"},{"speaker":"あくつ委員","kind":"質問・要望","question":"駐車場のところは最後にしますが、そうすると、庁舎が新しくなって、今でも、先ほど松永委員からあったように、日によって、また時期によって、月末・月初とか、年度末とか、年度の初めであるとか、かなり混む状況もあったりもするので、そこのところは区民の理解を得られるように、最大限一般の来庁者の台数というのは確保していただきたいということを要望します。","respondent":"大友新庁舎建設担当課長","answer":"免震構造の点と絡めまして、耐震安全性能のところについても少し触れてご説明をさせていただきたいと思います。耐震安全性能のところのページとして、４ページをご確認ください。４ページ目の左上の部分になります。","id":"exchange-009"},{"speaker":"あくつ委員","kind":"質問・要望","question":"オイルタンクについては地下に置くということですが、これについては、こういう１４階建ての一応高層建築物ということになっていますけれども、大体真ん中ぐらいにこういうものを置くというのが今スタンダードなのでしょうか。","respondent":"大友新庁舎建設担当課長","answer":"しかしながら、今回、浸水、また、使い勝手等を考えたときに、構造上でも問題ない位置というところで、６階に整備することができるというところの中で、６階の整備を考えているところです。","id":"exchange-010"},{"speaker":"あくつ委員","kind":"質問・要望","question":"そのとおりだなと思うのですが、オイルタンクは地下で、これは、そうすると、６階まで接続して重油なり何なりで発電機を回さなければいけないというところで、その接続がまず大丈夫なのかなというのが。地下であれば、６階まで上げなければいけないというところで、専門的なところが分からないので、そこのところがもし分かれば教えていただきたいということです。","respondent":"大友新庁舎建設担当課長","answer":"地下に持ってきたオイルタンク、オイルを発電機まで持っていく手法といたしまして、検討自体、具体的な設計はこれからになるのですけれども、その耐震性能等、万が一のときに破損等ないような形での設計を進めてまいりたいと考えているところです。","id":"exchange-011"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"２点質問します。それと、もう１点が、９ページの概算事業費のところで、特殊要因で２０億円というのが事業費として示されていますけれども、特にりんかい線の影響対策というのは、具体的なところ、どういう対策を考えておられるのかというのを教えていただきたいと思います。","respondent":"大友新庁舎建設担当課長","answer":"高さの部分につきまして、別紙１の３ページ目、どこに反映しているかというところにつきましては、建物の躯体としまして約６２.２ｍというところはあるのですけれども、屋上設備などの設置箇所というところにつきましては。","id":"exchange-012"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"１点目のところは、いずれこれはパース上でも反映していただくという考えでいいのか、もう一回、よろしくお願いします。この２０億円というところで見ると、どれぐらい地下水の対策というのは、これは見えないところなのは当然お答えできるかどうかあれなのですけれども、どの程度内訳として見込んでいるのかというのを教えていただきたいと思います。","respondent":"大友新庁舎建設担当課長","answer":"地下水対策、どのぐらいの金額かというところにつきましては、対策工法が様々ある中で、ポップアップになるとは思うのですけれども、具体的な金額をこの場でお示しすることはなかなか難しいのかなと考えているところです。","id":"exchange-013"},{"speaker":"松本委員","kind":"意見","question":"先ほどＪＲを含めて、周りの駐車場の利用も、まだ確約は取れていないけれども、一応検討はされているという話だったのですが、検討されているというのは、今２時間以内であれば、庁舎利用者については無料という運用をされていると思うのですけれども、それを、ＪＲが整備される駐車場でも、例えば２時間使う分には無料という運用をこれからお願いする感じになると思うのですが、そういうことを今想定。","respondent":"大友新庁舎建設担当課長、黒田新庁舎整備担当部長","answer":"引き続き検討はしていきたいというところで考えているところです。広町地区全体の中でいろいろ駐車場、ＪＲが整備するものもありますので、そういったところの運用も含めて、区民の皆様がご利用しやすいような庁舎になるようにというところも含めて。","id":"exchange-014"},{"speaker":"松本委員","kind":"意見","question":"先ほどの選挙のところは、やはり懸念されるのは、例えば６０とか７０とか街宣車が動く、選挙カーが動く場合に、近いところにきちんとした駐車場にとめられないと、路上駐車とかが増えてくるとか、これは当然候補者側の問題で、それは本来きちんと駐車しないといけないとは思うのですけれども、場合によってはそういうことも想定され得るということは、いろいろな起こり得ることを想定しながら、今後。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"筒井委員","kind":"意見","question":"私からは３点ほどあるのですが。もっとも完成するのは２０２９年１月予定ということで、そのときにどれだけ自動車の需要があるかという問題もありますし、また一方で、何か大きなイベントがあったら駐車場は必要ではないかという話も当然だと思うのですけれど。その点、区としては、駐車場の充電設備とか、そうした環境対応をどうお考えになっているのかをお知らせください。","respondent":"大友新庁舎建設担当課長","answer":"駐車場の充電設備というところの環境対策についてご回答させていただければと思います。新庁舎に整備する駐車場におきましては、一定充電できる設備、エコカーといいますか、ＥＶ車といいますか、そのような車の充電できる設備を設ける形で検討を進めているところです。","id":"exchange-016"},{"speaker":"筒井委員","kind":"質問・要望","question":"２０２９というのはかなり大きな数字かなと考えていますので、カーボンハーフの目標の年である２０３０年の１年前ということなので、しっかりとご対応いただければと思います。補助２６号線に向けて歩行者専用通路が幾つか、２号、３号、４号、補助２６号線に出る側の通路があるのですが、確認させていただきたいのですが。","respondent":"泉広町事業調整担当課長","answer":"回遊性の向上に向けて、引き続き取り組んでまいりたいと考えています。","id":"exchange-017"},{"speaker":"筒井委員","kind":"質問・要望","question":"当事者、関係者の皆様のご納得を得られるような方法で、そうしたお話を進めていっていただきたいと考えております。近隣説明会についてですが、広町地区２４０ｍの範囲、これでご説明されるということですが、これは都市計画法上の最低限の範囲なのか、あくまでもこれは法律にのっとって粛々とやっていくもので、範囲もこの程度のものなのかということを確認させていただきたいと思います。","respondent":"大友新庁舎建設担当課長","answer":"今回、この説明会を実施するに当たりましては、事業者としての立場として実施するものでございまして、基本的な考えでいきますと、建物の高さから２倍の範囲で今回周知をするということで考えているところです。","id":"exchange-018"},{"speaker":"筒井委員","kind":"質問","question":"ＪＲの周知範囲ということと、条例にもあるということでしたけれども。今後の周知の在り方、どのように区民に向けて説明していくのかということも含めて、もう少し広報していったほうがいいのかなと考えているのですけれど、その点いかがお考えでしょうか。","respondent":"大友新庁舎建設担当課長、山下新庁舎整備課長","answer":"区民周知につきましては、今後、基本設計等が取りまとまった段階で、また広く実施していきたいと考えています。ただいまご質問がございましたこちらの近隣説明会の実施等につきましては、広報しながわ等の掲載によりまして周知を図ってまいりたいと考えています。","id":"exchange-019"},{"speaker":"筒井委員","kind":"質問","question":"説明会の周知とともに、ある程度ここまでかなり具体的にお話が出てきているので、そうした全体の概要というのも広報しながわで周知していったらいいのかなとは考えているのですけれど、その点いかがお考えでしょうか。","respondent":"山下新庁舎整備課長","answer":"今現在考えておりますのは、こちらの開催、実施をするよということの周知ということで、紙面等の制約等から今調整に臨んでいるところでございまして、現段階での検討としては、そのような状況です。","id":"exchange-020"},{"speaker":"筒井委員","kind":"質問","question":"当然、説明会の開催告知ですから、今回資料に示されたようなイメージ図とか、そうしたこともそろそろ出していくというお考えでしょうか。","respondent":"大友新庁舎建設担当課長","answer":"イメージ等も固まってきて、建物概要も固まってきている段階です。今後、さらに基本設計の後段といたしまして、取りまとめをさらに精度を上げたものとして、全体周知ということで、区民の皆様にまたご説明できる機会を新たに設けていきたいと考えているところです。","id":"exchange-021"},{"speaker":"まつざわ委員","kind":"質問","question":"１点、私も駐車場に触れようと思っていまして。そもそもこの区画道路がＴの字にあって、駐車場の入り口というのは、この区画道路のＴの縦棒のところに入るのですか。","respondent":"大友新庁舎建設担当課長","answer":"駐車場の出入口の箇所につきましては、南北道路、新たに整備される縦の道路、そちらのほうから車に入っていただく形を想定しています。","id":"exchange-022"},{"speaker":"まつざわ委員","kind":"質問","question":"この縦のところですね。そうすると、ここから入っていって、質疑を聞いていると、一般の車は５０台ぐらいだと。私も感覚的には少ないのかなというのが本音です。だから、例えば、地下は２階しか掘れないし、これ以上はできない。そうなのか、例えば、ＤＸ化が進む中で、そもそも車での来庁者数というのが減るという見込みなのか、そこら辺を教えてください。","respondent":"大友新庁舎建設担当課長","answer":"駐車場の台数全体につきましては、見込み等の想定もしているところではありますけれども、こちら、一定ＤＸが進むからもっとどんどん減るというところの考え等ではなく、全体として１５０台の確保というところにつきましては、附置義務が現状。","id":"exchange-023"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"そこで、足りない部分は、地域の駐車場、民間の駐車場を使ったりといいますが、現状は、ご存じのとおり、大井町の周りの駐車場というのは常にパンパンなのです。だから、ＪＲとの協議になる。区民だけではなくて、いろいろな方が来場すると思うので、願わくば、ほかのところとの連携という部分を見越して想定するのではなく、ここでうまく収められるという、そういった想定ができるように要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"えのした委員","kind":"質問","question":"私からは１点だけ。議場は最上階ですから、そこに議会関連諸室が近いほうがいいとかというのはあると思いますが、利便性も含めてお考えだとは思いますが、どういった考え方でこのフロア分けをされているのか、お知らせいただけませんか。","respondent":"大友新庁舎建設担当課長","answer":"実際に非常時、消火活動や避難を考慮して、非常用エレベーターを２基設置するというところにおきましては、１４階と屋上等からも避難経路を十分な確保というところは考慮して計画を立てているところではあります。","id":"exchange-025"},{"speaker":"えのした委員","kind":"意見","question":"それ以外の階の配置というのは、何か他区の事例ですとか、今この庁舎のフロアに倣ってなのか、新庁舎で１４階建てになるときには、やはりこういった階層でまちづくり、都市環境、子ども・教育、区長・企画・総務ですとか、その下、窓口も含めて、もちろん区民の利用者の利便性も含めて考えられていると思いますが、その階層配置はどういうふうにされたというのをご説明をお願いいたします。","respondent":"大友新庁舎建設担当課長","answer":"その他の各所管等の配置の考え方なのですけれども、まず低層部のほうから区民利用を基本的に考えて配置をしているというところでございまして、保健所・保健センターというところにおきましては、一定診療機能というところで独立した区画等を設けなくてはならないというところで。","id":"exchange-026"},{"speaker":"山本委員","kind":"質問・要望","question":"私からは、今後のスケジュール関連についてお教えください。より多くの区民の方々に関わってもらうことで、そういった区民の皆様にとって愛着のある庁舎になるというところもあるかなと思っておりまして、そういった考えから、区民の皆様のアイデアを今後、竣工までの段階で様々集めていくということはご検討されているでしょうかです。","respondent":"大友新庁舎建設担当課長","answer":"こちらのほうの実施については、４月の中旬を予定しています。続きまして、事業者選定についてなのですけれども、こちらにつきましては、令和７年度着手の工事を考えているところです。","id":"exchange-027"},{"speaker":"山本委員","kind":"質問・要望","question":"この事業者の意味等、理解いたしました。区民の皆様のアイデアを聞いていくというところについては、ぜひ、今後の区民の皆様への説明の機会で、アイデアを聞いていただく場を設けたりしながら、検討を進めていただきたいと思います。","respondent":"吉岡政策推進担当課長","answer":"最後に項番４、今後の予定ですけれども、来月、３月２２日に答申を踏まえた活用方針（案）に係る住民説明会を旧荏原第四中学校にて実施後、４月には活用方針を策定・公表いたしまして、基本計画の策定に向け、具体的な検討を開始してまいります。","id":"exchange-028"},{"speaker":"塚本委員","kind":"意見","question":"例えば、図書館とかということで、図書機能となると、今、品川区にある区立図書館が一つ増える、図書館の所管としてこれを管理していくのだとか、運営していくのだとか、そういう話になって、それぞれの縦割りだとか、そういうのになってくると、それはそれでいろいろメリット・デメリットとか、検討しなければいけないことが出てくると思うのですが、今後の全体として。","respondent":"吉岡政策推進担当課長","answer":"次年度、計画を策定するという流れの中で、具体的に施設を固めていって、どのようなゾーニングにして、その中で、今、指定管理ですとか、運営方法についてのお話がございましたけれども、どのように運営していくのが望ましいかというところ。","id":"exchange-029"},{"speaker":"塚本委員","kind":"質問","question":"例えば、屋上を庭園として見たらどうなのだと、いろいろな話があったと思うのですが。今回こういった形に結論が出たということは、今ある老朽化した保育園とシルバーセンターを改築することで、スペースというか、地面を広くしてということで園庭の面積を確保すると、こういう考え方でよろしいのでしょうか。","respondent":"吉岡政策推進担当課長","answer":"ぷりすくーる西五反田の園庭面積の確保ですけれども、改築を行うことで、いろいろな形で園庭面積の確保の方法はありますので、そちらについても具体的な検討を進めていくです。","id":"exchange-030"},{"speaker":"塚本委員","kind":"質問","question":"具体的なというと、現段階では、どのように確保するかはまだ確定していないというところなのでしょうか。それとも、一定程度こういうやり方でいくという方向が出ているということかなと思ったのですが、そこをもう少しお聞かせいただいて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"塚本委員","kind":"質問","question":"そうですか。分かりました。では、一応改築をするということでなったものについての今後のスケジュールみたいなことは分かりますか。大体のところで、いつ頃そういったことが見えてくるのかというようなことはどうなのでしょうか。","respondent":"吉岡政策推進担当課長","answer":"スケジュールについても、これから線を引きましてご報告をするですけれども、保育園の利用者、シルバーセンターの利用者もありますので、そういったところは、適切な時期に分かりやすく報告をさせていただければと思ってあります。","id":"exchange-032"},{"speaker":"まつざわ委員","kind":"質問","question":"ここが、５７２人も入れるようになるという部分に関しては、本当に大変心強い施設になるのかなと思っていて。通りの面積の中がそういうのがあったりすると、訓練場にも助かりますし、例えば、住宅側にするとうるさいというのだったら、道路側というのですか、線路側に置くことによって、そういった苦情の課題解決もいろいろ考えられるかなと思っているのですが、難しいですか。","respondent":"吉岡政策推進担当課長","answer":"今後の運用というところでのお話かと思いますけれども、今後ゾーニングなども次年度以降検討していくですので、いただいた意見をどのように活かしていけるかというところは、引き続き検討していきたいと考えております。","id":"exchange-033"},{"speaker":"まつざわ委員","kind":"質問","question":"この旧荏原第四中学校の跡地活用というのは大変すばらしいもので、４ページにも書いてあって、円を描くように、全体のこういう、言わば旧荏原第四中学校跡地だけではなくて、ある程度大きなくくりを考えた計画になっていくと思うのです。旧荏原第四中学校だけを考えるのではなくて。そこら辺、区のほうでどういった考えがあるのか、教えてください。","respondent":"こんの委員長、吉岡政策推進担当課長","answer":"まつざわ委員、申し訳ないです。いわゆる跡地活用の話なので、今ある既存の整備となると、なかなかお答えしにくいのかなという部分ですけれども。何かお答えできるようでしたらば。公有地に関しましては、公共施設等総合計画の中でもありますように、施設の統廃合というところも記載させていただいているところではありますので、今回は旧荏原第四中学校の跡地活用というところではありますけれども。","id":"exchange-034"},{"speaker":"あくつ委員","kind":"提案","question":"この創発という言葉、今までの説明の中であったら申し訳ないのですが、ここに注をつけなければ、恐らくそこまで、私は、申し訳ないですが、あまり存じない言葉だったのですが、これはどういう観点で出てきた言葉なのか、皆さんのご審議の中で、誰がご提案されて、地域の方から出た言葉なのか、その辺りを教えていただきたいのと、前のご説明のときにもあったのですが、品川区にとっては新しい形の施設、でも。","respondent":"吉岡政策推進担当課長","answer":"地域に向けて説明というところなのですけれども、やはりコンセプト、導入施設、非常にたくさんある部分ではあるのですけれども、まずは大きなコンセプトのところをしっかりとご理解いただく中で、こういった導入施設、こういった事例がありますというところで。","id":"exchange-035"},{"speaker":"あくつ委員","kind":"質問・要望","question":"先ほど例示として、写真等もこれには載せたということではありましたけれども、一つ一つ理解するのが大変ではないのかなというところがあって、そこのところは、要望としては、より丁寧に説明をしていただきたいということですけれども、最後、一言お願いします。","respondent":"吉岡政策推進担当課長","answer":"そういった中では、しっかりと地域の方、あるいは、区民の方に受け入れてもらう、理解していただくために、分かりやすく適切にしっかりと情報を周知していく、意見を聞いていくという姿勢が必要だと思いますので、今後とも変わらずそのような対応をしていきたいと考えています。","id":"exchange-036"},{"speaker":"えのした委員","kind":"意見","question":"先ほどまつざわ委員からも、区民避難所についてもお話がありましたが、やはりこれだけ多様な人々が集うということは、私、ちょうど昨日、地元のスクエア荏原の避難所訓練会議のほうに出席していたのですが、あそこも跡地利用で今の施設になってはいるのですけれども、品川区内では、ほぼ学校が避難所になっているところが多いと思いますが、こちら、こういう施設になると、やはり日常。","respondent":"吉岡政策推進担当課長","answer":"先ほど避難所の運営マニュアルですとか、備蓄倉庫というところのお話がございましたけれども、今回は方針というところで、そこまで具体的には踏み込んでいないのですけれども、計画、あるいは、今後の設計、そういった進んでいく段階の中で、当然ながら防災課と協議しながら。","id":"exchange-037"},{"speaker":"えのした委員","kind":"質問・要望","question":"やはり本当に万が一発災した場合には、学校であれば、生徒・児童の帰宅、保護者が引き取りとかというのはありますけれども、やはり近くの方だけでなくて、遠くの方も利用する施設になると思いますので、その辺しっかりとつくっていただければと。こちらは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"山本委員","kind":"質問・要望","question":"今回、こういったプロセスを経て、パブリックコメントを経て答申に至ったというところで、今回のこの一連の進め方のところで、よかったと思われている点、今後に活かすという意味でというところと、課題というか、もっとこういうふうにできたのではないかみたいに思っているところなどがあれば、少しお聞かせいただきたいです。","respondent":"吉岡政策推進担当課長","answer":"今年度のこういった方針を策定する中でのプロセスで、よかった点というところでご報告を申し上げますと、やはりワークショップから始まりまして、跡地活用方針の委員会の設置、そして、パブリックコメント、オープンハウス方式説明。","id":"exchange-039"},{"speaker":"山本委員","kind":"質問・要望","question":"一方で、それがやはり限られた方々からの意見の集約になるので、本当に全体の方々の意見になるのかというところはあるなと思いますので、引き続きそういったやり方などについてもご検討いただき、今後の同じような機会に役立てていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"松本委員","kind":"質問","question":"伺いたいのが、まず電子申請のところなのですけれども、住民票等の取得等を含めて、いろいろ進んでいていいなと思うのですが、この間思ったのが、これは品川区としてやっていることなので、関係する団体との関係でどうなのかなと思って。この間、シティラン、１年前のマラソンの関係で、申し込もうかなと思ったら、五反田の体育館まで行かないといけないみたいな感じのことがあって。","respondent":"河西情報戦略担当課長","answer":"品川区電子申請サービスに関しまして、こちらの利用範囲ということでお答えします。こちら、品川区の電子申請サービスに関しましては、品川区が利用しているＬＧＷＡＮに接続する端末で受付のほうを実施しております。","id":"exchange-041"},{"speaker":"松本委員","kind":"質問","question":"団体にもよると思うのですけれども、一応区側としては、それは可能というふうなことをやられていると理解いたしました。これはもう本当に区議会側のとても恥ずかしいことだと私は思っていて。今、印刷枚数の削減率を含めてデータとして出していただいているのですけれども、この印刷枚数のカウントに、区議会および区議会議員向けの印刷枚数というのもデータとしては集計されているのか、伺います。","respondent":"河西情報戦略担当課長","answer":"こちらの印刷枚数になりますが、こちらは条件がございまして、１８ページ下に小さく書かせていただきました。複合機を対象として印刷される枚数になります。","id":"exchange-042"},{"speaker":"松本委員","kind":"質問","question":"逆に、理事者の方たちも、我々が出ている会議と、理事者の方たちで担当されている方、多分重複されている方もたくさんいらっしゃるので、そうすると、理事者の皆様は、出るたびに新しく資料をまた印刷されているのか、それとも、もう一回もらったら、もうそれはあるでしょうというふうなことになっているのか、あるいは、もうそれすらもなくて、基本的にはもうデジタルが前提となっているのか。","respondent":"河西情報戦略担当課長","answer":"今は、会議を主催する所管の考えによるところもあります。ただし、全体の流れといたしましては、今、理事者は端末を持っておりますので、基本的には端末を持ち寄って、その端末の中で電子データを見ながら庁内の会議は実施しています。","id":"exchange-043"},{"speaker":"松本委員","kind":"質問・要望","question":"これはもう議会側が、区がこれだけペーパーレスをやっているのに、こうやってご報告を受けて、自分たちは紙を見ながらやっているという状況について、本当は今日聞いていただきたいところの方がいらっしゃらないような気もするのですけれども、そこはすごく理解できました。議事録に残すということも大事だと考えていますので、聞かせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"あくつ委員","kind":"質問","question":"そういう中で、まさにマイナンバーカードを持っている、使っていることが本当に利便性があるということを感じていただくようなことを何とか品川区でも行っていただけないですかということを、ずっとこれは申し上げてきているのですけれども、これはどのような工夫をされる、通知というのはどういうことをお考えになっているのかをお聞きしたいのが一つです。この２点、お伺いしたいと思います。","respondent":"横田情報推進課長、河西情報戦略担当課長","answer":"３点目が、ふるさと納税のワンストップ特例制度ができるようになります。オンラインで寄附金控除申請ができるようになるほか、返礼品の配送状況が分かるようになる予定です。私からは、２つ目のご質問にお答えいたします。ＲＰＡツールに関して、人手がかかっている手入力のところの対応に使えないかということですが、まさにＲＰＡツールの一つの特徴として、そういった用途に利用されております。","id":"exchange-045"},{"speaker":"あくつ委員","kind":"提案","question":"それと、ＲＰＡの話は、まさにそういうものに適したことだということは、今改めて確認させていただきましたので、私もそういったご説明があった所管のほうにはお伝えして、ぜひ、御課とも相談をしていただいて、外注に出そうかとか言っていましたが、そういうものは逆に品川区のＤＸの中で、それこそＲＰＡ化していったほうがいいのではないでしょうかということでご提案をしたいと思いますが。","respondent":"横田情報推進課長","answer":"おくやみコーナーにつきましては、事前に何か情報を取ろうというところではなくて、実際に来ていただいて、機械にマイナンバーカードを当てまして、そこの当てたＩＣチップの４情報、氏名・住所・生年月日・性別を読み取って。","id":"exchange-046"},{"speaker":"あくつ委員","kind":"質問・要望","question":"そうすると、それでも書くよりは、あそこのおくやみコーナーは、別に行政書士の方は名前を書いてくれるわけではないので、サポートをするということなので、その場でデータを確認して、印字されたものを出すという話だと思うのですが。できれば、その先、今後、自宅から予約をした段階で、本人確認をして、情報を送っておけば、その方が行けば、もう既にそういった書類が一式そろっている。","respondent":"横田情報推進課長","answer":"委員ご提案の件ですが、今予定しているやり方をやってみて、どういうふうにできるかというのをいろいろ検証してみて、決めていきたいと考えております。","id":"exchange-047"},{"speaker":"山本委員","kind":"質問・要望","question":"その中で４点ほどお伺いしたいのですけれども、１つが、電子申請サービスの利用状況ですけれども、令和４年度から令和５年度にかけて大幅に利用が伸びているということで、とてもいいことだと思うのですけれども。これによって、自動化したりして、業務量が削減されたときの、例えば削減時間とかを測定するとか、そういったところが確認できるようにお考えなのかというところをお聞かせください。","respondent":"河西情報戦略担当課長","answer":"今現在では、先ほどご紹介した業務数、２３業務で新たに今年導入する予定なのですけれども、そちらに関しても、何らかの実績、どれくらい効果が出ているかというところ、こちらもどういった計算の仕方ができるか今検討中ですので、こちらも。","id":"exchange-048"},{"speaker":"山本委員","kind":"質問・要望","question":"それぞれご説明ありがとうございました。電子申請サービスですけれども、７万件を超える申請で、その分、窓口業務が減っているというのは、とても大きいなと思います。さらに進めていただきたいと思います。高齢者スマホ教室、ご説明ありがとうございました。そして、研修をされるということですけれども、これは何名ぐらいの方を対象に、何回ぐらいご予定されているのでしょうか。","respondent":"河西情報戦略担当課長","answer":"追加の研修になりますが、本日午後、２コマ実施予定になっておりまして、１コマ３０名です。なので、合計で６０名の研修になります。","id":"exchange-049"},{"speaker":"山本委員","kind":"質問","question":"３０名ぐらいということで、分かりやすく説明するには、それぐらいの人数が適切なのかなと思いながらも、全体の職員の人数からすると、やはりまだまだ多くの方々に使ってもらえるような環境を整えていくことが大事なのかなというところだと思いました。それに対する考え方とか、課題と感じていらっしゃるかどうか、どのようなことが課題かとか、コメントいただけるようでしたら、お願いします。","respondent":"河西情報戦略担当課長","answer":"そちらに関しても、我々、情報をキャッチしまして、効果的な使い方、一例を紹介しますと、プロンプト例のひな形の利用機能というのが最近になって上がりまして、よく使う質問のやり方、そういったものを。","id":"exchange-050"},{"speaker":"山本委員","kind":"質問・要望","question":"やはり使えば効果的だというところだと思いますので、ぜひ多くの職員の皆様に使っていただけるように、研修とともに、それ以外の様々な工夫を進めていただきたいと思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"塚本委員","kind":"質問","question":"当初、洗い出しというのを、このオンライン化を進めていく上で、各現場にどういうものがオンライン化できそうな業務ですか、手続ですかということで、出たのが最初に出ている１,２９６。結構な数増えているので、それをお聞きしたいのと、今後ともこういう洗い出しというのを定期的にやっていくと、まだまだ増えるよという見通しを持っていらっしゃるのか、そこについてお伺いします。","respondent":"河西情報戦略担当課長","answer":"ですので、今回一通り洗い出したつもりではありますが、ほかの区との差分がやはりどこかありますので、何が我々にはなくて、ほかの区はどういったことをやっているかというところ、こういったところを注視しながら、手続に関しても漏れがないか確認していきたいと考えております。","id":"exchange-052"},{"speaker":"塚本委員","kind":"質問","question":"今回は現場に改めて聞いたというよりは、そういう所管のほうでホームページを検証して、この追加の手続を洗い出したと、こういうことなのですか。","respondent":"河西情報戦略担当課長","answer":"具体的に申しますと、まず我々、情報部門のほうで手続を洗い出しまして、これは対象ではないですかという一覧を各課に配りました。その結果、これは違いますよというのを落としていただいて、最終的に集まったのが、この１,６６１になっているというところで、ご報告します。","id":"exchange-053"},{"speaker":"塚本委員","kind":"質問","question":"そこのところについて、なかなか所管だけでは洗い出し切れないところはあると思うので、現場のほうに、オンライン化できるような手続を対象に挙げていけるようなやり方というのは考えたほうがいいのかなとも思うのですが、今どのようにお考えですか。","respondent":"河西情報戦略担当課長","answer":"今、大田区から、どういうやり方を取られたかというお話を聞いております。ですので、それが品川区でも利用できるようであれば、まねさせていただいて、検討を進めていきたいと考えております。","id":"exchange-054"},{"speaker":"塚本委員","kind":"質問・要望","question":"ここで一覧表に出ている１８の業務の中で、随意契約とプロポーザルというふうに分かれているものがあって、随意になるのか、プロポーザルするのかというところの線引きは、どういう理由によるものかということと、情報提供依頼書（ＲＦＩ）、これを出していただいているということで、結局、これによって、対応可能事業者というふうにもなっていますが、この事業者が。","respondent":"横田情報推進課長","answer":"基本的に、令和７年度末までという短い期間になりますので、既存のベンダーも、今ある顧客以外は引き受けられないという事業者が多くて、それでも引き受けられるよと答えられたのがプロポーザルを実施しているというような形になります。","id":"exchange-055"},{"speaker":"塚本委員","kind":"質問","question":"そうすると、今あるものがどういうものかということがネックで、事業者がもう決まってきてしまうと、こういうことなのでしょうか。同じものをつくるなら、その仕様が公開されていれば、どの事業者でもできて、そこは純粋な価格競争で、よりよいところを選定するみたいな話があるのではないかと思ったりもするのですけれども、そこのところをお聞かせください。","respondent":"横田情報推進課長","answer":"システム移行が、今、カスタマイズだらけのシステムから標準仕様書に準拠したシステムになるということで、移行作業が非常に大変ということがございまして、そこで時間をどうしても要してしまうというところで。","id":"exchange-056"},{"speaker":"筒井委員","kind":"質問","question":"私からは、オンライン受付状況とか、電子決済のところで、５ページのスライドのところですと、４４５手続が、押印が必要であるため、オンライン化できなかったということで、それを省略可能とするということで、これも、４４５手続全部、押印を省略、完全に可能とするということでよろしいのでしょうか。","respondent":"河西情報戦略担当課長","answer":"こちら、４４５手続記載しておりますが、こちらの中でも、請求書、見積書以外の押印が必要なものがございましたら、そちらに関しては、今回のタイミングではオンライン化が難しいというものになりますので、あくまでも請求書と見積書に関係する手続ということで、ご回答します。","id":"exchange-057"},{"speaker":"筒井委員","kind":"質問・要望","question":"やはりオンライン化を進めるためには、脱炭素ということを国のほうでも言っておりますけれども、こうした押印もどんどん省略していっていただきたいと考えているのですけれども、区としても、このオンライン化を進めるために、そうした規制だとか、規則だとか、そうしたものの改正を関係機関とか国とかに要望するということはあるのでしょうか。","respondent":"横田情報推進課長","answer":"そのほかにつきましては、今これから取りかかるところなのですが、アナログ規制というのを国のほうでやっておりまして、その辺りで、どういったものがデジタル化できるのかというのを、これから調査をしてまいるところです。","id":"exchange-058"},{"speaker":"筒井委員","kind":"質問・要望","question":"ぜひ、どんどん進めていっていただきたいと考えています。大田区の話も出ましたけれど、特別区長会とかを通じて、そうしたオンラインの需要は非常に高まっているということで、ぜひ、そうしたところに対してお声がけをしていっていただきたいと考えております。よろしくお願いします。このことについて利活用していきますよということ、現時点で固まっているところがあれば、教えてください。","respondent":"横田情報推進課長","answer":"先ほどのあくつ委員のところと重複してしまうのですが、少し省略して、一応予定しているところがデジタル通知というところで、区民のスマホにデジタル的に通知するサービス。","id":"exchange-059"},{"speaker":"筒井委員","kind":"質問・要望","question":"広く捉えて、窓口にはキャッシュレス化が進んでいると思うのですけれども、端末自体が結構足りなくて、同時に来た場合、端末が１個しかないので、少しお待ちくださいということもあったので、ぜひ端末を増やしていただきたいなと思っているのですけれども、その点、お考えはいかがでしょうか。","respondent":"横田情報推進課長","answer":"キャッシュレス端末の台数を増やせないかですが、今現在、例えば、戸籍住民課ですとか、税務課ですとか、地域センター、大体１５～２０％ぐらいの利用率になっております。そこの辺りの利用率も含めまして、今後、台数を増やすかどうかというのを検討していきたいと思います。","id":"exchange-060"},{"speaker":"筒井委員","kind":"質問・要望","question":"ただ一方で、はじめてのスマホ体験教室とか、基本的なことを教えていただく教室というのは引き続きやっていただきたいのと同時に、やはりもうそろそろ慣れてきた高齢者に対して、基本アプリ講座というのをやると思うのですけれども、そうした応用編みたいな講座も増やしていただきたいのと、教室がせっかくあっても、現場まで行けないという方も当然いらっしゃるかと思うので、当然。","respondent":"横田情報推進課長","answer":"これまでやってきたスマホ教室のほかに、例えば、総務省のほうで、デジタル活用支援推進事業というところで、通信キャリアに委託してショップでスマホ教室を実施していたりですとか、東京都で高齢者向けスマホ普及啓発事業で、スマホの体験会とか、相談会とか。","id":"exchange-061"},{"speaker":"筒井委員","kind":"質問・要望","question":"そうした国とか都の事業の周知とかも、区の事業のついでに広報していただくとありがたいので、その点も含めて、ぜひ高齢者スマホ教室を進めていっていただきたいと思います。よろしくお願いします。そして、最後に、１９ページのテレワークの実施状況で、新システムでかなり便利になったというようなことが書いてあるのですけれども、この新システムというのは具体的にどのようなものなのでしょうか。","respondent":"河西情報戦略担当課長","answer":"ですので、予約する必要もないですし、取りにくる必要もないというところで、ハードルが下がったものになります。","id":"exchange-062"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/869098?Template=document&Id=6164#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":49850,"voices":160}},{"id":"r06-20240229-19","meetingId":"r06-cm02","date":"2024年2月29日","dateIso":"2024-02-29","committee":"災害・環境対策特別委員会","time":"午前１０時００分～午後 ２時３４分","status":"正式会議録","sourceType":"formal","overview":"災害・環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を60件抜き出しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"それと、別紙の１ページのところで、計画の位置づけというところに、今回の災害廃棄物処理計画が真ん中にありますけれども、発災した後に、品川区災害廃棄物処理実行計画というのをつくるということで、これがどういったものなのかというところで、記載を見ると、発災後に被災状況を見て、廃棄物の発生量とかを含めて具体的にやっていく計画なのかなというところを思うのですが、実際のところ。","respondent":"平原防災課長、品川品川区清掃事務所長","answer":"もう一つ、こちらの資料にあります処理実行計画についてですが、現在の災害廃棄物処理計画につきましては、あくまで平時からの想定という形なのですけれども、実際に発生いたしましたら。協定についてご説明いたします。こちらは、まず災害ごみに関しましては、地域の近いところ、地区仮置場というところに持っていくという流れになります。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"実際に起きたときに、区民としても、どう出したらいいのかというところもあると思うので、そこを伺いたいと思います。それで、この表の下に、発災後７２時間後には通常収集を再開予定だということで書かれているのですが、これが本当にできるのかなと思うのですけれども、能登半島地震の状況を見ていると、被害状況を確認するのも相当時間がかかっていたと思うのです。","respondent":"品川品川区清掃事務所長、平原防災課長","answer":"要するに、被災によって出たごみについて区分けをしています。それから、２つ目です。７２時間で通常のごみ収集ができるかどうかというところですけれども、これは一番、道路啓開が大きく影響してくるところかと思います。ご質問いただきましたうち、がれきの町丁目のところの算定というところのお話ですが、こちらの絵は、前回の被害想定、平成２４年の東京都が出した被害想定のところで、町丁目ごとの建物の倒壊の見込みといったところがございまして。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問","question":"今の計画自体が、東京都の平成２４年の想定でやられているということなので、この発生量も変わってきていますけれども、処理計画自身の見直しというのは考えていらっしゃるのか、発生量が変わってくるので、いろいろ見直すところが出てくるのかなと思うのですが、いかがでしょうか。","respondent":"平原防災課長","answer":"次年度以降はその地域防災計画に基づきまして、各種計画の見直しを考えてありますので、災害廃棄物処理計画につきましても、見直していくということを考えてあります。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"ただ、発生量が多い町会というのがマップでも示されていますけれども、赤いところが幾つか、２万５,０００ｔ以上というのが１０個ぐらいありますが、こういった町会では、地区仮置場というのは多く配置するという考え方でやるのかどうかというのと、地区仮置場は家の近くにないと、すぐ出せないということになると思うので、町会に１つ設置していくような感じになるのかなと思っているのですが。","respondent":"平原防災課長","answer":"それからもう一つが、地区仮置場、公園の配置計画といったところですが、こちらは先ほどご説明させていただきましたとおり、処理実行計画という中で、実際にどのぐらいの量が発生するかによって、どのぐらいの箇所数が必要かといったところもありますので、そういう中で。","id":"exchange-004"},{"speaker":"のだて委員","kind":"質問・要望","question":"分別の徹底のところでは、ハンドブックが配付をされているということで、そうした周知はしていっていただきたいと思うのですが、備蓄もしているところがなかなかないかなというところもあったりする中で、廃棄物まで平常時に気が回るという方もなかなかいらっしゃらないと思うので、これはぜひ、さらに周知を進めていっていただいて、今回、この計画も見直しをするということですから。","respondent":"平原防災課長","answer":"地区仮置場の件ですけれども、地域センター管内に１つということは、そこについてはまず最低限のところということで、それだけ開くということを考えているところですが、片づけごみという性格上、継続的に出てくるというよりは、一時的に。","id":"exchange-005"},{"speaker":"吉田委員","kind":"質問・要望","question":"そういうことを防ぐ努力はしていただきたいと思うのですけれども、その辺の対応はどのようにお考えか伺います。処理現場の周辺環境等への配慮というところでは、先ほどの、誰かが仮の仮で置いたところが、置場のようになってしまうということについて、これは区民やボランティアとの協力の混乱防止のところにも関係するかと思うのですけれども、その辺をどのようにお考えか伺います。","respondent":"平原防災課長","answer":"そういったところで、そのようなことにならないように、先ほど来ご説明しています廃棄物処理計画に基づきますマニュアルであるとか、そのような発想で全て立てしていますので、道路放置などが発生しないよう、全てやらせていただきたいという計画にしております。","id":"exchange-006"},{"speaker":"吉田委員","kind":"質問・要望","question":"一気にすばらしい答えが出る問題ではないということを私も分かりながら、ぜひ考えていただきたいということで伺いました。し尿のことも、結構地方のほうで土の地面がいっぱいあるところは、割と皆さんのお庭とかも掘って、ご自分のご家庭のし尿とかは処理されたというのも伺っておりますが、そういう経験をされた方が、東京ではどうですかねと心配してくださるのです。本当にそうだと思います。","respondent":"平原防災課長","answer":"説明会というお話でございましたけれども、災害廃棄物の説明という形でしたら、逆にふだんの心がけという形のところになってしまいまして、少し現実的ではないと。","id":"exchange-007"},{"speaker":"吉田委員","kind":"質問","question":"最後にします。防災学校での内容は、私の身近で参加された方は、すごくいい内容だと評価しています。何かのときにご質問いただいたとき、この間こういうのが配られたでしょうと言うと、えっという感じです。探せば、ありましたというご報告もあるのですけれども、配られた資料を有効に活かすためにも説明会は有効ではないかと思うのですが、その辺についてもう一回お答えください。","respondent":"平原防災課長","answer":"どうしても個別にという形になりましたら、なかなか全てに対応できるということが難しいので、様々そういったところ、先ほどもご紹介させていただきました訓練もそうなのですけれども、そういったところを使いながら。","id":"exchange-008"},{"speaker":"吉田委員","kind":"質問・要望","question":"これからオンラインを検討されるということであれば、ぜひそれは積極的に進めていただきたいのですけれども、オンラインに参加できる方ばかりではないということがあって、どうなのでしょう。地域の中でやってくれれば参加できるのにと。これは要望ですので、ぜひご検討いただければと思います。もし何かコメントがあったらいただきたいのですけれども、私からは要望といたします。","respondent":"平原防災課長、品川品川区清掃事務所長","answer":"そういったところも含めまして、今、個別の対応というお話もございましたけれども、なかなか人員的にも、全てというのは難しい現状でもありますので、どのようなやり方がいいか。説明会のお話ですけれども、少し気になるのが、平時のごみの分別と混同してしまうといけないなというところが非常に気になるところで、防災という観点の中で説明をしていくというところは非常に大事なところかなと思います。","id":"exchange-009"},{"speaker":"ゆきた委員","kind":"質問","question":"令和５年度の地域防災計画では、応急仮置場についても候補地が全公園となりましたが、このようになった経緯についてお聞きできればと思います。","respondent":"平原防災課長、品川品川区清掃事務所長","answer":"それを具体的に、地区仮置場でどのように使うか、一次仮置場でどのように使うかというのは、面積要件等々もありますので、そこに応じて考えていくということにしておりますので。一定程度限定したような形で、とにかく被災の状況によって、どこにするかというところを選択していく、そのような流れになるかと考えております。","id":"exchange-010"},{"speaker":"ゆきた委員","kind":"質問","question":"もう１点なのですけれども、品川区災害廃棄物処理計画の中で、最後の部分のところに、区が実施する教育訓練の内容として挙げられているのが４つありまして、年度当初の本計画の読み合わせ、２つ目が職員研修の講習会、３つ目が情報収集訓練、４つ目が図上訓練となっておりますが、先ほど天王洲公園での訓練ということもございましたけれども、今の実施状況といったところでお聞きできればと思います。","respondent":"品川品川区清掃事務所長","answer":"訓練というところですけれども、事実上、１月に行いました天王洲のところが初めてという形です。","id":"exchange-011"},{"speaker":"ゆきた委員","kind":"意見","question":"大きな災害は、急に来て、急に対応せざるを得ないというのが現実だと思います。やはり訓練だと思いますし、災害廃棄物に対する情報収集訓練、図上訓練を行っているということも、今回の天王洲訓練のこともそうですが、発信していくことで、区民への啓発になると思われますので、こういった活動をしているというのも、うまく情報発信していただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"澤田委員","kind":"質問・要望","question":"私が聞きたいのは、災害廃棄物の仮置場の候補地は発災時の状況に応じて検討を行うと書かれていますし、今までの説明もそうですけれども、仮置場が決定するのは発災したときだと思うのですが、どこが地区仮置場になったとか、応急仮置場になったというアナウンスはどのようにしていかれるのかということと、あとは、どうやって示すのか、それをどうやって周知していくのかということを教えていただきたいです。","respondent":"平原防災課長","answer":"区民に対してお知らせするのは地区仮置場の情報ですけれども、地区仮置場につきましては、災害広報の一つとして、別にこれだけではなく、様々な支援情報も含んでなのですが、区の、若干抽象的な言い方になるのですけれども、全ての媒体を使ってやることになっておりますし。","id":"exchange-013"},{"speaker":"澤田委員","kind":"質問","question":"発災時の情報はどのように入手すればいいかというのも含めて、ご説明していったらいいのではないかと思うのですけれども、それについて、区の考えを教えてください。","respondent":"平原防災課長","answer":"地域の訓練というところでは、例えば避難所訓練の場で、トイレというものは各避難所単位におきまして、やりたいというお話もいただいているところですので、それを決めていく段階のときに、防災課の職員から、トイレの考え方あるいは使い方。","id":"exchange-014"},{"speaker":"澤田委員","kind":"質問・要望","question":"分かりました。トイレの大事さとかだけではなくて、例えば捨てる方法とかいろいろ、一歩踏み込んで、もう少し先のことまで、処理の仕方とかまで含めて、町会の方が説明できるようにというか、出前訓練というのもやっていらっしゃるので、それも活用しながらになるかとは思いますが、町会の方たちがそれぞれ説明できるような形に落とし込めるといいなという要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"こしば委員","kind":"質問・要望","question":"少し細かいことも含めて確認といいますか、質問をさせていただきたいのですけれども、片づけごみの対象は、損壊した家屋から排出される家財道具（通常の粗大ごみは除く）と書かれているのですが、例えば、損壊という定義も分からないところもあるのですけれども、損壊はしていないが、家屋の中で置かれていたたんすが倒れて破損した。こういったものは片づけごみの対象になるのかどうか。","respondent":"平原防災課長","answer":"こちらの資料３のところには、損壊家屋からという形で書かせていただいているところですけれども、何らかの被害を受けたといったことですので、動産被害も含んでいるというご理解をいただければと思います。","id":"exchange-016"},{"speaker":"こしば委員","kind":"質問・要望","question":"かなり格差があります。町会でも、役員も少ないところもあります。かなり限られてくると思いますけれども、その辺り、何かしら区のほうで、もちろん共助であるならば、当然地域でそういった人員を確保していかないといけないのでしょうけれども、なかなかそれが難しいというのが現状ですので、区で何かその辺りのお考えといいますか、サポート体制みたいなものがあるならば、教えていただきたいと思います。","respondent":"平原防災課長","answer":"あるいは、そういう必要のないところでは、別な観点でのボランティアが行くとか、そういう濃淡をつけながら対応するということを、第一義で考えているところです。","id":"exchange-017"},{"speaker":"こしば委員","kind":"質問・要望","question":"今、ボランティアを地域によっては集中的に派遣するといったお示しもいただきましたけれども、地域、町会の中での人を増やしていくということが、体力のある人を増やしていくということが課題でもあると思いますので、町会の中でそういったことを話し合っているところもあると思いますけれども、なかなかそこまで話が行き当たらないというところもありますので、本来これは多分、区政協力委員とか。","respondent":"平原防災課長","answer":"委員ご指摘のとおり、地区のてこ入れといいましょうか、ご支援といいましょうか、そういったところは非常に重要だと考えてございまして、私どもは、例えば次年度ですけれども、マンション防災の考え方を大きく拡充して、マンションにお住まいの方々に。","id":"exchange-018"},{"speaker":"須貝委員","kind":"質問","question":"だから、そういう意味で、地域を主体にして考えてほしい。ただ、１点だけ、毎回忸怩たる思いなのですけれども、瓦礫の発生量とかごみ発生量が、想定をどんどん減らしています。なぜなら、これ以上のものが来たらどうするのですか。全く対応できないではないですか。どんどん品川区、大都会は安全なのだなという、逆に変な認識を持たれませんかと僕は思ってしまうのですが、それだけお答えください。","respondent":"平原防災課長","answer":"そうはいいながら、災害がそのとおり、１３２万ｔ発生するのかという問題は確かに現実としていますので、私どもはここを一つの基準として、そういう意味で、いかようにも対応できるような形、一つのあくまで基準として、対応できるような計画という形で活動を考えてありますので。","id":"exchange-019"},{"speaker":"須貝委員","kind":"質問・要望","question":"そのとおりで、今、我々が歩いていても、鉄骨・鉄筋の建物が多いです。それは分かります。その地域、例えば大崎地区へ行けば、皆さん、まず大丈夫だと。それはそのとおりです。それは人間として。だから、それは手段として考えていただきたいと思います。ただ、悔しくて、想定を毎回下げられて、変に安全なような錯覚を起こしかねないので、別にこれは意見だけなので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"新妻委員","kind":"質問・要望","question":"私の認識不足ですが、災害廃棄物に関しての協定を結ばれているのは、この１者が初めてで、ほかにもあるのかということをお伺いしたいと思います。このカムズがどのような動き、どういうことをやっていただくのか、どの段階のフェーズからカムズが動かれることを想定しているのかということを教えていただきたいと思います。","respondent":"品川品川区清掃事務所長","answer":"ただ、基本的には災害廃棄物という部類に関しては、特別区で清掃業者と協定を結んでいるとか、そういうものがありますので、ほぼそちらで対応は可能かとは思いますが、区としてもそういう人材確保については、今進めているところの一つとして、カムズと今回やったです。","id":"exchange-021"},{"speaker":"新妻委員","kind":"質問","question":"流れが分かりました。１者で協定がどうなのかなというところが心配だったのですが、そこはしっかり特別区でも連携をしているということで、品川区としては、この１者の協定で対応していけるという判断の下での、この協定というところでよろしいのでしょうか。","respondent":"品川品川区清掃事務所長","answer":"これはさすがに廃棄物の量、状況等によりますので、現在このカムズの中で対応できるということまでは言い切れないという状況です。","id":"exchange-022"},{"speaker":"新妻委員","kind":"質問・要望","question":"もう１点、周知のところで、こういう考え方があるというところが、地域、町会を中心にしっかりと行っていただきたいと思うのですが、こういうところの具体的なお知らせをする場が、今、決まっているのかどうかというところがあれば、教えていただきたいと思います。","respondent":"平原防災課長","answer":"ただ、先ほど言いましたとおり、次年度、地区防災計画というものを、全ての地区でいきなりということは難しいのかもしれないですけれども、そのお話をする中で、地区のリスク、あるいは、地区に内在しているような災害時の活動といったところもご説明させていただきながら。","id":"exchange-023"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"何点かお伺いしますが、まず１点、先ほど被害想定の話で、少しずつ数が下がっていて、これでいいのだろうかという話があったと思うのですが、明確に行政から示していただきたいのですけれども、そもそもそれぞれの防災に関する施策というのは、被害想定の数を下げるためにやっていらっしゃるのだと思っていますので、そこで被害想定が下がってしまっていいのだろうかというところに対して。","respondent":"平原防災課長","answer":"その結果、今回、前回の平成２４年想定に比べまして、品川区の場合は減ったですが、逆に２３区の一部地域では、１０年前より被害想定が増えたという地区も出ているのは事実ですので、そういった成果というのは、私どもも地域を回って説明させていただいた際には。","id":"exchange-024"},{"speaker":"せりざわ委員","kind":"提案","question":"私もマンション防災を一つキーワードに、町会加入とかということをいろいろ提案してきたので、ぜひ進めていただきたいと思うのですが、応援している一方で、今のお話、マンションにとって地域とのつながりが、こんなことが大切ですということを教えていくというお話があったと思うのですが、正直なところ、それだけだとなかなか、いわゆる共助というところ。","respondent":"品川品川区清掃事務所長、平原防災課長","answer":"そこのところで、まだ実際に現実上、要求した車が配車できるかとか、そういう部分が、２３区の中でも少し調整ができていない部分もあったりしますので、こういう部分からしても、もう少し車の確保については、協定等を結んでいくとか。今まではマンション単位でしたけれども、地域と一緒にやっていただくということの重要性といったものを、次年度以降のマンション防災の一つの考え方の柱として進めていく所存です。","id":"exchange-025"},{"speaker":"つる委員","kind":"確認","question":"災害廃棄物処理計画ですが、ざっとしかまだ確認できていないのですけれども、災害廃棄物処理計画の中に動物に関する記述があるのか教えてください。","respondent":"平原防災課長","answer":"計画中に、特に動物というような形で特定して記述したものはございません。","id":"exchange-026"},{"speaker":"つる委員","kind":"質問","question":"いろいろ見る中では、例えば、この別紙の中でもあるのですが、発災後の実行計画という中に、例えば反映していくものなのかどうかということも含めて、あとは、計画そのものの改定のタイミングとか、そういったときに、動物に関する記述等についての記載を明記していくという、現段階での考え方とか方向性があれば、教えてください。","respondent":"平原防災課長","answer":"委員ご指摘のとおりでございまして、まず、動物の死骸、一般廃棄物という扱いになりますし、いわゆる事業系から出たものについては事業系のごみという扱いになりますけれども、ただ、実際に災害時にペット、愛玩動物がお亡くなりになったというか、死骸となった場合に、その後。","id":"exchange-027"},{"speaker":"つる委員","kind":"質問・要望","question":"それはそれできちんとやっていただきたいと思うのですが、逆に言うと、計画にないことはできないのかもしれませんが、今、記載がないので。逆に、今、さっき少し揺れが、千葉の震度３があって、ここも少し揺れた。倒壊した家屋でペットが亡くなってしまった。起因するものが災害だったとしても、そうしたペットについての扱いは、現段階でどうなるのでしょうか、教えてください。","respondent":"品川品川区清掃事務所長","answer":"路上等、飼い主のいない動物に関しては、何か一定の考え方が必要になるかなとは思いますが、原則、今やっている道路上とか、そういった対応をどういうふうに災害時において拡大をしていくかというようなことを、次回計画に対して検討していきたいというふうに思います。","id":"exchange-028"},{"speaker":"つる委員","kind":"質問・要望","question":"犬だけでも１万４,０００弱ぐらい、登録されているだけでもあるわけですし、残念ながら公道上等で亡くなってしまう予算としてもそれだけ確保しているということを考えれば、発災時にはそういったことも、もっと多くなっていくのだろうというところでは、ぜひチラシだとか、何かの形で、少しでも早く区民に周知できるようなことは、ぜひ考えていっていただきたいと思います。","respondent":"品川品川区清掃事務所長","answer":"やはりそういった課題点もありますので、次期計画改定に向けて検討していくことと、周知の仕方等についても同様にやっていきたいと、このように思っております。","id":"exchange-029"},{"speaker":"鈴木副委員長","kind":"質問","question":"例えば、地区仮置場にしても、割と早くに、３日後とか、２４時間後とか、一時仮置場でも３日後ということでの仮置場が選定されるということからすると、おおよそこれくらいのごみは、想定されたものが出ているので、そのごみの集積場所は、これぐらい平米が必要だということも出されていると思うので、そういうところでは、事前にここのところが仮置場になりますよというところが。","respondent":"平原防災課長","answer":"午前中の答弁の中でもお話しさせていただきましたけれども、まず、地区仮置場につきましては、１３地区に１か所ずつと、それから地区が広い大井第一、大崎第一地区については、もう１か所ずつということで、１５か所ということでやっているのですけれども。","id":"exchange-030"},{"speaker":"鈴木副委員長","kind":"質問","question":"決められていたら、多分、地域の方も、ここら辺、ここだということがある程度想定できていると、近隣の方もそういう思いになれるのではないかなと思うのですけれども、そこら辺のところはどうなっているのかと、それから、一時仮置場は、ここのところでも、１３.６万m2と書かれているのですけれども、これは多分、前の想定からされている２５３m3に対しての平米数となっているので、これも多分、先ほど。","respondent":"平原防災課長","answer":"地区仮置場１５か所、先ほど検討中という答弁をさせていただきましたけれども、今、実際に、具体的にそこが仮置場として本当に活用できるのかどうかといったところを、１月１８日でしたけれども、検証を行っているところですので。","id":"exchange-031"},{"speaker":"鈴木副委員長","kind":"質問・要望","question":"だけど、ここで初めて見せていただいて、瓦礫のほうは１３０万トンということですけれども、片づけごみは３万４,８００トンということで、何桁も少ない状況だったので、私は至るところに片づけごみなども置かないと間に合わないような状況になっているのかなと思いきや、１３地区内に１か所ずつぐらいで何とか足りるというのが現実なのかなということは、今、改めて認識したという状況なのですけれども。","respondent":"平原防災課長、品川品川区清掃事務所長","answer":"必ず開くのが１５か所であるというような形で、そこから状況に応じてさらに増やしていく必要があるのかとか、あるいは期間的にも、初動で３日目には１５か所開くというような方向で、今、検討を進めているのですけれども。し尿は、今は完全に委託化をしておりますので、２３区の災害対策を通じて、し尿収集車を配備するというような状況になろうかと思います。","id":"exchange-032"},{"speaker":"鈴木副委員長","kind":"質問","question":"ということは、災害用トイレと、簡易トイレは別のもの、何かちょっと分からないのですけれども、簡易トイレをこれから１人２０個ずつ配布されますけれども、そういう簡易トイレは、全くの燃えるごみと同じように出してしまっていいということなのでしょうか。それで、この災害用トイレの分別排出は、分別収集する必要というのは何を差しているのか、それももう少し教えてください。","respondent":"品川品川区清掃事務所長","answer":"ですので、分けてし尿で収集する部分、それから、残った部分を可燃ごみで収集する部分と、そのような形になっていくかと思います。","id":"exchange-033"}]},{"id":"topic-02","title":"品川区地域防災計画の修正","agenda":"品川区地域防災計画の修正","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"この間、説明して、報告していただいてきておりますけれども、その中で、その後、何か変更になったところとかがありましたら、伺いたいと思います。それと今回、２月５日に防災会議が行われたということで、ここでの意見とかがありましたら、どういった議論があったのかというところを伺いたいと思います。","respondent":"平原防災課長","answer":"先ほどの私の説明のところで、今後こちらでというふうなお話をさせていただきましたが、こちらについて、地域防災計画という形でご説明するのは、やはり共助の中核組織である防災区民組織が中心となりまして、広く区民の方というと、地域防災計画の説明というよりは。","id":"exchange-034"},{"speaker":"のだて委員","kind":"質問・要望","question":"様々周知していただいて、区民が実際に発災時に困らないように周知をしていっていただきたいと思います。それと、防災会議で書面のやり取りがいろいろあったということで、もし紹介できるようなことがありましたら、どういった意見があったのか伺いたいと思います。","respondent":"平原防災課長","answer":"東京都のところでは出たのですけれども、防災会議委員のところは、例えばインフラ会社とか、私どもが日常的に防災の意見交換を行っているところで、そういった場でいただいているものでございまして、分かりづらい説明をしてしまいまして申し訳ございませんでした。","id":"exchange-035"},{"speaker":"須貝委員","kind":"質問","question":"これによって災害関連死がなくならない。テントが足りない場合は、国の資金でホテルに宿泊もしていて、それでも足りない場合は、簡易ベッドを使って寝起きしているのが一般的で、体育館に大勢集めて雑魚寝をするような避難方法はとっていないというのが世界の通例のようですけれども、これ、なぜ日本は、このままずっとやっていると思うのですけれども、ご見解をお聞かせください。","respondent":"平原防災課長","answer":"ヨーロッパで例外的なところということで、他の地域では、局所的な災害はあったとしても、エリア全体が壊滅的な被害を受けるというようなものが少ないということで、避難者数の違いがまず大きなところで考えられるかなということが１点と、もう１つは、やはり人口規模です。","id":"exchange-036"},{"speaker":"須貝委員","kind":"質問・要望","question":"日本はこれだけ頻発しているのに、なぜかというのは、本当に疑問に思ったのです。やはりこういうことは、都のほうにも働きかけて、やはり、本当に大都市で人口密集しているわけですから、それなりの対応策は、被害を受けた人にとっては、やはり避難所は一番大事ではないですか。私は、都と連携して、何か対応策も考えていただきたいと思います。意見だけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"}]},{"id":"topic-03","title":"令和６年度の防災訓練の変更","agenda":"令和６年度の防災訓練の変更","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"それと、今回、水防訓練と避難施設開設訓練が、実践的な訓練にしていくということで、それは本当に今後の災害対応に向けていいことだと思うのですけれども、それも公開してもいいのではないかという気もするのですが、実際こういう実践的なことをしっかりやっていますよということもあるかと思うのですが、公開しない理由を改めて伺いたいと思います。","respondent":"伊藤災害対策担当課長","answer":"例年、消防署と連携をした訓練を行っておりますが、やはり消防署からも、しっかりと区と連携をした訓練を行いたいというような声も、また区からも。","id":"exchange-038"},{"speaker":"須貝委員","kind":"質問・要望","question":"今までどうしてもセレモニー的な、我々も見に行ってお客さんみたいな感じで見ていたのですが、そうではなくて、やはり見せる訓練より実践的な訓練をやってほしいし、そこにはいろいろな装備、設備なども必要ならやってほしいし、本当にすばらしい画期的な変更だと考えています。ぜひこれにも区からの予算を使って、より的確なというよりも、必要な訓練を実践していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"ひがし委員","kind":"質問・要望","question":"(1)の全般のところに、様々な人が参加しやすい防災訓練にするためにというふうな文言がありまして、当会派としましても、障害がある方が参加しやすい防災訓練の実施をというふうに要望させていただいているのですけれども、事業者による企画・運営支援などの新たな要素を取り入れた訓練の枠組みを構築と、具体的にどのようなことを検討しているのかという点がまず１点。","respondent":"伊藤災害対策担当課長","answer":"委員に先ほどおっしゃっていただきましたように、障害のある方も参加できるような訓練を、そちらの中の要素として入るか、また、別にしっかりとニーズに対応できるような形で訓練に参加ないしは見学をしていただいて。","id":"exchange-040"},{"speaker":"ひがし委員","kind":"確認","question":"取組として新たに区としてやりますということだったら、全部やってもいいのではないか、少しずつ取り入れられるところをという程度のところでやればいいのではないかと思うと、従来どおりですと初めから決められているのは、積極性として少し見えにくいかなと思ったので、準備の問題とか場所の問題等あるかもしれないのですけれども、従来どおり固定ですというような表記よりは。","respondent":"伊藤災害対策担当課長","answer":"ただ、来年度につきましては、試験的導入という形で、将来的には、全て、今やっていない訓練会場３か所を含めまして、１３会場で訓練をやり、また、こういった新たな要素を取り入れた訓練を実施していきたいと計画していますので、来年度につきましては、前回。","id":"exchange-041"},{"speaker":"ひがし委員","kind":"質問・要望","question":"ぜひ前向きにほかの地区にも広がるようにしていただければなと思いますので、こちらは要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"新妻委員","kind":"提案","question":"今、ひがし委員のほうから、各地区の防災訓練の話がありました。この事業者による企画・運営支援というのは、これは東京都が提案をしているものを活用して品川区がやるということでしょうか。そこを教えていただきたい。","respondent":"伊藤災害対策担当課長","answer":"今回の訓練につきましては、東京都の提案のものではございません。","id":"exchange-043"},{"speaker":"新妻委員","kind":"質問・要望","question":"そこをどう若い方を引き込んでいくのかは、課題を持っていらっしゃって、今回こういう形で組んでいただいたのかなと思っているのですが、事業者による企画・運営ということではなく、例えば、地域の中の若いＰＴＡの方とか、そういう方に声かけをしていただいて、例えば、マラソン大会を開催するに当たって、アイデアソンみたいなものを開催して。","respondent":"伊藤災害対策担当課長","answer":"基本的には、主体となるのは防災協議会となりますので、そちらと連携をしながら、どういった形で若い方、特に、親子世代を今回はターゲットにしてやろうと考えておりますが、より多くの方が参加していただけるのか、考えながら実施していきたいと考えています。","id":"exchange-044"},{"speaker":"つる委員","kind":"質問","question":"聞き漏らしていたらあれなのですけれども、この新たなほうの５地区で、事業者ですが、５地区それぞればらばらなのですか。一緒なのですか。私、聞き漏らしたのですけれども、全部同じ事業者が５地区全部を見るのか、それぞれの地区ばらばらなのか。さっき言いましたよということがもしあれば、それも含めて教えてください。","respondent":"伊藤災害対策担当課長","answer":"すみません、先ほどはお伝えしてございません。回答が漏れていました。もちろん日程は違いますけれども、１つの事業所に委託をしてやっていく予定です。","id":"exchange-045"},{"speaker":"つる委員","kind":"質問","question":"もう１４年前になるのですけれども、１４年前に、なかなか地域の防災訓練の参加者が少ないので、子どもたちが参加しやすいようなということで、ＮＰＯ法人が墨田区などもやっていて、あと、そなエリア東京の監修とかをされている法人があって、そういったところと連携したらどうですかと、今、改めて資料を見ながら思い出したのですけれども、そのようなイメージで合っているのかということで、当時は。","respondent":"伊藤災害対策担当課長","answer":"ただ、今回、事業所に依頼をするということで、まだどういったものになるかはこれからの検討事項になってくると思うのですが、もう少し規模の大きい委託事業になりまして、具体的なものを言うと、やはりゲーム性があって、少し大きなものになりますと、迷路。","id":"exchange-046"},{"speaker":"須貝委員","kind":"質問","question":"そのときは、やはり参加人数が増えたり、やはりほとんど知らないでそのままスルーしてしまう。スピーカーで流すではないですか。あれもほとんど聞こえないので、各町会長に頭を下げて、嫌だという人もいると思うのですけれども、１,０００軒ぐらいポスティングして、こういうイベントやるので、ぜひ参加するように町会から呼びかけてくださいというお願いをできればしてほしい。意見だけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"}]},{"id":"topic-04","title":"議会閉会中継続審査調査事項","agenda":"議会閉会中継続審査調査事項","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"職員の派遣をされているということで、今後の区の防災対策にぜひ生かしていただきたいと思うのですが、職員、行った方の感想とか、区に生かせるようなことがありましたら、伺いたいと思います。それと、物的支援のところで、輪島市と金沢市に支援をしたというところで、支援の要請があったということなのですが、何か品川区との関わりといいますか、要請があった理由が何かあるのかどうか伺いたいと思います。","respondent":"平原防災課長","answer":"物的支援の要請についてですが、この地震、１月１日ということもあったのですけれども、私どもと直接の関係を築かせていただいております福井県の坂井市に直ちにご連絡させていただいたところ、坂井市からは特に大きな被害がないということで。","id":"exchange-048"},{"speaker":"西村委員","kind":"質問","question":"１点、お伺いさせてください。被災宅地危険度判定なのですけれども、担当課をまたいで伺っていただいているのかなと思っていまして、応急危険度判定士を取得している職員の方が、今、何名ぐらいおられるのかということと、職員の方の資格取得が、任意なのか必須なのかも分かっておりませんで、職員の方々が、その辺り、庁内でどのような推進をしておられるのかお聞かせください。","respondent":"平原防災課長","answer":"ただ今、被災宅地の知見を持った人数が何名といったところの資料が手元にないものですから、申し訳ございませんけれども、資格取得は必須という形ではないのですけれども、その資格を持った人間で行ける者を、今回の災害が見えてきた段階でピックアップさせていただいて。","id":"exchange-049"},{"speaker":"西村委員","kind":"質問","question":"私も突然聞いてしまいましたので失礼してしまったのですが、そうやって任意で既に取得しておられる方が何名もいらっしゃるということがすごいなと改めて思っておりまして、その辺り、改めて伺えればと思いますし、また、先ほど、委員からの質問にもあったのですけれども、複数回実際にこの震災の直後に現地に出向いてくださった、その空気感だったり、悲惨な状態だというのは、区民の皆様とか、我々とか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"吉田委員","kind":"質問・要望","question":"公営住宅への受け入れで、これは一時提供ではないですか。でも、特に期限の定めなくというふうに、ぜひそうあっていただきたいと思うのですけれども、その辺について、何かあれば教えてください。","respondent":"中村都市環境部長","answer":"公営住宅をご利用していただくのは、被災を受けた方が、復興が進んで自宅に戻れるようになるというところが本来の趣旨ですので、ただ、期限の定めはございまして、原則半年、最長で１年です。","id":"exchange-051"},{"speaker":"吉田委員","kind":"質問・要望","question":"一定ルールは必要なのかなと思いますし、今おっしゃったとおり、基本的には、ご本人もふるさとに帰ってというか、それで再建をしたいと思っていらっしゃると思うのですけれども、期限があったとしても、個別にご事情、再建を目指したとしても、なかなか計画どおりにいかないとか、そういうことがあると思うのですけれども、その場合は、ご相談の上、延長とかしていただきたいと思うのですが。","respondent":"中村都市環境部長","answer":"一度入っていただいて、帰るあてがないのに出ていってくださいということはありませんので、その辺は事情をよく聞いて、話合いでしっかりと決定していきたいと思います。","id":"exchange-052"},{"speaker":"吉田委員","kind":"質問・要望","question":"安心いたしました。ぜひそのように進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"つる委員","kind":"確認","question":"すみません、総務委員会でもしかしたら質疑があったかもしれないですし、過去、そういった議論、確認、また資料等があると思うのですけれども、３の2)の物的支援の関係なのですが、無駄のないようにということで、支援があった物品についての支援品の輸送ということで品川区がやられているわけですけれど、この品目は、そもそも品川区が備蓄しているものからチョイスして送っている。そこを教えてください。","respondent":"平原防災課長","answer":"こちらにつきましては、いずれも区の備蓄品です。","id":"exchange-054"},{"speaker":"つる委員","kind":"質問","question":"はい、分かりました。そうすると、新たに買ってとかということではなくて、あるものの中で要請があった中から区が持っているもの、リスト等を最初に配って、これがあるからどうですかという、いろいろな聞き方があるかもしれませんけれども。","respondent":"平原防災課長","answer":"今回、輪島市にお送りさせていただきました物資につきましては、備蓄品ではありますけれども、午前中の答弁の中で、想定外にどこまでというような話の中で。品川区の備蓄品の中で、いわゆる有効期限のあるものについては有効活用というふうにやっておりますけれども、その有効活用品をこちらで提供させていただいておりまして、そういったところでいくと。","id":"exchange-055"},{"speaker":"つる委員","kind":"質問","question":"今回みたいに、こうやって支援のために使った場合、当然、アジャストの部分なのだけれども、想定外のところを想定するということを考えたときには、そこの部分を、品川区としては、どこかのそれなりのタイミングで備蓄しているということが、当然これはいいと思うのですけれども、逆に品川区が支援を受けるということも、これは重要な部分であろうかと思うのですが。","respondent":"平原防災課長","answer":"そういった意味で、今回、有効活用のところから支援させていただきましたので、区の備蓄数量という形では、災害対応そのものには対応できているという考え方でおります。","id":"exchange-056"},{"speaker":"つる委員","kind":"質問・要望","question":"なので、私が少し自分の勉強不足で質問したわけですけれど、そういったものを活用しているという、安心だよねということは、一方で区民に必要なのかなと思うのです。自分たち、今、在宅避難となっているから、どうやってそこに取りに行ったらいいのだろうというご質問などを聞くわけです。要望で結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"ひがし委員","kind":"提案","question":"輪島漆器青年会という方々が、高齢の方々がもう引退しなければというお話をしているのを聞いて、生産再開までのつなぎとなる仕事と資金が必要ということで、そういう展示会、即売会をやっているということで、前回、２７日までですか、たしか新宿区のほうでされていて、また、これから名古屋市とか大阪とか、それぞれのところでやるということを聞いて、区としても。","respondent":"平原防災課長","answer":"今回、大変申し訳ございません、総務委員会でご報告させていただいたということで、これ、所管自体は総務部のほうで行っておりますので、今回ご意見があったというようなことをしっかりと所管部署に伝えさせていただきまして、様々な支援につながるように。","id":"exchange-058"},{"speaker":"こしば委員","kind":"質問","question":"公営住宅の受け入れの件なのですけれども、こちらは４月２４日から受付を開始したということで、提供住宅が１０戸のうち、３件の申込みがあって、今、１件、入居を開始されているというふうに認識させてもらったのですけれども、そもそもこの公営住宅の、多分、区営住宅、都営住宅も含まれるかもしれませんが、こちらは被災地の方にはどのように案内をされているのでしょうか。","respondent":"中村都市環境部長","answer":"こちらは、区のホームページは当然載せておりますが、あと、東京都を通じて、被災地の石川県のホームページにも載せておりまして、品川区と石川県でお互いに見られて、リンクをしている、そういうような形になっております。","id":"exchange-059"},{"speaker":"こしば委員","kind":"質問","question":"区だけだと、なかなかそこにアクセスするのは難しいかなと思うのですけれども、なぜこれを聞くかといいますと、実は今日に至るまでの間で、民間のアパートなりマンションを持たれているオーナーの方々から、うちの空いている物件もあるから、もしよかったかどうかという話も実際に受けていまして、担当の所管の課長にもお話もさせてもらったことはあったのですけれども、こういったものは、例えば。","respondent":"中村都市環境部長","answer":"ただ、今は１０件提供している中で３件ということで、まだ今後、需要については様子を見てみないと分かりませんけれども、まずは公営住宅で対応するという形が適切なのかなというふうには考えております。","id":"exchange-060"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/302312?Template=document&Id=6650#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=19&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":57548,"voices":167}},{"id":"r06-20240229-10","meetingId":"r06-cm02","date":"2024年2月29日","dateIso":"2024-02-29","committee":"議会運営委員会","time":"午後 ０時３０分～午後 ０時３６分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を3件抜き出しています。","topics":[{"id":"topic-01","title":"その他","agenda":"その他","exchanges":[{"speaker":"須貝委員","kind":"意見","question":"さまざまご協力もありまして、一応完成しまして、今週の月曜日に安藤委員にお渡ししまして、あとは共産党で一部修正するのか分かりませんが、それで各会派にお願いに上がるという話は聞いております。今はそういう状況です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"},{"speaker":"安藤委員","kind":"提案","question":"通常の決議や意見書もそうだと思うのですけれども、私たちは須貝委員の協力も得て案文を、今、作っておりますけれども、皆さんにも提案者になっていただけるように調整や事前の情報提供もしまして、ぜひ議会として出せればいいと思っています。共産党としてその中に名前を連ねるというのはもちろん当然のことだと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、どのような決議や意見書でもそうだと思うのですけれども、やっぱりオール議会で出すのがベストだと思っているので、それに向けてまず案文を作っているということなのです。早い時期に皆様に案文を提示するので、議会としての対応を求められているところでもありますから、ぜひご検討いただきたいということで、今、案文を作成しています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/116834?Template=document&Id=5540#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":2146,"voices":21}}]);
